-- 补齐福建高中复习卡的周期律、课程级P0/P1知识，并加入对应原创母题。
-- 仅更新review复习系统；不修改独立小测链接或其内容。

alter table public.chem_questions
  add column if not exists usable_for_class_quiz boolean not null default true,
  add column if not exists usable_for_review boolean not null default true,
  add column if not exists usable_for_exam_sprint boolean not null default true;

update public.chem_knowledge_cards
set structured_content = jsonb_set(
  jsonb_set(
    jsonb_set(
      jsonb_set(
        structured_content,
        '{overview}',
        coalesce(structured_content->'overview', '[]'::jsonb) || $classify_overview$["四类基本反应按反应物和生成物的种类、数量分类；氧化还原反应按有无化合价变化分类，两条分类线可以交叉。"]$classify_overview$::jsonb
      ),
      '{sections}',
      coalesce(structured_content->'sections', '[]'::jsonb) || $classify_sections$[{"title":"四类基本反应与横向分类","summary":"先看反应前后“几种变几种”，再另开一条线检查化合价；同一反应可以同时拥有两个分类标签。","items":[{"label":"化合反应：多变一","rule":"两种或两种以上物质生成一种物质，叫化合反应。先数反应物种类，再确认生成物只有一种；“一种物质”指一种纯净物，不把计量系数当作种类数。","examples":["【示范：两种化合反应的氧化还原属性不同】2H₂+O₂=2H₂O是“多变一”，同时H、O化合价改变，所以也是氧化还原反应；CaO+H₂O=Ca(OH)₂也是“多变一”，但各元素化合价不变，所以不是氧化还原反应。"],"visualSteps":["数种类：多种→一种","另查化合价","得到两个分类标签"],"caution":"福建高中只要求用反应形式和化合价作基础分类，不按大学反应机理重新命名。"},{"label":"分解反应：一变多","rule":"一种物质生成两种或两种以上物质，叫分解反应。必须先确认反应物只有一种，再数生成物；受热只是常见条件，不是分解反应的定义。","examples":["【示范：碳酸钙受热】CaCO₃在加热条件下生成CaO和CO₂：反应物一种、生成物两种，判为分解反应；Ca、C、O化合价都不变，所以它不是氧化还原反应。"],"visualSteps":["一种反应物","生成多种物质","再查价态是否变化"],"caution":"不要看到“加热”就直接判分解；仍要按反应物、生成物种类数判断。"},{"label":"置换反应：单质换出单质","rule":"一种单质和一种化合物反应，生成另一种单质和另一种化合物，叫置换反应。置换前后必有单质元素从0价进入化合物、另一元素从化合物价态变为0价，所以中学常见置换反应一定属于氧化还原反应。","examples":["【示范：锌置换氢】Zn+2HCl=ZnCl₂+H₂中，Zn由0升到+2，H由+1降到0；形式上是“单质+化合物→化合物+单质”，同时电子由Zn转移给H⁺。"],"visualSteps":["认出单质与化合物","Zn升价、H降价","置换且氧化还原"],"caution":"有单质参加或生成不一定就是置换反应；还要满足“单质+化合物→单质+化合物”的形式。"},{"label":"复分解反应：离子交换伙伴","rule":"两种化合物相互交换成分生成另外两种化合物，叫复分解反应。水溶液中常因生成沉淀、气体或弱电解质而进行；元素化合价通常不变，所以通常不属于氧化还原反应。","examples":["【示范：盐酸和氢氧化钠】HCl+NaOH=NaCl+H₂O中，两种化合物交换离子组合，实质是H⁺+OH⁻=H₂O；所有元素化合价不变，判为复分解反应、非氧化还原反应。"],"visualSteps":["交换离子组合","出现水等推动力","价态不变"],"caution":"“通常不属于”针对课内典型复分解；分类时仍以题给反应和实际价态为准。"},{"label":"两套分类标准画成十字","rule":"纵向按形式分为化合、分解、置换、复分解；横向按化合价分为氧化还原、非氧化还原。先各自判断，再把结果放到交叉格，不能用一套分类替代另一套。","examples":["【示范：四个反应落入交叉格】2H₂+O₂=2H₂O落在“化合+氧化还原”；CaO+H₂O=Ca(OH)₂落在“化合+非氧化还原”；Zn+2HCl=ZnCl₂+H₂落在“置换+氧化还原”；HCl+NaOH=NaCl+H₂O落在“复分解+非氧化还原”。"],"visualSteps":["先判形式","再判化合价","交叉定位"],"caution":"四类基本反应不能覆盖所有高中反应；不符合四种形式时仍可继续判断是否为氧化还原反应。"}]}]$classify_sections$::jsonb
    ),
    '{workedExamples}',
    coalesce(structured_content->'workedExamples', '[]'::jsonb) || $classify_examples$[{"substance":"反应分类双通道","path":"先沿“几种反应物→几种生成物”通道判断四类基本反应，再沿“有无元素化合价改变”通道判断氧化还原；最后合并两个标签。","labels":["形式分类","价态分类","双标签核对"]}]$classify_examples$::jsonb
  ),
  '{checkpoints}',
  coalesce(structured_content->'checkpoints', '[]'::jsonb) || $classify_checks$["我能把四类基本反应与氧化还原分类画成两条可交叉的分类线。"]$classify_checks$::jsonb
),
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_CLASSIFY' and skill_id = 'H1_CLASSIFY'
  and not exists (
    select 1 from jsonb_array_elements(coalesce(structured_content->'sections', '[]'::jsonb)) entry
    where entry->>'title' = '四类基本反应与横向分类'
  );

update public.chem_knowledge_cards
set structured_content = $card_h1_periodic${"skillId":"H1_PERIODIC","version":2,"intro":"元素周期律不是一串需要硬背的箭头。先把“原子序数递增—核外电子排布周期性变化—周期表位置—元素及其化合物性质”接成因果链，再在同周期或同主族的前提下使用递变规律。","overview":["元素周期律：随着原子序数递增，元素性质呈周期性变化；根本原因是核外电子排布呈周期性变化。","原子序数=核电荷数=质子数；中性原子中还等于核外电子数。","周期序数看电子层数，主族序数通常看最外层电子数。","多数主族元素的最高正价可由主族序数判断，O、F不机械套最高正价规律；ⅣA—ⅦA族非金属的最低负价通常等于主族序数−8，O、F的常见最低负价分别为−2、−1。","同周期从左到右：半径总体减小，金属性减弱、非金属性增强；最高价氧化物对应水化物的碱性减弱、酸性增强，气态氢化物热稳定性总体增强。","同主族从上到下：半径增大，金属性增强、非金属性减弱；同族非金属气态氢化物的热稳定性总体减弱。","比较结论必须用匹配的事实落地：与水/酸反应、置换反应、气态氢化物热稳定性、最高价氧化物对应水化物的酸碱性。"],"visualSummary":{"kind":"compare","title":"元素周期律完整趋势图","groups":[{"label":"同周期 →","items":["层数不变·核电荷↑","半径总体↓","金属性↓｜非金属性↑"]},{"label":"最高价氧化物","items":["Na₂O→MgO→Al₂O₃→SiO₂→P₄O₁₀→SO₃→Cl₂O₇"]},{"label":"对应水化物","items":["NaOH→Mg(OH)₂→Al(OH)₃→H₂SiO₃→H₃PO₄→H₂SO₄→HClO₄","碱性减弱→两性→酸性增强","“对应”不等于一定能由氧化物直接加水得到"]},{"label":"气态氢化物","items":["同周期：SiH₄＜PH₃＜H₂S＜HCl","同主族：HF＞HCl＞HBr＞HI","热稳定性≠水溶液酸性≠还原性"]},{"label":"同主族 ↓","items":["电子层↑·屏蔽↑","半径↑","金属性↑｜非金属性↓","同族非金属简单氢化物：热稳定性↓、还原性通常↑"]},{"label":"价态与通式","items":["最高正价一般+1～+7（O、F不套）","最低负价通常−4/−3/−2/−1","RH₄/RH₃/H₂R/HR","最高正价+|最低负价|=8（限定相应主族非金属）"]},{"label":"证据与半径边界","items":["反应难易/置换/含氧体系/氢化物","同电子离子：核电荷↑半径↓","相同条件并排除氧化膜等干扰"]}]},"sections":[{"title":"从原子结构重新起步","summary":"周期律的根在核外电子排布，而不是表格位置本身。","items":[{"label":"元素周期律的因果起点","rule":"原子序数递增时，核电荷和核外电子数依次增加；最外层电子排布会按一定次序重复出现，因此元素性质不是简单直线变化，而是呈周期性变化。","examples":["Li与Na最外层都只有1个电子，化学性质相似；它们之间还隔着一整段性质递变。","【示范：²³₁₁Na、²⁴₁₁Na与周期性】两种Na核素都有11个质子，属于同一元素、占周期表同一位置；中性原子都排成2、8、1。与Li最外层结构相似，说明电子排布重复出现会带来性质的周期性。"],"visualSteps":["元素周期律的因果起点","质子数定元素","质量数定核素","电子分层","结构周期性"]},{"label":"原子核与核外电子","rule":"原子核含质子和中子；质子数决定元素种类。质量数A=质子数Z+中子数N。中性原子的电子数等于质子数。","examples":["²³₁₁Na含11个质子、12个中子和11个电子。","【示范：²³₁₁Na、²⁴₁₁Na与周期性】两种Na核素都有11个质子，属于同一元素、占周期表同一位置；中性原子都排成2、8、1。与Li最外层结构相似，说明电子排布重复出现会带来性质的周期性。"],"visualSteps":["原子核与核外电子","质子数定元素","质量数定核素","电子分层","结构周期性"]},{"label":"核素与同位素","rule":"具有一定质子数和中子数的一种原子叫核素；质子数相同而中子数不同的核素互为同位素。同位素属于同一种元素，在周期表中占同一位置。","examples":["¹H、²H、³H的质子数都为1，中子数不同，互为同位素。","【示范：²³₁₁Na、²⁴₁₁Na与周期性】两种Na核素都有11个质子，属于同一元素、占周期表同一位置；中性原子都排成2、8、1。与Li最外层结构相似，说明电子排布重复出现会带来性质的周期性。"],"caution":"质量数不同不代表元素种类不同；决定元素种类的是质子数。","visualSteps":["核素与同位素","质子数定元素","质量数定核素","电子分层","结构周期性"]},{"label":"电子层与最外层电子","rule":"高一阶段先用分层排布理解：电子优先从内层排起；最外层电子直接影响主要化学性质。","examples":["Na为2、8、1，易失去1个电子；Cl为2、8、7，易得到1个电子。","【示范：²³₁₁Na、²⁴₁₁Na与周期性】两种Na核素都有11个质子，属于同一元素、占周期表同一位置；中性原子都排成2、8、1。与Li最外层结构相似，说明电子排布重复出现会带来性质的周期性。"],"visualSteps":["电子层与最外层电子","质子数定元素","质量数定核素","电子分层","结构周期性"]},{"label":"原子与离子","rule":"原子失电子形成阳离子，得电子形成阴离子；质子数不变，因此元素种类不变。","examples":["Na→Na⁺+e⁻；Cl+e⁻→Cl⁻。","【示范：²³₁₁Na、²⁴₁₁Na与周期性】两种Na核素都有11个质子，属于同一元素、占周期表同一位置；中性原子都排成2、8、1。与Li最外层结构相似，说明电子排布重复出现会带来性质的周期性。"],"visualSteps":["原子与离子","质子数定元素","质量数定核素","电子分层","结构周期性"]}]},{"title":"结构怎样定位到周期表","summary":"先周期、再主族，最后用性质交叉检验。","items":[{"label":"周期表的基本框架","rule":"元素周期表有7个周期、18个纵列和16个族：7个主族、7个副族、1个第Ⅷ族（三纵列）和1个0族。短周期与长周期的元素数不同，过渡元素位于中部区域。","examples":["第3周期从Na到Ar共8种元素；第4周期开始出现过渡元素。","【示范：由2、8、7定位Cl】3个电子层确定第3周期，7个最外层电子确定第ⅦA族；最低负价通常为-1，最高正价线索为+7，但O、F等例外不能机械套用。再用HCl或最高价含氧体系交叉核对。"],"caution":"“18个纵列”不等于“18个族”，因为第Ⅷ族占3个纵列。","visualSteps":["周期表的基本框架","数电子层","数最外层电子","定周期和主族","价态与氢化物复核"]},{"label":"1～20号元素怎样分层排电子","rule":"先从内层向外层排；各电子层最多容纳2n²个电子，最外层通常不超过8个（第1层不超过2个）。高一常见1～18号元素可按2、8、8分层，K、Ca继续排入第4层。","examples":["Cl为2、8、7；Ar为2、8、8；K为2、8、8、1；Ca为2、8、8、2。","【示范：由2、8、7定位Cl】3个电子层确定第3周期，7个最外层电子确定第ⅦA族；最低负价通常为-1，最高正价线索为+7，但O、F等例外不能机械套用。再用HCl或最高价含氧体系交叉核对。"],"caution":"这里是前20号元素的分层模型；选择性必修中的能级交错要另按更精细规则处理。","visualSteps":["1～20号元素怎样分层排电子","数电子层","数最外层电子","定周期和主族","价态与氢化物复核"]},{"label":"判断周期","rule":"基态主族原子的电子层数等于周期序数。","examples":["电子排布2、8、2有3个电子层，位于第3周期。","【示范：由2、8、7定位Cl】3个电子层确定第3周期，7个最外层电子确定第ⅦA族；最低负价通常为-1，最高正价线索为+7，但O、F等例外不能机械套用。再用HCl或最高价含氧体系交叉核对。"],"visualSteps":["判断周期","数电子层","数最外层电子","定周期和主族","价态与氢化物复核"]},{"label":"判断主族","rule":"主族元素的最外层电子数通常等于主族序数；He是最外层2电子的特殊稳定结构。多数主族元素最高正价等于主族序数；ⅣA—ⅦA族非金属的最低负价依次为−4、−3、−2、−1，简单氢化物通式依次为RH₄、RH₃、H₂R、HR。","examples":["2、8、2对应第ⅡA族、最高正价通常为+2；2、8、7对应第ⅦA族、最低负价通常为−1并形成HR型氢化物。","【示范：由2、8、7定位Cl】3个电子层确定第3周期，7个最外层电子确定第ⅦA族；最低负价通常为-1，最高正价线索为+7，但O、F等例外不能机械套用。再用HCl或最高价含氧体系交叉核对。"],"caution":"O、F不套最高正价规律；相应主族非金属才可用“最高正价+|最低负价|=8”，H等特殊元素单独判断。","visualSteps":["判断主族","数电子层","数最外层电子","定周期和主族","价态与氢化物复核"]},{"label":"位置、结构、性质互推","rule":"题目可能给位置推结构，也可能给离子结构、最高价含氧化合物或气态氢化物反推位置。每得到一个结论，都用另一条条件核对。","examples":["某第3周期元素形成RH型气态氢化物、最低价为-1，可联想到第ⅦA族并用最高价含氧体系复核。","【示范：由2、8、7定位Cl】3个电子层确定第3周期，7个最外层电子确定第ⅦA族；最低负价通常为-1，最高正价线索为+7，但O、F等例外不能机械套用。再用HCl或最高价含氧体系交叉核对。"],"caution":"化合价规律只提供线索，最终还要结合题给元素范围和实际化合物。","visualSteps":["位置、结构、性质互推","数电子层","数最外层电子","定周期和主族","价态与氢化物复核"]}]},{"title":"同周期为什么这样变化","summary":"电子层数相同，核电荷逐步增加是主要矛盾。","items":[{"label":"原子半径总体减小","rule":"新增电子仍进入同一电子层，而质子数增加使核对电子的吸引增强，所以半径总体减小。","examples":["第3周期通常Na>Mg>Al>Si>P>S>Cl。","【示范：第3周期Na到Cl的三条证据】电子层数相同而核电荷增大，使半径总体减小、金属性减弱、非金属性增强；最高价氧化物对应水化物由强碱性经过两性再到酸性增强；SiH₄、PH₃、H₂S、HCl的热稳定性总体增强。"],"visualSteps":["原子半径总体减小","结构原因","半径与金属性","最高价含氧体系","气态氢化物稳定性"]},{"label":"金属性减弱、非金属性增强","rule":"半径减小、核吸引增强后，原子失电子越来越难、得电子能力总体增强。","examples":["Na与冷水剧烈反应，Mg与冷水反应较慢；Cl的非金属性强于S。","【示范：第3周期Na到Cl的三条证据】电子层数相同而核电荷增大，使半径总体减小、金属性减弱、非金属性增强；最高价氧化物对应水化物由强碱性经过两性再到酸性增强；SiH₄、PH₃、H₂S、HCl的热稳定性总体增强。"],"visualSteps":["金属性减弱、非金属性增强","结构原因","半径与金属性","最高价含氧体系","气态氢化物稳定性"]},{"label":"最高价氧化物对应水化物的酸碱性","rule":"同周期主族元素从左到右，最高价氧化物依次为Na₂O、MgO、Al₂O₃、SiO₂、P₄O₁₀（常简写P₂O₅）、SO₃、Cl₂O₇；对应水化物由碱性逐渐减弱，经过两性，再表现为酸性且酸性总体增强。","examples":["第3周期水化物序列为NaOH→Mg(OH)₂→Al(OH)₃（两性）→H₂SiO₃→H₃PO₄→H₂SO₄→HClO₄。","【示范：第3周期Na到Cl的三条证据】电子层数相同而核电荷增大，使半径总体减小、金属性减弱、非金属性增强；最高价氧化物对应水化物由强碱性经过两性再到酸性增强；SiH₄、PH₃、H₂S、HCl的热稳定性总体增强。"],"caution":"“对应水化物”是价态和酸碱体系的对应关系，不等于氧化物一定能直接与水反应；例如SiO₂不能直接与水生成H₂SiO₃。也不能拿Na₂O₂、HClO等非最高价体系乱排。","visualSteps":["最高价氧化物对应水化物的酸碱性","结构原因","半径与金属性","最高价含氧体系","气态氢化物稳定性"]},{"label":"气态氢化物的热稳定性","rule":"同周期非金属元素从左到右，原子半径总体减小、与H成键总体增强，因此简单气态氢化物的热稳定性总体增强。","examples":["第3周期可用SiH₄＜PH₃＜H₂S＜HCl表示总体热稳定性递增。","【示范：第3周期Na到Cl的三条证据】电子层数相同而核电荷增大，使半径总体减小、金属性减弱、非金属性增强；最高价氧化物对应水化物由强碱性经过两性再到酸性增强；SiH₄、PH₃、H₂S、HCl的热稳定性总体增强。"],"caution":"这里说的是受热分解难易，不等于水溶液酸性、还原性或沸点；比较对象必须是相应非金属的气态氢化物。","visualSteps":["气态氢化物的热稳定性","结构原因","半径与金属性","最高价含氧体系","气态氢化物稳定性"]}]},{"title":"同主族为什么这样变化","summary":"从上到下电子层增加，距离和屏蔽效应成为主要矛盾。","items":[{"label":"原子半径增大","rule":"每往下一周期多一个电子层，最外层电子离核更远，内层电子屏蔽更强。","examples":["【示范：卤素从F到I及其氢化物】从F到I电子层增加、半径增大，非金属性和单质氧化性总体减弱；H—X键总体变弱，所以HF＞HCl＞HBr＞HI的热稳定性依次减弱，而还原性总体增强。"],"visualSteps":["原子半径增大","电子层增加","非金属性减弱","氢化物稳定性减弱","还原性反向"]},{"label":"金属性增强、非金属性减弱","rule":"核对最外层电子的有效吸引减弱，失电子更容易、得电子能力总体减弱。","examples":["碱金属从Li到Cs金属性增强；卤素从F到I非金属性减弱。","【示范：卤素从F到I及其氢化物】从F到I电子层增加、半径增大，非金属性和单质氧化性总体减弱；H—X键总体变弱，所以HF＞HCl＞HBr＞HI的热稳定性依次减弱，而还原性总体增强。"],"visualSteps":["金属性增强、非金属性减弱","电子层增加","非金属性减弱","氢化物稳定性减弱","还原性反向"]},{"label":"相似性与递变性并存","rule":"同主族因最外层电子数相同而化学性质相似，又因电子层数不同而强弱递变。","examples":["卤素单质都能表现氧化性，但总体F₂>Cl₂>Br₂>I₂。","【示范：卤素从F到I及其氢化物】从F到I电子层增加、半径增大，非金属性和单质氧化性总体减弱；H—X键总体变弱，所以HF＞HCl＞HBr＞HI的热稳定性依次减弱，而还原性总体增强。"],"visualSteps":["相似性与递变性并存","电子层增加","非金属性减弱","氢化物稳定性减弱","还原性反向"]},{"label":"同族气态氢化物的热稳定性","rule":"同主族非金属元素从上到下原子半径增大，与H形成的化学键总体变弱，所以气态氢化物的热稳定性总体减弱；相应还原性常总体增强。","examples":["卤化氢热稳定性HF＞HCl＞HBr＞HI，而还原性总体反向增强。","【示范：卤素从F到I及其氢化物】从F到I电子层增加、半径增大，非金属性和单质氧化性总体减弱；H—X键总体变弱，所以HF＞HCl＞HBr＞HI的热稳定性依次减弱，而还原性总体增强。"],"caution":"热稳定性、酸性和还原性是三种不同指标，不能把同一组箭头通用到所有性质。","visualSteps":["同族气态氢化物的热稳定性","电子层增加","非金属性减弱","氢化物稳定性减弱","还原性反向"]}]},{"title":"考试比较的五步法","summary":"先限定对象，再选规律，再用事实证明。","items":[{"label":"第1步：定位","rule":"写出元素在同周期、同主族还是跨区比较；不先定位就不能机械套箭头。","examples":["【示范：Cl和S怎样用证据比较】先确认Cl、S同在第3周期，再由结构推出Cl非金属性更强；可用HCl比H₂S热稳定、HClO₄比H₂SO₄酸性强等证据。若改比O²⁻、F⁻、Na⁺、Mg²⁺，则进入同电子半径规则。"],"visualSteps":["第1步：定位","先定位对象","选择正确指标","事实验证结论","半径另分情形"]},{"label":"第2步：找结构原因","rule":"比较电子层数、核电荷和最外层电子，不只背结论。","examples":["【示范：Cl和S怎样用证据比较】先确认Cl、S同在第3周期，再由结构推出Cl非金属性更强；可用HCl比H₂S热稳定、HClO₄比H₂SO₄酸性强等证据。若改比O²⁻、F⁻、Na⁺、Mg²⁺，则进入同电子半径规则。"],"visualSteps":["第2步：找结构原因","先定位对象","选择正确指标","事实验证结论","半径另分情形"]},{"label":"第3步：选择指标","rule":"题目问金属性、非金属性、半径、化合物酸碱性还是反应强弱，证据不能混用。","examples":["【示范：Cl和S怎样用证据比较】先确认Cl、S同在第3周期，再由结构推出Cl非金属性更强；可用HCl比H₂S热稳定、HClO₄比H₂SO₄酸性强等证据。若改比O²⁻、F⁻、Na⁺、Mg²⁺，则进入同电子半径规则。"],"visualSteps":["第3步：选择指标","先定位对象","选择正确指标","事实验证结论","半径另分情形"]},{"label":"半径比较先分三类","rule":"同周期原子看核电荷递增；同主族原子看电子层递增；同电子微粒看核电荷，核电荷越大半径越小。同一元素通常阴离子＞原子＞阳离子，且正电荷越多半径越小。","examples":["O²⁻、F⁻、Na⁺、Mg²⁺都有10个电子，核电荷依次增大，所以半径依次减小。","【示范：Cl和S怎样用证据比较】先确认Cl、S同在第3周期，再由结构推出Cl非金属性更强；可用HCl比H₂S热稳定、HClO₄比H₂SO₄酸性强等证据。若改比O²⁻、F⁻、Na⁺、Mg²⁺，则进入同电子半径规则。"],"caution":"先确认电子层数和电子数是否可比，再使用简化规律。","visualSteps":["半径比较先分三类","先定位对象","选择正确指标","事实验证结论","半径另分情形"]},{"label":"第4—5步：用事实验证并查例外","rule":"用与指标匹配的事实支持结论：金属性看相同条件下失电子、与水或非氧化性酸反应的难易；非金属性可看与H₂反应、气态氢化物热稳定性、最高价含氧体系酸性或置换事实；最后检查氧化膜、钝化、离子和O/F等特殊对象。","examples":["证明Cl非金属性强于S，可比较HCl与H₂S热稳定性，或比较HClO₄与H₂SO₄酸性；不能只写“Cl在S右边”。","【示范：Cl和S怎样用证据比较】先确认Cl、S同在第3周期，再由结构推出Cl非金属性更强；可用HCl比H₂S热稳定、HClO₄比H₂SO₄酸性强等证据。若改比O²⁻、F⁻、Na⁺、Mg²⁺，则进入同电子半径规则。"],"caution":"反应快慢受温度、颗粒大小、氧化膜和酸的氧化性影响，只有条件可比时才能作元素性质证据。","visualSteps":["第4—5步：用事实验证并查例外","先定位对象","选择正确指标","事实验证结论","半径另分情形"]}]}],"workedExamples":[{"substance":"²³₁₁Na、²⁴₁₁Na与周期性","path":"两种Na核素都有11个质子，属于同一元素、占周期表同一位置；中性原子都排成2、8、1。与Li最外层结构相似，说明电子排布重复出现会带来性质的周期性。","labels":["质子数定元素","质量数定核素","电子分层","结构周期性"]},{"substance":"由2、8、7定位Cl","path":"3个电子层确定第3周期，7个最外层电子确定第ⅦA族；最低负价通常为-1，最高正价线索为+7，但O、F等例外不能机械套用。再用HCl或最高价含氧体系交叉核对。","labels":["数电子层","数最外层电子","定周期和主族","价态与氢化物复核"]},{"substance":"第3周期Na到Cl的三条证据","path":"电子层数相同而核电荷增大，使半径总体减小、金属性减弱、非金属性增强；最高价氧化物对应水化物由强碱性经过两性再到酸性增强；SiH₄、PH₃、H₂S、HCl的热稳定性总体增强。","labels":["结构原因","半径与金属性","最高价含氧体系","气态氢化物稳定性"]},{"substance":"卤素从F到I及其氢化物","path":"从F到I电子层增加、半径增大，非金属性和单质氧化性总体减弱；H—X键总体变弱，所以HF＞HCl＞HBr＞HI的热稳定性依次减弱，而还原性总体增强。","labels":["电子层增加","非金属性减弱","氢化物稳定性减弱","还原性反向"]},{"substance":"Cl和S怎样用证据比较","path":"先确认Cl、S同在第3周期，再由结构推出Cl非金属性更强；可用HCl比H₂S热稳定、HClO₄比H₂SO₄酸性强等证据。若改比O²⁻、F⁻、Na⁺、Mg²⁺，则进入同电子半径规则。","labels":["先定位对象","选择正确指标","事实验证结论","半径另分情形"]},{"substance":"由2、8、7推出Cl","path":"3个电子层→第3周期；最外层7个电子→第ⅦA族；易得1e⁻→常形成Cl⁻；与同周期S相比，核吸引更强、非金属性更强。","labels":["结构","位置","性质","事实验证"]},{"substance":"比较Na、Mg、Al金属性","path":"三者同在第3周期，电子层数相同，核电荷依次增大，半径总体减小，失电子能力减弱，所以金属性Na>Mg>Al。可用与水或酸反应的难易作证据。","labels":["先限定同周期","解释而非只背箭头","证据必须匹配"]},{"substance":"把第3周期化合物趋势接完整","path":"从Na到Cl，最高价氧化物对应水化物由NaOH的强碱性逐步过渡到Al(OH)₃两性，再到含氧酸且酸性总体增强；非金属简单气态氢化物由SiH₄到HCl热稳定性总体增强。两条证据都支持非金属性增强，但比较对象不同。","labels":["最高价含氧体系","碱性减弱","酸性增强","气态氢化物更稳定"]},{"substance":"卤素氢化物为什么向下更不稳定","path":"F、Cl、Br、I同主族向下原子半径增大，H—X键总体变弱，所以HF、HCl、HBr、HI的热稳定性依次减弱；与此同时还原性总体增强。先写指标名称，再写箭头，避免把稳定性和还原性混成一件事。","labels":["限定同主族","半径与键强","热稳定性递减","还原性反向"]}],"checkpoints":["我能说出元素周期律的根本原因。","我能由电子层数和最外层电子数定位主族元素。","我能解释同周期、同主族半径和金属性递变的原因。","我能画出最高价氧化物对应水化物的碱性—两性—酸性趋势。","我能分别判断同周期和同主族气态氢化物的热稳定性。","我能区分热稳定性、酸性、还原性三种指标。","我比较离子半径时会先看电子层和电子数。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h1_periodic$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_PERIODIC' and skill_id = 'H1_PERIODIC';

update public.chem_knowledge_cards
set structured_content = $card_h1_redox${"skillId":"H1_REDOX","version":2,"intro":"氧化还原看起来名词很多，其实所有判断都从同一件事出发：反应前后有没有元素化合价变化。化合价变化只是表面证据，电子转移才是本质。","overview":["有元素化合价升降，就是氧化还原反应；没有升降就不是。","升价=失电子=被氧化=发生氧化反应；对应物质是还原剂。","降价=得电子=被还原=发生还原反应；对应物质是氧化剂。","同一反应中失电子总数一定等于得电子总数，这是配平和计算的总开关。","同种元素既升又降叫歧化，不同价态归到中间价叫归中；缺项配平仍由电子、原子和电荷三重守恒锁定。"],"visualSummary":{"kind":"balance","title":"氧化还原电子天平","center":"e⁻总数相等","groups":[{"label":"升价｜失电子","items":["被氧化","还原剂","氧化产物"]},{"label":"降价｜得电子","items":["被还原","氧化剂","还原产物"]}]},"sections":[{"title":"先会正确标化合价","summary":"标错一个价，后面所有身份都会跟着错。","items":[{"label":"单质与常见固定价","rule":"单质中元素为0价；化合物中H通常+1、O通常-2；ⅠA族常+1、ⅡA族常+2。","examples":["Na、O₂、Cl₂均为0价；NaCl中Na为+1、Cl为-1。","【示范：SO₄²⁻和Na₂O₂怎样标价】SO₄²⁻中设S为x，有x+4×(-2)=-2，得S=+6；Na₂O₂中Na为+1，总和为0，得O=-1，说明过氧化物是常见例外。"],"visualSteps":["单质与常见固定价","先用固定价","列代数和","解未知价","查特殊物质"]},{"label":"总和规则","rule":"中性化合物中各元素化合价代数和为0；多原子离子中代数和等于离子电荷。","examples":["SO₄²⁻中S+4×(-2)=-2，所以S为+6。","【示范：SO₄²⁻和Na₂O₂怎样标价】SO₄²⁻中设S为x，有x+4×(-2)=-2，得S=+6；Na₂O₂中Na为+1，总和为0，得O=-1，说明过氧化物是常见例外。"],"visualSteps":["总和规则","先用固定价","列代数和","解未知价","查特殊物质"]},{"label":"常见例外","rule":"过氧化物中O为-1；金属氢化物中H可为-1；具体题目还要服从已知结构和电荷。","examples":["Na₂O₂中O为-1。","【示范：SO₄²⁻和Na₂O₂怎样标价】SO₄²⁻中设S为x，有x+4×(-2)=-2，得S=+6；Na₂O₂中Na为+1，总和为0，得O=-1，说明过氧化物是常见例外。"],"visualSteps":["常见例外","先用固定价","列代数和","解未知价","查特殊物质"]}]},{"title":"把四组概念接成一条线","summary":"过程词和物质身份词要一一对应。","items":[{"label":"化合价升高的一侧","rule":"元素失电子，被氧化，发生氧化反应；含该元素并提供电子的反应物叫还原剂；生成物叫氧化产物。","examples":["Fe²⁺→Fe³⁺+e⁻，Fe²⁺是还原剂。","【示范：Fe²⁺和Cl₂的身份链】Fe²⁺→Fe³⁺+e⁻：升价、失电子、被氧化，Fe²⁺是还原剂；Cl₂+2e⁻→2Cl⁻：降价、得电子、被还原，Cl₂是氧化剂。"],"visualSteps":["化合价升高的一侧","升价失电子","还原剂被氧化","降价得电子","氧化剂被还原"]},{"label":"化合价降低的一侧","rule":"元素得电子，被还原，发生还原反应；接受电子的反应物叫氧化剂；生成物叫还原产物。","examples":["Cl₂+2e⁻→2Cl⁻，Cl₂是氧化剂。","【示范：Fe²⁺和Cl₂的身份链】Fe²⁺→Fe³⁺+e⁻：升价、失电子、被氧化，Fe²⁺是还原剂；Cl₂+2e⁻→2Cl⁻：降价、得电子、被还原，Cl₂是氧化剂。"],"visualSteps":["化合价降低的一侧","升价失电子","还原剂被氧化","降价得电子","氧化剂被还原"]},{"label":"口诀必须有逻辑","rule":"“升失氧、降得还”只能帮助回忆，最终要能说出电子去了哪里。","caution":"氧化剂自身发生还原反应；还原剂自身发生氧化反应。","examples":["【示范：Fe²⁺和Cl₂的身份链】Fe²⁺→Fe³⁺+e⁻：升价、失电子、被氧化，Fe²⁺是还原剂；Cl₂+2e⁻→2Cl⁻：降价、得电子、被还原，Cl₂是氧化剂。"],"visualSteps":["口诀必须有逻辑","升价失电子","还原剂被氧化","降价得电子","氧化剂被还原"]}]},{"title":"电子转移与表示","summary":"不管用双线桥还是半反应，电子总数必须守恒。","items":[{"label":"电子数怎么算","rule":"单个原子的化合价变化数×发生变化的原子个数×该物质计量数，得到转移电子数。","examples":["1 mol Cl₂由0价变-1价，共得到2 mol e⁻。","【示范：2Na+Cl₂→2NaCl的双线桥】Na由0升至+1，2个Na共失2e⁻；Cl由0降至-1，一个Cl₂共得2e⁻。在线桥上标“失2e⁻”与“得2e⁻”，二者相等。"],"visualSteps":["电子数怎么算","标反应前后价态","计算变价原子数","标得失电子","电子总数相等"]},{"label":"双线桥思路","rule":"从反应物的变价元素连到生成物同种元素，标出“升/降、失/得、电子数”。电子不写正负号。","examples":["【示范：2Na+Cl₂→2NaCl的双线桥】Na由0升至+1，2个Na共失2e⁻；Cl由0降至-1，一个Cl₂共得2e⁻。在线桥上标“失2e⁻”与“得2e⁻”，二者相等。"],"visualSteps":["双线桥思路","标反应前后价态","计算变价原子数","标得失电子","电子总数相等"]},{"label":"半反应思路","rule":"分别写氧化半反应和还原半反应，使原子、电荷守恒后相加；酸碱介质中的H⁺、OH⁻、H₂O按条件补齐。","caution":"基础阶段先把变价原子和电子配平，再补其他元素。","examples":["【示范：2Na+Cl₂→2NaCl的双线桥】Na由0升至+1，2个Na共失2e⁻；Cl由0降至-1，一个Cl₂共得2e⁻。在线桥上标“失2e⁻”与“得2e⁻”，二者相等。"],"visualSteps":["半反应思路","标反应前后价态","计算变价原子数","标得失电子","电子总数相等"]}]},{"title":"氧化还原方程式配平","summary":"先电子，后原子，最后电荷和条件。","items":[{"label":"第1步：找变价","rule":"标出反应前后真正发生价态变化的元素，写出升降数。","examples":["【示范：FeS₂被O₂氧化】FeS₂中Fe由+2到+3失1e⁻，两个S由-1到+6共失14e⁻，每个FeS₂共失15e⁻；O₂中两个O共得4e⁻。最小公倍数60，先定4FeS₂和15O₂；再按酸性介质补齐，得到4FeS₂+15O₂+2H₂O=4Fe³⁺+8SO₄²⁻+4H⁺，左右总电荷均为0，并满足原子与电子守恒。"],"visualSteps":["第1步：找变价","标价","升降电子数","最小公倍数","补齐并守恒校验"]},{"label":"第2步：电子守恒","rule":"求升降电子数的最小公倍数，确定氧化剂、还原剂和对应产物的系数。","examples":["【示范：FeS₂被O₂氧化】FeS₂中Fe由+2到+3失1e⁻，两个S由-1到+6共失14e⁻，每个FeS₂共失15e⁻；O₂中两个O共得4e⁻。最小公倍数60，先定4FeS₂和15O₂；再按酸性介质补齐，得到4FeS₂+15O₂+2H₂O=4Fe³⁺+8SO₄²⁻+4H⁺，左右总电荷均为0，并满足原子与电子守恒。"],"visualSteps":["第2步：电子守恒","标价","升降电子数","最小公倍数","补齐并守恒校验"]},{"label":"第3步：补齐并检查","rule":"再配其他元素，最后检查原子守恒、电荷守恒、电子守恒和反应条件。","examples":["酸性MnO₄⁻与Fe²⁺反应中MnO₄⁻:Fe²⁺=1:5。","【示范：FeS₂被O₂氧化】FeS₂中Fe由+2到+3失1e⁻，两个S由-1到+6共失14e⁻，每个FeS₂共失15e⁻；O₂中两个O共得4e⁻。最小公倍数60，先定4FeS₂和15O₂；再按酸性介质补齐，得到4FeS₂+15O₂+2H₂O=4Fe³⁺+8SO₄²⁻+4H⁺，左右总电荷均为0，并满足原子与电子守恒。"],"visualSteps":["第3步：补齐并检查","标价","升降电子数","最小公倍数","补齐并守恒校验"]}]},{"title":"强弱比较、先后反应与守恒","summary":"复杂题仍然只是在电子转移主线上加条件。","items":[{"label":"氧化性和还原性","rule":"一般可由一个自发反应判断：氧化剂的氧化性强于氧化产物，还原剂的还原性强于还原产物。","examples":["【示范：MnO₄⁻先氧化谁】酸性体系中MnO₄⁻遇Fe²⁺和其他还原性粒子时，先由题给反应或强弱关系判断顺序；定量时把各还原剂失电子总数与MnO₄⁻得电子总数相等，不必追逐全部中间产物。"],"visualSteps":["氧化性和还原性","比较氧化还原能力","判断先后","汇总失电子","总电子守恒"]},{"label":"反应先后","rule":"同一氧化剂遇多种还原剂，通常先与还原性较强者反应；反之同理，但题给条件和动力学现象优先。","examples":["【示范：MnO₄⁻先氧化谁】酸性体系中MnO₄⁻遇Fe²⁺和其他还原性粒子时，先由题给反应或强弱关系判断顺序；定量时把各还原剂失电子总数与MnO₄⁻得电子总数相等，不必追逐全部中间产物。"],"visualSteps":["反应先后","比较氧化还原能力","判断先后","汇总失电子","总电子守恒"]},{"label":"多步电子守恒","rule":"中间产物可以不逐一求量，只要初态到终态的总失电子数等于总得电子数。","examples":["工艺流程和滴定计算常用总电子守恒。","【示范：MnO₄⁻先氧化谁】酸性体系中MnO₄⁻遇Fe²⁺和其他还原性粒子时，先由题给反应或强弱关系判断顺序；定量时把各还原剂失电子总数与MnO₄⁻得电子总数相等，不必追逐全部中间产物。"],"visualSteps":["多步电子守恒","比较氧化还原能力","判断先后","汇总失电子","总电子守恒"]}]},{"title":"歧化、归中与缺项配平","summary":"把特殊名字还原成化合价箭头，再用电子守恒和介质条件完成方程式。","items":[{"label":"歧化：同一价态向两边分流","rule":"同一种物质中的同一种元素，一部分化合价升高、另一部分化合价降低，叫歧化。该反应物同时提供和接受电子，所以它同时充当还原剂和氧化剂；配平时仍要求升、降电子总数相等。","examples":["【示范：氯气与冷的稀碱】Cl₂中Cl都是0价，反应后分别进入Cl⁻的−1价和ClO⁻的+1价；一份Cl降1价、另一份Cl升1价，得到Cl₂+2OH⁻=Cl⁻+ClO⁻+H₂O。"],"visualSteps":["Cl：0→−1与0→+1","一降一升各1e⁻","补OH⁻、H₂O并校验"],"caution":"只掌握福建高中常见歧化的价态与守恒判断；产物受温度、浓度等条件影响时以教材或题给条件为准。"},{"label":"归中：高低价态相向靠拢","rule":"同一元素的较高价态和较低价态共同生成中间价态，叫归中。先分别画“高价降低”和“低价升高”的箭头，再按电子得失相等确定两种反应物的比例。","examples":["【示范：铁的两种价态归中】2Fe³⁺+Fe=3Fe²⁺中，2个Fe³⁺各得1e⁻变Fe²⁺，1个Fe单质失2e⁻变Fe²⁺；得、失电子都是2e⁻，所以系数比为2∶1∶3。"],"visualSteps":["Fe³⁺：+3→+2","Fe：0→+2","2e⁻=2e⁻"],"caution":"“高价+低价一定归中”并非无条件成立；还要确认该反应在题给介质和条件下能够发生。"},{"label":"酸性介质缺项：先骨架、后水和氢离子","rule":"缺少H₂O、H⁺或电子时，先配变价元素和电子，再用H₂O补O、用H⁺补H，最后检查总电荷。每一步都服从题目明确给出的酸性介质，不能凭习惯把OH⁻写入最终式。","examples":["【示范：酸性高锰酸根氧化亚铁离子】MnO₄⁻中Mn由+7降到+2得5e⁻，5Fe²⁺各失1e⁻；先得MnO₄⁻+5Fe²⁺→Mn²⁺+5Fe³⁺，再用4H₂O补右侧4个O、用8H⁺补左侧8个H，得到MnO₄⁻+5Fe²⁺+8H⁺=Mn²⁺+5Fe³⁺+4H₂O，左右总电荷都为+17。"],"visualSteps":["变价骨架定1∶5","H₂O补O、H⁺补H","原子与电荷同查"],"caution":"只使用高中离子方程式配平规则；陌生含氧粒子的真实产物和介质必须服从题给信息。"},{"label":"碱性介质缺项：最后只留氢氧根和水","rule":"碱性介质可先按酸性介质补齐H₂O和H⁺，再在方程式两边加入等量OH⁻把H⁺变成H₂O，约去两边相同的水；最终式中不应残留H⁺。也可直接用OH⁻、H₂O配平，但检查标准相同。","examples":["【示范：把氯气歧化式查完整】骨架Cl₂→Cl⁻+ClO⁻已经满足电子守恒；右侧多1个O，左侧加2OH⁻提供2O和2H，右侧加H₂O用去1O和2H，得到Cl₂+2OH⁻=Cl⁻+ClO⁻+H₂O；左右原子数、电荷−2都相等。"],"visualSteps":["先定变价产物","OH⁻、H₂O补H/O","最终无H⁺并查电荷"],"caution":"碱性介质的产物可能随题设改变；“配平方法”不能替代对真实反应事实的判断。"}]}],"workedExamples":[{"substance":"SO₄²⁻和Na₂O₂怎样标价","path":"SO₄²⁻中设S为x，有x+4×(-2)=-2，得S=+6；Na₂O₂中Na为+1，总和为0，得O=-1，说明过氧化物是常见例外。","labels":["先用固定价","列代数和","解未知价","查特殊物质"]},{"substance":"Fe²⁺和Cl₂的身份链","path":"Fe²⁺→Fe³⁺+e⁻：升价、失电子、被氧化，Fe²⁺是还原剂；Cl₂+2e⁻→2Cl⁻：降价、得电子、被还原，Cl₂是氧化剂。","labels":["升价失电子","还原剂被氧化","降价得电子","氧化剂被还原"]},{"substance":"2Na+Cl₂→2NaCl的双线桥","path":"Na由0升至+1，2个Na共失2e⁻；Cl由0降至-1，一个Cl₂共得2e⁻。在线桥上标“失2e⁻”与“得2e⁻”，二者相等。","labels":["标反应前后价态","计算变价原子数","标得失电子","电子总数相等"]},{"substance":"FeS₂被O₂氧化","path":"FeS₂中Fe由+2到+3失1e⁻，两个S由-1到+6共失14e⁻，每个FeS₂共失15e⁻；O₂中两个O共得4e⁻。最小公倍数60，先定4FeS₂和15O₂；再按酸性介质补齐，得到4FeS₂+15O₂+2H₂O=4Fe³⁺+8SO₄²⁻+4H⁺，左右总电荷均为0，并满足原子与电子守恒。","labels":["标价","升降电子数","最小公倍数","补齐并守恒校验"]},{"substance":"MnO₄⁻先氧化谁","path":"酸性体系中MnO₄⁻遇Fe²⁺和其他还原性粒子时，先由题给反应或强弱关系判断顺序；定量时把各还原剂失电子总数与MnO₄⁻得电子总数相等，不必追逐全部中间产物。","labels":["比较氧化还原能力","判断先后","汇总失电子","总电子守恒"]},{"substance":"2Na+Cl₂→2NaCl","path":"Na由0升到+1，每个Na失1e⁻，2个Na共失2e⁻；Cl由0降到-1，一个Cl₂含2个Cl，共得2e⁻。Na是还原剂，Cl₂是氧化剂。","labels":["升失氧","降得还","得失电子相等"]},{"substance":"酸性MnO₄⁻氧化Fe²⁺","path":"Mn从+7降到+2，每个Mn得5e⁻；Fe从+2升到+3，每个Fe失1e⁻，因此1个MnO₄⁻对应5个Fe²⁺，再用H⁺、H₂O补H和O并检查电荷。","labels":["先定1:5","再补H和O","查电荷"]},{"substance":"歧化与归中对照","path":"歧化从一个中间价向高、低两边分开；归中从高、低两个价态向中间靠拢。两者都先画化合价箭头，再用总失电子=总得电子求系数。","labels":["画价态数轴","标升降箭头","电子守恒定比"]}],"checkpoints":["我能不靠“含氧”判断氧化还原反应。","我能把氧化剂、还原剂、氧化产物、还原产物说完整。","我会计算1 mol物质实际转移多少mol电子。","我能用电子守恒解释配平系数。","我能用价态箭头区分歧化与归中。","我能按酸性或碱性介质补H₂O、H⁺、OH⁻并做三重校验。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h1_redox$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_REDOX' and skill_id = 'H1_REDOX';

update public.chem_knowledge_cards
set structured_content = $card_h1_electrolyte${"skillId":"H1_ELECTROLYTE","version":2,"intro":"这一模块把“电解质分类—电离—离子反应—离子方程式”连成一条线：先知道溶液里真正有哪些粒子，再判断哪些粒子发生了反应。","overview":["电解质判断先限化合物，再看物质本身能否在水中或熔融时产生离子。","强电解质在水中近乎完全电离，弱电解质部分电离；强弱与溶解性不是同一标准。","离子反应发生的常见推动力：生成沉淀、气体、弱电解质，或发生氧化还原等。","离子方程式按“写—拆—删—查”完成，并根据少量、过量和反应顺序确定产物。","离子检验和除杂都不是“报一个试剂名”：要把取样、排干扰、特征反应、现象、结论和新增杂质串成证据链。"],"visualSummary":{"kind":"flow","title":"离子反应完整路线","steps":[{"label":"限定化合物","caption":"01"},{"label":"列真实粒子","caption":"02"},{"label":"找反应推动力","caption":"03"},{"label":"写→拆→删","caption":"04"},{"label":"查事实/原子/电荷","caption":"05"}]},"sections":[{"title":"先看水溶液中真正存在的粒子","summary":"宏观上是一杯溶液，微观上可能有分子、离子和水分子共存。","items":[{"label":"强电解质","rule":"在水溶液中近乎完全电离，书写电离方程式时用“=”。常见强酸、强碱和大多数盐属于此类。","examples":["NaCl=Na⁺+Cl⁻；H₂SO₄在基础离子方程式中按强酸处理。","【示范：NaCl、CH₃COOH和蔗糖的粒子图】NaCl在水中以Na⁺、Cl⁻为主，是强电解质；CH₃COOH分子与少量H⁺、CH₃COO⁻共存，是弱电解质；蔗糖主要以分子存在，是非电解质。"],"visualSteps":["强电解质","强电解质完全电离","弱电解质部分电离","非电解质不电离","画真实粒子"]},{"label":"弱电解质","rule":"在水中只部分电离，存在动态平衡，书写时用可逆号。","examples":["CH₃COOH⇌H⁺+CH₃COO⁻；NH₃·H₂O⇌NH₄⁺+OH⁻。","【示范：NaCl、CH₃COOH和蔗糖的粒子图】NaCl在水中以Na⁺、Cl⁻为主，是强电解质；CH₃COOH分子与少量H⁺、CH₃COO⁻共存，是弱电解质；蔗糖主要以分子存在，是非电解质。"],"visualSteps":["弱电解质","强电解质完全电离","弱电解质部分电离","非电解质不电离","画真实粒子"]},{"label":"强弱与溶解性独立","rule":"强弱说已溶解部分的电离程度；溶解性说有多少物质进入溶液。","examples":["BaSO₄难溶，但溶解的部分完全电离，属于强电解质。","【示范：NaCl、CH₃COOH和蔗糖的粒子图】NaCl在水中以Na⁺、Cl⁻为主，是强电解质；CH₃COOH分子与少量H⁺、CH₃COO⁻共存，是弱电解质；蔗糖主要以分子存在，是非电解质。"],"visualSteps":["强弱与溶解性独立","强电解质完全电离","弱电解质部分电离","非电解质不电离","画真实粒子"]}]},{"title":"离子反应为什么能够发生","summary":"本质是某些离子浓度显著减小或电子发生转移。","items":[{"label":"生成沉淀","rule":"离子结合成难溶物并从溶液的自由离子体系中离开。","examples":["Ba²⁺+SO₄²⁻=BaSO₄↓。","【示范：盐酸与NaOH为什么反应】混合后H⁺与OH⁻结合成难电离的H₂O，二者浓度显著降低；Na⁺、Cl⁻没有实质变化，是旁观离子。"],"visualSteps":["生成沉淀","列出溶液粒子","找显著减少粒子","生成弱电解质","识别旁观离子"]},{"label":"生成气体或弱电解质","rule":"生成气体逸出，或生成水、弱酸、弱碱等难电离物质，推动反应进行。","examples":["H⁺+HCO₃⁻=CO₂↑+H₂O；H⁺+OH⁻=H₂O。","【示范：盐酸与NaOH为什么反应】混合后H⁺与OH⁻结合成难电离的H₂O，二者浓度显著降低；Na⁺、Cl⁻没有实质变化，是旁观离子。"],"visualSteps":["生成气体或弱电解质","列出溶液粒子","找显著减少粒子","生成弱电解质","识别旁观离子"]},{"label":"氧化还原、络合等其他原因","rule":"离子之间发生电子转移，或形成稳定的复杂粒子，也可推动反应。","examples":["Fe+2Fe³⁺=3Fe²⁺。","【示范：盐酸与NaOH为什么反应】混合后H⁺与OH⁻结合成难电离的H₂O，二者浓度显著降低；Na⁺、Cl⁻没有实质变化，是旁观离子。"],"caution":"陌生反应以题目给出的事实和信息为准。","visualSteps":["氧化还原、络合等其他原因","列出溶液粒子","找显著减少粒子","生成弱电解质","识别旁观离子"]}]},{"title":"离子方程式“写—拆—删—查”","summary":"每一步都解决一个明确问题。","items":[{"label":"写：写对分子方程式","rule":"先保证反应物、产物、条件和计量数正确；分子方程式错，后面无法补救。","examples":["【示范：HCl+NaOH的写拆删查】先写HCl+NaOH=NaCl+H₂O；把可溶强电解质拆为离子；删去两边相同的Na⁺、Cl⁻；得到H⁺+OH⁻=H₂O，并查事实、原子、电荷和最简系数。"],"visualSteps":["写：写对分子方程式","写对分子式","拆强电解质","删旁观离子","四重检查"]},{"label":"拆：只拆该拆的","rule":"水溶液中的可溶强电解质拆成离子；沉淀、气体、弱电解质、单质和氧化物通常保留化学式。","examples":["CH₃COOH、H₂O、CO₂、CaCO₃不拆。","【示范：HCl+NaOH的写拆删查】先写HCl+NaOH=NaCl+H₂O；把可溶强电解质拆为离子；删去两边相同的Na⁺、Cl⁻；得到H⁺+OH⁻=H₂O，并查事实、原子、电荷和最简系数。"],"visualSteps":["拆：只拆该拆的","写对分子式","拆强电解质","删旁观离子","四重检查"]},{"label":"删：删除旁观离子","rule":"删去反应前后形式和数目都相同的离子，保留真正改变的粒子。","examples":["【示范：HCl+NaOH的写拆删查】先写HCl+NaOH=NaCl+H₂O；把可溶强电解质拆为离子；删去两边相同的Na⁺、Cl⁻；得到H⁺+OH⁻=H₂O，并查事实、原子、电荷和最简系数。"],"visualSteps":["删：删除旁观离子","写对分子式","拆强电解质","删旁观离子","四重检查"]},{"label":"查：四重检查","rule":"检查反应事实、原子守恒、电荷守恒和系数最简；氧化还原还要查电子守恒。","examples":["【示范：HCl+NaOH的写拆删查】先写HCl+NaOH=NaCl+H₂O；把可溶强电解质拆为离子；删去两边相同的Na⁺、Cl⁻；得到H⁺+OH⁻=H₂O，并查事实、原子、电荷和最简系数。"],"visualSteps":["查：四重检查","写对分子式","拆强电解质","删旁观离子","四重检查"]}]},{"title":"离子共存题的判断顺序","summary":"“能大量共存”就是在给定条件下不能发生显著反应。","items":[{"label":"先读隐含条件","rule":"无色、透明、强酸性、强碱性、由水电离的H⁺浓度等条件先翻译成粒子限制。","examples":["无色排除明显有色离子；强酸性相当于有大量H⁺。","【示范：无色酸性溶液能否共存】先把“无色”排除有色离子，把“酸性”转成有大量H⁺；再逐对检查沉淀、气体、弱电解质和氧化还原。HCO₃⁻会与H⁺生成CO₂、H₂O，不能大量共存。"],"visualSteps":["先读隐含条件","翻译隐含条件","逐对检查","写净离子反应","所有离子同时成立"]},{"label":"再逐对排查反应","rule":"依次查沉淀、气体、弱电解质、氧化还原和题目给出的特殊反应。","examples":["【示范：无色酸性溶液能否共存】先把“无色”排除有色离子，把“酸性”转成有大量H⁺；再逐对检查沉淀、气体、弱电解质和氧化还原。HCO₃⁻会与H⁺生成CO₂、H₂O，不能大量共存。"],"visualSteps":["再逐对排查反应","翻译隐含条件","逐对检查","写净离子反应","所有离子同时成立"]},{"label":"注意“少量存在”和“大量共存”","rule":"痕量不等于能大量共存；题目要求的是所有给定离子在相同溶液中都有较大浓度。","examples":["【示范：无色酸性溶液能否共存】先把“无色”排除有色离子，把“酸性”转成有大量H⁺；再逐对检查沉淀、气体、弱电解质和氧化还原。HCO₃⁻会与H⁺生成CO₂、H₂O，不能大量共存。"],"visualSteps":["注意“少量存在”和“大量共存”","翻译隐含条件","逐对检查","写净离子反应","所有离子同时成立"]}]},{"title":"少量、过量和反应顺序","summary":"用量不同会改变终点，必须先找限制量。","items":[{"label":"少量试剂","rule":"把少量物质的化学计量数定为满足完全反应，再判断过量物质剩余。","examples":["少量CO₂通入NaOH溶液主要生成CO₃²⁻。","【示范：CO₂少量与过量通入NaOH】少量CO₂时OH⁻足量，终点以CO₃²⁻为主：CO₂+2OH⁻=CO₃²⁻+H₂O；过量CO₂继续把CO₃²⁻转为HCO₃⁻，总式为CO₂+OH⁻=HCO₃⁻。"],"visualSteps":["少量试剂","定少量为1","判断谁过量","分阶段反应","按终点合并"]},{"label":"过量试剂","rule":"继续反应可能生成新的粒子，离子方程式要写到题设终点。","examples":["过量CO₂通入NaOH溶液可主要生成HCO₃⁻。","【示范：CO₂少量与过量通入NaOH】少量CO₂时OH⁻足量，终点以CO₃²⁻为主：CO₂+2OH⁻=CO₃²⁻+H₂O；过量CO₂继续把CO₃²⁻转为HCO₃⁻，总式为CO₂+OH⁻=HCO₃⁻。"],"visualSteps":["过量试剂","定少量为1","判断谁过量","分阶段反应","按终点合并"]},{"label":"多反应竞争","rule":"先发生更有利或题设指定的反应；必要时分阶段写方程式，再按用量合并。","caution":"不能见到所有可能反应就一次性全部相加。","examples":["【示范：CO₂少量与过量通入NaOH】少量CO₂时OH⁻足量，终点以CO₃²⁻为主：CO₂+2OH⁻=CO₃²⁻+H₂O；过量CO₂继续把CO₃²⁻转为HCO₃⁻，总式为CO₂+OH⁻=HCO₃⁻。"],"visualSteps":["多反应竞争","定少量为1","判断谁过量","分阶段反应","按终点合并"]}]},{"title":"离子检验、除杂与干扰链","summary":"检验追求证据唯一，除杂追求目标保留、杂质转化、试剂可清除。","items":[{"label":"检验题的完整句式","rule":"先另取少量待测液，再按需要预处理排除干扰，加入检验试剂并写出特征现象，最后只作证据能够支持的结论。检验不能直接在原样中反复加试剂，否则前一步新加的离子可能干扰后一步。","examples":["【示范：检验氯离子】另取少量待测液，先加稀硝酸酸化，再滴加AgNO₃溶液；若出现不溶于稀硝酸的白色沉淀，可支持含Cl⁻，反应为Ag⁺+Cl⁻=AgCl↓。"],"visualSteps":["另取样品","稀硝酸预处理","AgCl白色沉淀→结论"],"caution":"离子检验以福建高中常见特征反应为限；复杂未知样品仍需结合题给离子范围，不能凭单一颜色无限外推。"},{"label":"硫酸根检验先处理同现象干扰","rule":"Ba²⁺能与多种阴离子生成沉淀，所以“加钡盐有白色沉淀”证据不唯一。高中常用先加稀盐酸酸化，排除CO₃²⁻、SO₃²⁻等会被酸转化的干扰，再加入BaCl₂观察是否仍有白色BaSO₄。","examples":["【示范：检验硫酸根】另取待测液，先加稀盐酸；若无异常沉淀，再加BaCl₂溶液，出现白色沉淀且在酸性条件下不溶，可支持含SO₄²⁻，离子反应为Ba²⁺+SO₄²⁻=BaSO₄↓。"],"visualSteps":["先列“钡盐白沉淀”竞争者","酸化排除碳酸根等","BaSO₄证据落地"],"caution":"若题目给出Ag⁺等会与Cl⁻反应的特殊背景，预处理试剂需要重新选择或增加分样；不能机械照搬固定顺序。"},{"label":"除杂剂的四个门槛","rule":"合格除杂剂要能与杂质反应完全、不能大量损耗目标物、过量试剂能够在后续清除、不能留下新的难除杂质。先把“杂质→沉淀/气体/弱电解质”画出来，再追踪新加入的每一种离子去了哪里。","examples":["【示范：粗盐溶液中除去硫酸根】向含少量Na₂SO₄的NaCl溶液加入适量BaCl₂，使SO₄²⁻转为BaSO₄沉淀并过滤；Cl⁻仍属于目标盐体系。若BaCl₂过量，还要继续设计步骤除去Ba²⁺，所以“适量”和后续检验不能省略。"],"visualSteps":["杂质SO₄²⁻→BaSO₄","过滤移出固相","追查Ba²⁺是否过量"],"caution":"高中除杂答案以题给目标产物和可用试剂为准；“加入过量”只有在过量部分能被后续可靠除去时才合理。"},{"label":"多离子任务先画干扰链","rule":"把每个候选试剂会与哪些现有离子、新增离子反应列成箭头；若两个检验会互相引入目标离子，就必须分样。若是连续除杂，则按“先生成沉淀—过滤—再调条件”的顺序，避免沉淀重新溶解或新杂质累积。","examples":["【示范：同一样品检验氯离子和硫酸根】应分成两份：一份用稀硝酸和AgNO₃检验Cl⁻；另一份用稀盐酸和BaCl₂检验SO₄²⁻。若先在同一份中加BaCl₂，就人为引入Cl⁻，之后的氯离子检验失去可信度。"],"visualSteps":["画“试剂→新增离子”箭头","发现BaCl₂引入Cl⁻","分样形成两条证据链"],"caution":"分样、顺序和试剂选择属于高中实验推理；不要求脱离题给范围设计完整仪器分析流程。"}]}],"workedExamples":[{"substance":"NaCl、CH₃COOH和蔗糖的粒子图","path":"NaCl在水中以Na⁺、Cl⁻为主，是强电解质；CH₃COOH分子与少量H⁺、CH₃COO⁻共存，是弱电解质；蔗糖主要以分子存在，是非电解质。","labels":["强电解质完全电离","弱电解质部分电离","非电解质不电离","画真实粒子"]},{"substance":"盐酸与NaOH为什么反应","path":"混合后H⁺与OH⁻结合成难电离的H₂O，二者浓度显著降低；Na⁺、Cl⁻没有实质变化，是旁观离子。","labels":["列出溶液粒子","找显著减少粒子","生成弱电解质","识别旁观离子"]},{"substance":"HCl+NaOH的写拆删查","path":"先写HCl+NaOH=NaCl+H₂O；把可溶强电解质拆为离子；删去两边相同的Na⁺、Cl⁻；得到H⁺+OH⁻=H₂O，并查事实、原子、电荷和最简系数。","labels":["写对分子式","拆强电解质","删旁观离子","四重检查"]},{"substance":"无色酸性溶液能否共存","path":"先把“无色”排除有色离子，把“酸性”转成有大量H⁺；再逐对检查沉淀、气体、弱电解质和氧化还原。HCO₃⁻会与H⁺生成CO₂、H₂O，不能大量共存。","labels":["翻译隐含条件","逐对检查","写净离子反应","所有离子同时成立"]},{"substance":"CO₂少量与过量通入NaOH","path":"少量CO₂时OH⁻足量，终点以CO₃²⁻为主：CO₂+2OH⁻=CO₃²⁻+H₂O；过量CO₂继续把CO₃²⁻转为HCO₃⁻，总式为CO₂+OH⁻=HCO₃⁻。","labels":["定少量为1","判断谁过量","分阶段反应","按终点合并"]},{"substance":"盐酸与NaOH","path":"分子方程式HCl+NaOH=NaCl+H₂O；HCl、NaOH、NaCl拆成离子；删去Na⁺、Cl⁻，得到H⁺+OH⁻=H₂O；原子和电荷都守恒。","labels":["写","拆","删","查"]},{"substance":"NaHCO₃与盐酸","path":"NaHCO₃、HCl、NaCl在水中拆写，但HCO₃⁻作为多原子离子整体保留；碳酸分解为CO₂和H₂O，最终HCO₃⁻+H⁺=CO₂↑+H₂O。","labels":["HCO₃⁻不能错拆","气体保留分子式","查电荷0=0"]},{"substance":"离子证据链模板","path":"另取样品→根据候选离子排干扰→加入特异性较好的试剂→记录现象→写离子方程式→把结论限定为“可支持检出”。","labels":["取样","排干扰","特征现象","边界结论"]}],"checkpoints":["我能解释强弱电解质与溶解性的区别。","我能列出离子反应发生的主要条件。","我知道哪些物质在离子方程式中通常不拆。","我遇到少量、过量时会先找限制量。","我能把离子检验写成完整证据链。","我选择除杂剂时会继续追踪过量试剂和新增离子。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h1_electrolyte$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_ELECTROLYTE' and skill_id = 'H1_ELECTROLYTE';

update public.chem_knowledge_cards
set structured_content = $card_h1_mole${"skillId":"H1_MOLE","version":2,"intro":"完整物质的量计算只有一个中心n。无论题目给质量、微粒数、气体体积还是溶液浓度，都先回到n，再按化学方程式的计量关系走向所求量。","overview":["四条主桥：n=m/M，N=nNₐ，气体n=V/Vₘ，溶液n=cV。","使用Vₘ必须同时检查物质是气体、温度和压强条件；22.4 L·mol⁻¹只对应标准状况下的近似值。","使用c=n/V时，溶液体积必须以L代入，不是溶剂体积。","反应计算先把已知量化成n，再用配平方程式系数比转移。","溶液质量分数、密度与物质的量浓度用“取1 L溶液”接通；配液误差统一回到c=n/V判断。"],"visualSummary":{"kind":"network","title":"所有已知量先汇入 n","center":"物质的量 n","groups":[{"label":"质量","items":["m/M"]},{"label":"微粒数","items":["N/Nₐ"]},{"label":"气体体积","items":["V/Vₘ"]},{"label":"溶液","items":["cV"]},{"label":"反应","items":["方程式系数比"]}]},"sections":[{"title":"以n为中心的换算网络","summary":"看到任何量都问：怎样先到n？","items":[{"label":"质量桥m↔n","rule":"n=m/M，m=nM。M按化学式计算，单位通常为g·mol⁻¹。","examples":["【示范：11.2 L标况O₂的换算网络】标况下n(O₂)=11.2/22.4=0.50 mol；m=0.50×32=16 g；N(O₂)=0.50Nₐ；N(O原子)=1.00Nₐ。所有量先汇到n再分流。"],"visualSteps":["质量桥m↔n","V到n","n到m","n到N","按下标换粒子"]},{"label":"粒子桥N↔n","rule":"N=nNₐ；再结合化学式下标、离子数或电子数处理目标粒子。","examples":["【示范：11.2 L标况O₂的换算网络】标况下n(O₂)=11.2/22.4=0.50 mol；m=0.50×32=16 g；N(O₂)=0.50Nₐ；N(O原子)=1.00Nₐ。所有量先汇到n再分流。"],"visualSteps":["粒子桥N↔n","V到n","n到m","n到N","按下标换粒子"]},{"label":"气体桥V↔n","rule":"在指定温度和压强下n=V/Vₘ；标准状况下Vₘ≈22.4 L·mol⁻¹。","caution":"非标准状况不能擅自用22.4；水在标准状况下不是气体。","examples":["【示范：11.2 L标况O₂的换算网络】标况下n(O₂)=11.2/22.4=0.50 mol；m=0.50×32=16 g；N(O₂)=0.50Nₐ；N(O原子)=1.00Nₐ。所有量先汇到n再分流。"],"visualSteps":["气体桥V↔n","V到n","n到m","n到N","按下标换粒子"]},{"label":"溶液桥c、V↔n","rule":"n=cV，c=n/V。V指溶液体积并以L计。","examples":["500 mL=0.500 L。","【示范：11.2 L标况O₂的换算网络】标况下n(O₂)=11.2/22.4=0.50 mol；m=0.50×32=16 g；N(O₂)=0.50Nₐ；N(O原子)=1.00Nₐ。所有量先汇到n再分流。"],"visualSteps":["溶液桥c、V↔n","V到n","n到m","n到N","按下标换粒子"]}]},{"title":"气体题先查条件","summary":"气体摩尔体积不是所有气体在所有条件下都相同。","items":[{"label":"标准状况","rule":"中学常指0 ℃、101 kPa；此时理想近似下1 mol气体体积约22.4 L。","examples":["【示范：标况11.2 L水是陷阱】22.4 L·mol⁻¹只用于该状态下的气体；0 ℃、101 kPa时水不是气体，不能用11.2/22.4。若同温同压比较两种气体，体积比才等于物质的量比。"],"visualSteps":["标准状况","查温压","查物态","再用Vₘ","同温同压比较"]},{"label":"阿伏加德罗定律","rule":"同温同压下，相同体积的任何气体含相同数目的分子；气体体积比等于物质的量比。","examples":["【示范：标况11.2 L水是陷阱】22.4 L·mol⁻¹只用于该状态下的气体；0 ℃、101 kPa时水不是气体，不能用11.2/22.4。若同温同压比较两种气体，体积比才等于物质的量比。"],"visualSteps":["阿伏加德罗定律","查温压","查物态","再用Vₘ","同温同压比较"]},{"label":"气体混合物","rule":"总物质的量等于各组分物质的量之和；平均摩尔质量=总质量/总物质的量。","examples":["【示范：标况11.2 L水是陷阱】22.4 L·mol⁻¹只用于该状态下的气体；0 ℃、101 kPa时水不是气体，不能用11.2/22.4。若同温同压比较两种气体，体积比才等于物质的量比。"],"visualSteps":["气体混合物","查温压","查物态","再用Vₘ","同温同压比较"]}]},{"title":"物质的量浓度与配制","summary":"浓度描述单位体积溶液中溶质的物质的量。","items":[{"label":"定义与单位","rule":"c=n/V，常用单位mol·L⁻¹。这里V是最终溶液体积，不是加入水的体积。","examples":["【示范：配500 mL 0.200 mol·L⁻¹ NaCl】需n=cV=0.200×0.500=0.100 mol，m=5.85 g；按称量、溶解、转移、洗涤、定容、摇匀操作。定容看最终溶液体积，不看加水体积。"],"visualSteps":["定义与单位","计算用量","称量溶解","转移洗涤","定容摇匀"]},{"label":"稀释与混合","rule":"同一溶质且无反应时，稀释前后溶质的量不变，可用c₁V₁=c₂V₂；发生反应时不能直接套。","examples":["【示范：配500 mL 0.200 mol·L⁻¹ NaCl】需n=cV=0.200×0.500=0.100 mol，m=5.85 g；按称量、溶解、转移、洗涤、定容、摇匀操作。定容看最终溶液体积，不看加水体积。"],"visualSteps":["稀释与混合","计算用量","称量溶解","转移洗涤","定容摇匀"]},{"label":"一定浓度溶液配制","rule":"计算—称量/量取—溶解—转移—洗涤—定容—摇匀；容量瓶只能配制规定体积。","caution":"定容仰视或俯视会改变最终体积，从而改变浓度。","examples":["【示范：配500 mL 0.200 mol·L⁻¹ NaCl】需n=cV=0.200×0.500=0.100 mol，m=5.85 g；按称量、溶解、转移、洗涤、定容、摇匀操作。定容看最终溶液体积，不看加水体积。"],"visualSteps":["一定浓度溶液配制","计算用量","称量溶解","转移洗涤","定容摇匀"]}]},{"title":"化学方程式怎样连接不同物质","summary":"配平系数给出的就是物质的量之比。","items":[{"label":"先配平方程式","rule":"只有正确配平后，系数比才能作为n之比。","examples":["【示范：Fe与HCl的限制量】对Fe+2HCl=FeCl₂+H₂，分别计算n(Fe)/1与n(HCl)/2，较小者决定反应进度；按系数求H₂，再用质量、气体体积或粒子数桥梁转换，并用元素守恒验算。"],"visualSteps":["先配平方程式","配平方程式","比较n/系数","按系数转移","守恒验算"]},{"label":"找限制量","rule":"有两个或更多反应物时，分别计算能支持的反应进度，先耗尽者是限制量。","examples":["【示范：Fe与HCl的限制量】对Fe+2HCl=FeCl₂+H₂，分别计算n(Fe)/1与n(HCl)/2，较小者决定反应进度；按系数求H₂，再用质量、气体体积或粒子数桥梁转换，并用元素守恒验算。"],"visualSteps":["找限制量","配平方程式","比较n/系数","按系数转移","守恒验算"]},{"label":"按系数转移","rule":"已知物质的n÷其系数=所求物质的n÷其系数；再转换成题目要求的质量、体积或粒子数。","examples":["【示范：Fe与HCl的限制量】对Fe+2HCl=FeCl₂+H₂，分别计算n(Fe)/1与n(HCl)/2，较小者决定反应进度；按系数求H₂，再用质量、气体体积或粒子数桥梁转换，并用元素守恒验算。"],"visualSteps":["按系数转移","配平方程式","比较n/系数","按系数转移","守恒验算"]},{"label":"守恒法辅助","rule":"质量守恒、元素守恒、电子守恒和电荷守恒能绕开复杂中间步骤，并用于验算。","examples":["【示范：Fe与HCl的限制量】对Fe+2HCl=FeCl₂+H₂，分别计算n(Fe)/1与n(HCl)/2，较小者决定反应进度；按系数求H₂，再用质量、气体体积或粒子数桥梁转换，并用元素守恒验算。"],"visualSteps":["守恒法辅助","配平方程式","比较n/系数","按系数转移","守恒验算"]}]},{"title":"阿伏加德罗常数判断题的检查表","summary":"每个选项都按对象、条件、反应、倍数四关检查。","items":[{"label":"对象关","rule":"问的是分子、原子、离子、质子、中子、电子还是化学键。","examples":["【示范：NA判断题逐关过】判断“标况22.4 L Cl₂含原子数2Nₐ”：对象是Cl原子，状态和物态成立，n(Cl₂)=1 mol，下标倍数2，且无其他反应，所以结论正确。遇溶液、弱电解质或可逆反应还要加查相应条件。"],"visualSteps":["对象关","对象","状态","溶液与反应","结构倍数"]},{"label":"条件关","rule":"气体是否处在指定状态，物质在该状态是否为气体，溶液是否给了体积。","examples":["【示范：NA判断题逐关过】判断“标况22.4 L Cl₂含原子数2Nₐ”：对象是Cl原子，状态和物态成立，n(Cl₂)=1 mol，下标倍数2，且无其他反应，所以结论正确。遇溶液、弱电解质或可逆反应还要加查相应条件。"],"visualSteps":["条件关","对象","状态","溶液与反应","结构倍数"]},{"label":"反应关","rule":"可逆反应是否完全、弱电解质是否完全电离、盐类是否水解、物质是否发生歧化或聚合。","examples":["【示范：NA判断题逐关过】判断“标况22.4 L Cl₂含原子数2Nₐ”：对象是Cl原子，状态和物态成立，n(Cl₂)=1 mol，下标倍数2，且无其他反应，所以结论正确。遇溶液、弱电解质或可逆反应还要加查相应条件。"],"visualSteps":["反应关","对象","状态","溶液与反应","结构倍数"]},{"label":"倍数关","rule":"化学式下标、价电子数、键数和离子电荷带来的倍数是否算全。","examples":["【示范：NA判断题逐关过】判断“标况22.4 L Cl₂含原子数2Nₐ”：对象是Cl原子，状态和物态成立，n(Cl₂)=1 mol，下标倍数2，且无其他反应，所以结论正确。遇溶液、弱电解质或可逆反应还要加查相应条件。"],"visualSteps":["倍数关","对象","状态","溶液与反应","结构倍数"]}]},{"title":"质量分数—密度—浓度与配液误差树","summary":"先把质量、体积统一到同一份溶液，再把错误分别落到溶质的量n或最终体积V。","items":[{"label":"从质量分数和密度推物质的量浓度","rule":"设溶质质量分数为w（小数）、溶液密度为ρ g·cm⁻³、溶质摩尔质量为M g·mol⁻¹。取1 L溶液，其质量为1000ρ g，溶质质量为1000ρw g，溶质物质的量为1000ρw/M mol，所以c=1000ρw/M。","examples":["【示范：98%浓硫酸换算浓度】ρ=1.84 g·cm⁻³、w=0.98、M(H₂SO₄)=98 g·mol⁻¹，则c=1000×1.84×0.98÷98=18.4 mol·L⁻¹。先把98%写成0.98，密度单位保持g·cm⁻³。"],"visualSteps":["取1 L→质量1000ρ","乘w得溶质质量","除M得到c"],"caution":"只处理高中常见均匀溶液换算；题给密度、质量分数的温度和溶液状态必须一致。"},{"label":"稀释只守住溶质的量","rule":"同一溶质稀释且无反应、无挥发、无损失时，稀释前后溶质物质的量不变，所以c₁V₁=c₂V₂。这里V₁是移取浓溶液体积，V₂是稀释后的溶液总体积，不能把加入水的体积直接当V₂。","examples":["【示范：配制250 mL 0.100 mol·L⁻¹溶液】若用1.00 mol·L⁻¹储备液，V₁=0.100×250 mL÷1.00=25.0 mL；量取25.0 mL储备液后转入250 mL容量瓶，最后定容到刻度，而不是再加入250 mL水。"],"visualSteps":["c₁V₁=c₂V₂","求移取体积25.0 mL","定容后的总体积250 mL"],"caution":"体积是否可直接相加由题给近似决定；容量瓶刻度给出的是最终总体积。"},{"label":"误差树第一层：先判n还是V变了","rule":"配制结果始终用c实际=n实际/V实际判断。溶质未完全转移、转移时洒失使n实际偏小；定容超过刻度使V实际偏大；仰视或俯视要结合刻度线和凹液面最低点画图，不能只背箭头。","examples":["【示范：洗涤液未转入容量瓶】烧杯和玻璃棒上仍残留溶质，进入容量瓶的n实际小于应有值，而最终仍定容到刻度使V基本正确，因此c实际偏低。"],"visualSteps":["错误→溶质有残留","n实际↓、V正确","c实际↓"],"caution":"误差只判断该次配制的实际浓度；若后续再用错误溶液做实验，要重新沿新公式传播。"},{"label":"湿润、摇匀后的液面变化要看物质是否丢失","rule":"容量瓶内壁预先有少量蒸馏水不会改变加入的溶质物质的量，最终又定容到刻度，所以不造成浓度误差。定容摇匀后，瓶颈附着的液体回落会使液面略低，这是正常分布变化，不能再补水。","examples":["【示范：容量瓶未干燥与摇匀后补水对比】容量瓶有蒸馏水：n不变，最终V到刻度，c不变；摇匀后若误加水重新到刻度，则V实际增大而n不变，c偏低。"],"visualSteps":["先问是否改变n","再问最终V是否超过标线","湿瓶无影响；补水偏低"],"caution":"容量瓶只能配制其标称体积，不能直接在瓶中溶解放热明显的固体或进行化学反应。"}]}],"workedExamples":[{"substance":"11.2 L标况O₂的换算网络","path":"标况下n(O₂)=11.2/22.4=0.50 mol；m=0.50×32=16 g；N(O₂)=0.50Nₐ；N(O原子)=1.00Nₐ。所有量先汇到n再分流。","labels":["V到n","n到m","n到N","按下标换粒子"]},{"substance":"标况11.2 L水是陷阱","path":"22.4 L·mol⁻¹只用于该状态下的气体；0 ℃、101 kPa时水不是气体，不能用11.2/22.4。若同温同压比较两种气体，体积比才等于物质的量比。","labels":["查温压","查物态","再用Vₘ","同温同压比较"]},{"substance":"配500 mL 0.200 mol·L⁻¹ NaCl","path":"需n=cV=0.200×0.500=0.100 mol，m=5.85 g；按称量、溶解、转移、洗涤、定容、摇匀操作。定容看最终溶液体积，不看加水体积。","labels":["计算用量","称量溶解","转移洗涤","定容摇匀"]},{"substance":"Fe与HCl的限制量","path":"对Fe+2HCl=FeCl₂+H₂，分别计算n(Fe)/1与n(HCl)/2，较小者决定反应进度；按系数求H₂，再用质量、气体体积或粒子数桥梁转换，并用元素守恒验算。","labels":["配平方程式","比较n/系数","按系数转移","守恒验算"]},{"substance":"NA判断题逐关过","path":"判断“标况22.4 L Cl₂含原子数2Nₐ”：对象是Cl原子，状态和物态成立，n(Cl₂)=1 mol，下标倍数2，且无其他反应，所以结论正确。遇溶液、弱电解质或可逆反应还要加查相应条件。","labels":["对象","状态","溶液与反应","结构倍数"]},{"substance":"5.85 g NaCl配成500 mL溶液","path":"M(NaCl)=58.5 g·mol⁻¹，n=5.85/58.5=0.100 mol；V=0.500 L；c=0.100/0.500=0.200 mol·L⁻¹。","labels":["m→n","mL→L","n/V"]},{"substance":"标准状况下11.2 L O₂含多少个O原子","path":"O₂是标况气体，n(O₂)=11.2/22.4=0.5 mol；每个O₂含2个O原子，所以n(O原子)=1.0 mol，N=Nₐ。","labels":["先查气体条件","分子到原子乘2","结果约6.02×10²³"]},{"substance":"配液误差总开关","path":"把每个错误翻译成“进入容量瓶的溶质物质的量n怎样变”和“最终实际体积V怎样变”，再代入c=n/V，避免背零散结论。","labels":["错误事实","n/V两分支","浓度方向"]}],"checkpoints":["我能从m、N、V、c中的任意一个量回到n。","我使用22.4前会检查状态和物态。","我能说明溶液体积与溶剂体积的区别。","我能用配平方程式的系数比完成反应计量。","我能从取1 L溶液推导c=1000ρw/M。","我能用c=n/V独立判断配液误差。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h1_mole$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_MOLE' and skill_id = 'H1_MOLE';

update public.chem_knowledge_cards
set structured_content = $card_h1_nacl${"skillId":"H1_NACL","version":2,"intro":"元素化合物不要背成孤立反应。每遇到一种物质都问四件事：中心元素是什么价态、物质属于什么类别、在什么条件下反应、中心元素最后去了哪里。","overview":["钠单质处于0价，强还原性来自容易失去最外层1个电子；保存和取用都要隔绝水和空气。","Na₂O与Na₂O₂必须分开：前者O为-2，后者O为-1，过氧化钠具有氧化性并能供氧。","Na₂CO₃与NaHCO₃用溶解性、碱性、热稳定性和与酸反应现象比较。","Cl₂既是有毒黄绿色气体，又是强氧化剂；氯水是多粒子混合体系。","漂白和消毒的核心通常是HClO等含氯氧化性粒子，现象解释必须写清水和光照条件。"],"visualSummary":{"kind":"network","title":"钠与氯的完整物质网络","center":"价态与电子","groups":[{"label":"钠主线","items":["Na失1e⁻","Na₂O/Na₂O₂","Na₂CO₃/NaHCO₃","焰色：Na黄/K紫"]},{"label":"氯气主线","items":["Cl₂强氧化","与金属/H₂","氯水多粒子"]},{"label":"含氯消毒剂","items":["冷稀碱→ClO⁻","热浓碱→ClO₃⁻","漂白粉/84→HClO"]}]},"sections":[{"title":"钠：从原子结构理解强还原性","summary":"第3周期ⅠA族，最外层1个电子，易失电子形成Na⁺。","items":[{"label":"物理性质与保存","rule":"银白色、质软、密度小、熔点较低；易与空气和水反应，通常保存在煤油或石蜡油中。","examples":["【示范：钠投入滴酚酞的水】Na浮在水面、熔成小球、四处游动并可能发声，溶液变红；分别由密度小、反应放热、H₂推动、生成NaOH解释。方程式2Na+2H₂O=2NaOH+H₂↑。"],"visualSteps":["物理性质与保存","观察现象","逐项解释","写方程式","说明保存原因"]},{"label":"与水反应","rule":"2Na+2H₂O=2NaOH+H₂↑。浮、熔、游、响、红分别可由密度、放热熔化、气体推动、反应剧烈和生成碱解释。","examples":["【示范：钠投入滴酚酞的水】Na浮在水面、熔成小球、四处游动并可能发声，溶液变红；分别由密度小、反应放热、H₂推动、生成NaOH解释。方程式2Na+2H₂O=2NaOH+H₂↑。"],"visualSteps":["与水反应","观察现象","逐项解释","写方程式","说明保存原因"]},{"label":"与氧气反应","rule":"产物受条件影响：常温表面生成氧化物，加热时主要生成Na₂O₂。","caution":"方程式产物必须结合题目给出的温度和现象。","examples":["【示范：钠投入滴酚酞的水】Na浮在水面、熔成小球、四处游动并可能发声，溶液变红；分别由密度小、反应放热、H₂推动、生成NaOH解释。方程式2Na+2H₂O=2NaOH+H₂↑。"],"visualSteps":["与氧气反应","观察现象","逐项解释","写方程式","说明保存原因"]}]},{"title":"氧化钠与过氧化钠","summary":"先看氧的价态，再看反应类型。","items":[{"label":"Na₂O","rule":"碱性氧化物，和水生成NaOH，和酸生成盐和水。","examples":["Na₂O+H₂O=2NaOH。","【示范：Na₂O与Na₂O₂遇水】Na₂O中O为-2，与水生成NaOH；Na₂O₂中O为-1，与水生成NaOH和O₂。后者既要守原子，也要用氧元素歧化的电子转移检查。"],"visualSteps":["Na₂O","辨氧化物/过氧化物","标氧价态","写产物","原子电子守恒"]},{"label":"Na₂O₂","rule":"过氧化物，O为-1价；与水或CO₂反应能生成O₂，兼具供氧和氧化作用。","examples":["2Na₂O₂+2H₂O=4NaOH+O₂↑；2Na₂O₂+2CO₂=2Na₂CO₃+O₂。","【示范：Na₂O与Na₂O₂遇水】Na₂O中O为-2，与水生成NaOH；Na₂O₂中O为-1，与水生成NaOH和O₂。后者既要守原子，也要用氧元素歧化的电子转移检查。"],"visualSteps":["Na₂O₂","辨氧化物/过氧化物","标氧价态","写产物","原子电子守恒"]},{"label":"电子转移判断","rule":"Na₂O₂中-1价氧可一部分升为0价、一部分降为-2价，具体反应要按产物判断电子转移。","examples":["【示范：Na₂O与Na₂O₂遇水】Na₂O中O为-2，与水生成NaOH；Na₂O₂中O为-1，与水生成NaOH和O₂。后者既要守原子，也要用氧元素歧化的电子转移检查。"],"visualSteps":["电子转移判断","辨氧化物/过氧化物","标氧价态","写产物","原子电子守恒"]}]},{"title":"碳酸钠与碳酸氢钠","summary":"同一中心元素、不同酸根形式，性质不完全相同。","items":[{"label":"溶液碱性与水解","rule":"相同条件下Na₂CO₃水解程度更明显，溶液碱性通常强于NaHCO₃。","examples":["【示范：Na₂CO₃与NaHCO₃鉴别和转化】等浓度溶液中Na₂CO₃碱性较强；加热只有NaHCO₃明显分解放出CO₂；Na₂CO₃吸收CO₂和H₂O变NaHCO₃，NaHCO₃受热或加适量碱转回。"],"visualSteps":["溶液碱性与水解","比较水解","比较热稳定","选鉴别方法","写相互转化"]},{"label":"与酸反应","rule":"两者都能与酸放出CO₂；相同物质的量完全反应时耗H⁺量不同。","examples":["CO₃²⁻+2H⁺=CO₂↑+H₂O；HCO₃⁻+H⁺=CO₂↑+H₂O。","【示范：Na₂CO₃与NaHCO₃鉴别和转化】等浓度溶液中Na₂CO₃碱性较强；加热只有NaHCO₃明显分解放出CO₂；Na₂CO₃吸收CO₂和H₂O变NaHCO₃，NaHCO₃受热或加适量碱转回。"],"visualSteps":["与酸反应","比较水解","比较热稳定","选鉴别方法","写相互转化"]},{"label":"热稳定性","rule":"Na₂CO₃较稳定；NaHCO₃受热分解：2NaHCO₃→Na₂CO₃+CO₂↑+H₂O。","examples":["【示范：Na₂CO₃与NaHCO₃鉴别和转化】等浓度溶液中Na₂CO₃碱性较强；加热只有NaHCO₃明显分解放出CO₂；Na₂CO₃吸收CO₂和H₂O变NaHCO₃，NaHCO₃受热或加适量碱转回。"],"visualSteps":["热稳定性","比较水解","比较热稳定","选鉴别方法","写相互转化"]},{"label":"相互转化","rule":"Na₂CO₃吸收CO₂和H₂O可转化为NaHCO₃；NaHCO₃受热或与适量碱反应可转回Na₂CO₃。","examples":["【示范：Na₂CO₃与NaHCO₃鉴别和转化】等浓度溶液中Na₂CO₃碱性较强；加热只有NaHCO₃明显分解放出CO₂；Na₂CO₃吸收CO₂和H₂O变NaHCO₃，NaHCO₃受热或加适量碱转回。"],"visualSteps":["相互转化","比较水解","比较热稳定","选鉴别方法","写相互转化"]}]},{"title":"氯气与氯水","summary":"把Cl₂的0价和氯水中的多种粒子分开。","items":[{"label":"氯气的性质","rule":"黄绿色、有刺激性、有毒、密度比空气大，可溶于水；强氧化性来自Cl₂易得电子形成Cl⁻。","examples":["与Fe反应通常生成FeCl₃。","【示范：新制氯水的多重性质】Cl₂+H₂O⇌HCl+HClO。H⁺体现酸性，Cl⁻可被Ag⁺检验，Cl₂/HClO体现氧化性，HClO使有色物褪色；光照使HClO分解，久置后性质改变。"],"visualSteps":["氯气的性质","建立平衡","列所有粒子","粒子对应性质","判断久置变化"]},{"label":"与水的反应","rule":"Cl₂+H₂O⇌HCl+HClO，是歧化反应：Cl从0价分别变为-1和+1。","examples":["【示范：新制氯水的多重性质】Cl₂+H₂O⇌HCl+HClO。H⁺体现酸性，Cl⁻可被Ag⁺检验，Cl₂/HClO体现氧化性，HClO使有色物褪色；光照使HClO分解，久置后性质改变。"],"visualSteps":["与水的反应","建立平衡","列所有粒子","粒子对应性质","判断久置变化"]},{"label":"新制氯水的粒子","rule":"通常含Cl₂、H₂O、HClO分子以及H⁺、Cl⁻、ClO⁻、OH⁻等离子；不同性质由不同粒子负责。","caution":"氯水是混合物，液氯是液态Cl₂纯净物。","examples":["【示范：新制氯水的多重性质】Cl₂+H₂O⇌HCl+HClO。H⁺体现酸性，Cl⁻可被Ag⁺检验，Cl₂/HClO体现氧化性，HClO使有色物褪色；光照使HClO分解，久置后性质改变。"],"visualSteps":["新制氯水的粒子","建立平衡","列所有粒子","粒子对应性质","判断久置变化"]},{"label":"光照变化","rule":"HClO见光分解，久置氯水中有效成分减少，体系逐渐更接近稀盐酸。","examples":["【示范：新制氯水的多重性质】Cl₂+H₂O⇌HCl+HClO。H⁺体现酸性，Cl⁻可被Ag⁺检验，Cl₂/HClO体现氧化性，HClO使有色物褪色；光照使HClO分解，久置后性质改变。"],"visualSteps":["光照变化","建立平衡","列所有粒子","粒子对应性质","判断久置变化"]}]},{"title":"漂白、消毒、制备和检验","summary":"从氧化性与实验安全理解用途。","items":[{"label":"漂白与消毒","rule":"HClO等氧化性含氯物种能破坏有色物质或微生物结构；漂白通常不可逆。","caution":"干燥Cl₂不能使干燥有色布条明显褪色，水参与形成HClO。","examples":["【示范：从制氯到检氯离子】实验室由MnO₂与浓盐酸加热制Cl₂，先除HCl和水蒸气干扰，再根据密度/溶解性收集并吸收尾气；检Cl⁻时取样、加稀硝酸酸化、再加AgNO₃，见白色AgCl沉淀。"],"visualSteps":["漂白与消毒","发生装置","净化收集","尾气处理","取样检验"]},{"label":"实验室制Cl₂","rule":"常用强氧化剂氧化浓盐酸中的Cl⁻，装置要包含发生、净化、干燥、收集和尾气吸收。","examples":["MnO₂+4HCl(浓)加热→MnCl₂+Cl₂↑+2H₂O。","【示范：从制氯到检氯离子】实验室由MnO₂与浓盐酸加热制Cl₂，先除HCl和水蒸气干扰，再根据密度/溶解性收集并吸收尾气；检Cl⁻时取样、加稀硝酸酸化、再加AgNO₃，见白色AgCl沉淀。"],"visualSteps":["实验室制Cl₂","发生装置","净化收集","尾气处理","取样检验"]},{"label":"Cl⁻检验","rule":"先用稀硝酸排除干扰，再加AgNO₃，产生不溶于稀硝酸的白色AgCl沉淀。","caution":"含Cl元素不等于含Cl⁻；ClO⁻中的氯不能直接用该方法等同检出。","examples":["【示范：从制氯到检氯离子】实验室由MnO₂与浓盐酸加热制Cl₂，先除HCl和水蒸气干扰，再根据密度/溶解性收集并吸收尾气；检Cl⁻时取样、加稀硝酸酸化、再加AgNO₃，见白色AgCl沉淀。"],"visualSteps":["Cl⁻检验","发生装置","净化收集","尾气处理","取样检验"]}]},{"title":"焰色试验：把颜色变成可靠证据","summary":"焰色试验要同时记住规范操作、特征颜色和结论边界。","items":[{"label":"规范操作链","rule":"用铂丝或洁净的无锈铁丝蘸盐酸，在火焰上灼烧至火焰无色；再蘸取样品放在外焰灼烧并观察颜色。每次换样都要重新洗涤、灼烧。","examples":["【示范：检验NaCl中的钠元素】先把金属丝蘸盐酸灼烧至无色，再蘸NaCl样品置于外焰，看到稳定的黄色火焰；若未先洗净，残留的Na⁺也可能造成黄色干扰。"],"visualSteps":["盐酸洗涤","灼烧至无色","蘸取样品","外焰观察"],"caution":"不能直接用手接触样品或把金属丝带着大量溶液伸入火焰。"},{"label":"钠、钾的特征颜色","rule":"钠元素的焰色为黄色；钾元素的焰色为紫色，观察钾时常透过蓝色钴玻璃，以减弱痕量钠造成的黄色干扰。","examples":["【示范：NaCl与KCl混合样】直接观察时强烈黄色可能遮住钾的紫色；透过蓝色钴玻璃后黄色被削弱，才更容易观察到钾的特征焰色。"],"visualSteps":["直接观察黄色","识别钠干扰","透蓝色钴玻璃","观察钾紫色"]},{"label":"证据能够说明什么","rule":"焰色来自电子能级变化产生的特征发射，属于物理变化。观察到特征焰色只能支持样品中含相应元素，不能据此唯一确定是哪一种化合物，也不能直接判断含量。","examples":["【示范：黄色焰色的结论】NaCl、Na₂CO₃和NaOH都可呈黄色焰色，所以现象只能支持“检出钠元素”，不能写成“样品一定是NaCl”。"],"visualSteps":["看到特征颜色","锁定相应元素","不能锁定化合物","不能直接定量"]}]},{"title":"氯气反应：先看对象，再看温度和用量","summary":"Cl₂既可作氧化剂，也能发生歧化；反应条件决定含氯产物。","items":[{"label":"与金属和非金属反应","rule":"氯气通常表现强氧化性：与铁在点燃条件下主要生成FeCl₃；与氢气在点燃或光照条件下生成HCl。写产物时必须结合氧化性和反应条件。","examples":["【示范：铁丝在氯气中燃烧】2Fe+3Cl₂点燃生成2FeCl₃，Fe由0价升至+3价、Cl由0价降至-1价；不能按“铁和酸”机械写成FeCl₂。"],"visualSteps":["确定反应对象","标出价态","结合氯气氧化性","写条件与产物"],"caution":"氯气与H₂的混合气体受强光照射可能爆炸，演示和表述都要带安全边界。"},{"label":"冷的稀碱：生成次氯酸盐","rule":"冷、稀碱中氯气发生歧化，离子方程式为Cl₂+2OH⁻=Cl⁻+ClO⁻+H₂O；同一价态的Cl同时升价和降价。","examples":["【示范：Cl₂通入冷稀NaOH】生成NaCl、NaClO和H₂O；一个Cl由0降到-1，另一个Cl由0升到+1，得失电子数相等。"],"visualSteps":["先读冷稀条件","Cl由0降到-1","Cl由0升到+1","电子守恒"]},{"label":"热的浓碱：生成氯酸盐","rule":"热、浓碱中氯气歧化程度更深：3Cl₂+6OH⁻=5Cl⁻+ClO₃⁻+3H₂O。ClO₃⁻中的Cl为+5价，因此生成的Cl⁻与ClO₃⁻物质的量之比为5∶1。","examples":["【示范：电子守恒定5∶1】1个Cl由0升到+5失5e⁻，需要5个Cl各由0降到-1共得5e⁻，所以先定ClO₃⁻∶Cl⁻=1∶5，再补OH⁻和H₂O。"],"visualSteps":["先读热浓条件","升价失5e⁻","5个Cl各得1e⁻","补原子和电荷"],"caution":"没有温度、浓度信息时，不可擅自把次氯酸盐或氯酸盐写成唯一产物。"}]},{"title":"含氯消毒剂：制备—生效—安全","summary":"漂白粉和84消毒液都要追到具有氧化性的含氯粒子，并区分正常使用与酸化风险。","items":[{"label":"84消毒液的主线","rule":"84消毒液的有效成分通常是NaClO。ClO⁻在水中形成少量HClO，HClO具有较强氧化性，可用于漂白和消毒；酸碱条件会改变含氯粒子的比例。","examples":["【示范：空气中CO₂促进形成HClO】可用ClO⁻+CO₂+H₂O=HClO+HCO₃⁻表示弱酸置换方向，说明敞口久置和酸碱条件会改变有效含氯粒子。"],"visualSteps":["NaClO入水","形成HClO","氧化漂白消毒","条件改变组成"]},{"label":"漂白粉的制备与生效","rule":"氯气与冷的石灰乳反应可制漂白粉，产物体系含CaCl₂和有效成分Ca(ClO)₂；使用时Ca(ClO)₂在水和酸性物质作用下形成HClO。","examples":["【示范：漂白粉制备】2Cl₂+2Ca(OH)₂=CaCl₂+Ca(ClO)₂+2H₂O；再由Ca(ClO)₂与水、CO₂作用形成HClO，解释漂白和消毒。"],"visualSteps":["氯气通入石灰乳","得到含次氯酸盐产品","水中形成HClO","发挥氧化作用"],"caution":"漂白粉是混合物，不能把整份漂白粉只写成Ca(ClO)₂一种纯净物。"},{"label":"有效氯与混用风险","rule":"有效氯用于比较含氯消毒剂可提供的氧化能力；高中题按题给反应和电子守恒换算。次氯酸盐与强酸混合可能生成有毒Cl₂，因此含氯消毒剂不能与酸性洁厕剂混用。","examples":["【示范：84消毒液遇盐酸】ClO⁻+Cl⁻+2H⁺=Cl₂↑+H₂O；Cl(+1)与Cl(-1)归中为Cl₂，产生有毒气体，说明“酸化越强消毒越好”是危险误区。"],"visualSteps":["读有效氯口径","按电子守恒换算","识别酸化反应","排除混用风险"],"caution":"不要求记忆工业检测公式；若题目给出有效氯定义，只按定义和守恒计算。"}]}],"workedExamples":[{"substance":"钠投入滴酚酞的水","path":"Na浮在水面、熔成小球、四处游动并可能发声，溶液变红；分别由密度小、反应放热、H₂推动、生成NaOH解释。方程式2Na+2H₂O=2NaOH+H₂↑。","labels":["观察现象","逐项解释","写方程式","说明保存原因"]},{"substance":"Na₂O与Na₂O₂遇水","path":"Na₂O中O为-2，与水生成NaOH；Na₂O₂中O为-1，与水生成NaOH和O₂。后者既要守原子，也要用氧元素歧化的电子转移检查。","labels":["辨氧化物/过氧化物","标氧价态","写产物","原子电子守恒"]},{"substance":"Na₂CO₃与NaHCO₃鉴别和转化","path":"等浓度溶液中Na₂CO₃碱性较强；加热只有NaHCO₃明显分解放出CO₂；Na₂CO₃吸收CO₂和H₂O变NaHCO₃，NaHCO₃受热或加适量碱转回。","labels":["比较水解","比较热稳定","选鉴别方法","写相互转化"]},{"substance":"新制氯水的多重性质","path":"Cl₂+H₂O⇌HCl+HClO。H⁺体现酸性，Cl⁻可被Ag⁺检验，Cl₂/HClO体现氧化性，HClO使有色物褪色；光照使HClO分解，久置后性质改变。","labels":["建立平衡","列所有粒子","粒子对应性质","判断久置变化"]},{"substance":"从制氯到检氯离子","path":"实验室由MnO₂与浓盐酸加热制Cl₂，先除HCl和水蒸气干扰，再根据密度/溶解性收集并吸收尾气；检Cl⁻时取样、加稀硝酸酸化、再加AgNO₃，见白色AgCl沉淀。","labels":["发生装置","净化收集","尾气处理","取样检验"]},{"substance":"钠投入滴有酚酞的水","path":"Na密度小先浮起；反应放热使其熔成小球；生成H₂推动游动并可能发声；生成NaOH使酚酞变红。每个现象都对应一个原因。","labels":["浮","熔","游响","红"]},{"substance":"新制氯水使有色纸条褪色","path":"Cl₂先与水建立平衡生成HCl和HClO；HClO具有强氧化性，破坏发色结构。若纸条干燥且无水，HClO难以形成，漂白现象不明显。","labels":["水参与","HClO负责","氧化漂白"]},{"substance":"NaCl与KCl混合样的焰色试验","path":"先把金属丝蘸盐酸灼烧至无色；直接观察黄色支持含Na，再透过蓝色钴玻璃观察是否出现紫色以判断K。结论只落到元素，不唯一锁定盐的种类。","labels":["规范清洗","黄色判Na","钴玻璃看K","证据不过界"]},{"substance":"Cl₂与NaOH的条件分叉","path":"冷稀碱生成Cl⁻和ClO⁻；热浓碱生成Cl⁻和ClO₃⁻。先由温度、浓度选产物，再用电子守恒确定比例，最后检查原子和电荷。","labels":["读条件","选含氯产物","电子守恒","原子电荷校验"]},{"substance":"84消毒液不能和洁厕剂混用","path":"酸性洁厕剂提供H⁺和Cl⁻，与ClO⁻反应生成Cl₂。写出离子方程式并指出Cl₂有毒，安全结论来自反应事实而不是生活口号。","labels":["列实际粒子","写归中反应","识别Cl₂","给出安全结论"]}],"checkpoints":["我能用价态和类别区分Na₂O、Na₂O₂。","我能比较Na₂CO₃、NaHCO₃的四类性质。","我能列出新制氯水的主要粒子并说明各自作用。","我能写出Cl⁻检验的试剂、现象和结论边界。","我能写出焰色试验的洗涤、灼烧、蘸样和观察顺序，并说明证据边界。","我能依据冷稀或热浓条件写出Cl₂与碱的不同产物并用电子守恒校验。","我能从NaClO或Ca(ClO)₂追到HClO，并说明含氯消毒剂的混用风险。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h1_nacl$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_NACL' and skill_id = 'H1_NACL';

update public.chem_knowledge_cards
set structured_content = $card_h2_rate${"skillId":"H2_RATE","version":2,"intro":"化学反应速率回答“反应有多快”，不是“最后能进行到什么程度”。先学会用浓度变化表示平均速率，再用有效碰撞解释浓度、压强、温度、催化剂等因素。","overview":["平均速率v=|Δc|/Δt，通常取正值；必须写明用哪一种物质表示。","同一反应中，不同物质表示的速率之比等于化学计量数之比。","浓度或气体分压影响碰撞频率；温度显著影响活化分子比例；催化剂降低反应途径的活化能。","速率变化与平衡移动要分开：反应可以变快但平衡组成不变。","实验测速要先选与反应进程单调对应、容易连续测量的量；出现“先慢—后快—再慢”时还要辨认自催化和诱导期信息。"],"visualSummary":{"kind":"network","title":"哪些因素改变反应速率","center":"反应速率","groups":[{"label":"浓度/分压","items":["碰撞频率↑"]},{"label":"温度","items":["活化分子比例↑"]},{"label":"催化剂","items":["活化能Ea↓"]},{"label":"计量关系","items":["速率比=系数比"]}]},"sections":[{"title":"速率的定义和计算","summary":"先统一物质、时间和单位，再比较。","items":[{"label":"平均反应速率","rule":"一段时间内某物质浓度变化的绝对值与时间间隔之比，v=|Δc|/Δt。","examples":["常用单位mol·L⁻¹·s⁻¹或mol·L⁻¹·min⁻¹。","【示范：用浓度变化算平均速率】某反应中A在20 s内由0.80降至0.40 mol·L⁻¹，则v(A)=|0.40-0.80|/20=0.020 mol·L⁻¹·s⁻¹。反应物也取正值；固体本身不用浓度变化表示。"],"visualSteps":["平均反应速率","确定时间段","浓度变化取绝对值","除以时间","单位完整"]},{"label":"反应物和生成物都取正值","rule":"反应物浓度下降、生成物浓度上升；中学比较速率时通常取变化量绝对值。","examples":["【示范：用浓度变化算平均速率】某反应中A在20 s内由0.80降至0.40 mol·L⁻¹，则v(A)=|0.40-0.80|/20=0.020 mol·L⁻¹·s⁻¹。反应物也取正值；固体本身不用浓度变化表示。"],"visualSteps":["反应物和生成物都取正值","确定时间段","浓度变化取绝对值","除以时间","单位完整"]},{"label":"固体和纯液体","rule":"其“浓度”视为常数，通常不用它们的浓度变化表示速率；可用气体体积、质量等实验量间接反映。","examples":["【示范：用浓度变化算平均速率】某反应中A在20 s内由0.80降至0.40 mol·L⁻¹，则v(A)=|0.40-0.80|/20=0.020 mol·L⁻¹·s⁻¹。反应物也取正值；固体本身不用浓度变化表示。"],"visualSteps":["固体和纯液体","确定时间段","浓度变化取绝对值","除以时间","单位完整"]}]},{"title":"不同物质的速率怎样换算","summary":"系数不同，数值不同，但描述的是同一个反应进程。","items":[{"label":"计量数关系","rule":"对aA+bB→cC+dD，有v(A):v(B):v(C):v(D)=a:b:c:d。","examples":["【示范：N₂+3H₂→2NH₃的速率换算】若v(N₂)=0.20 mol·L⁻¹·s⁻¹，则v(H₂)=0.60、v(NH₃)=0.40；比较“反应快慢”时可把各自速率除以对应计量数，得到同一个归一化速率。"],"visualSteps":["计量数关系","读计量系数","按比例换算","统一单位","必要时归一化"]},{"label":"归一化比较","rule":"若要比较不同反应或不同表示物，应使用v/计量数或题目定义的统一反应速率。","examples":["【示范：N₂+3H₂→2NH₃的速率换算】若v(N₂)=0.20 mol·L⁻¹·s⁻¹，则v(H₂)=0.60、v(NH₃)=0.40；比较“反应快慢”时可把各自速率除以对应计量数，得到同一个归一化速率。"],"visualSteps":["归一化比较","读计量系数","按比例换算","统一单位","必要时归一化"]},{"label":"三段式辅助","rule":"列起始浓度、变化浓度、某时刻浓度，再由变化量和时间计算。","examples":["【示范：N₂+3H₂→2NH₃的速率换算】若v(N₂)=0.20 mol·L⁻¹·s⁻¹，则v(H₂)=0.60、v(NH₃)=0.40；比较“反应快慢”时可把各自速率除以对应计量数，得到同一个归一化速率。"],"visualSteps":["三段式辅助","读计量系数","按比例换算","统一单位","必要时归一化"]}]},{"title":"有效碰撞模型","summary":"只有方向合适且能量足够的碰撞才可能导致反应。","items":[{"label":"活化分子与有效碰撞","rule":"具有足够能量的粒子更可能跨越能垒；碰撞方向也要合适。","examples":["【示范：为什么升温通常明显加快反应】升温后粒子平均动能增大，超过活化能的粒子比例明显增加，且合适方向的有效碰撞增多；所以不能只写“分子运动变快”。"],"visualSteps":["活化分子与有效碰撞","粒子能量变化","活化分子比例","有效碰撞次数","宏观速率"]},{"label":"活化能","rule":"从反应物状态到过渡区域所需跨越的最低能垒。活化能越低，在同温度下通常越易反应。","examples":["【示范：为什么升温通常明显加快反应】升温后粒子平均动能增大，超过活化能的粒子比例明显增加，且合适方向的有效碰撞增多；所以不能只写“分子运动变快”。"],"visualSteps":["活化能","粒子能量变化","活化分子比例","有效碰撞次数","宏观速率"]},{"label":"微观解释要求","rule":"回答影响因素时要说清“哪个量改变—有效碰撞怎样改变—速率怎样变”。","examples":["【示范：为什么升温通常明显加快反应】升温后粒子平均动能增大，超过活化能的粒子比例明显增加，且合适方向的有效碰撞增多；所以不能只写“分子运动变快”。"],"visualSteps":["微观解释要求","粒子能量变化","活化分子比例","有效碰撞次数","宏观速率"]}]},{"title":"常见因素逐一解释","summary":"不要用同一句“分子运动加快”解释所有因素。","items":[{"label":"浓度","rule":"溶液反应物浓度增大，单位体积内反应粒子数增多，碰撞频率通常增大。","examples":["【示范：大理石与盐酸的控制变量组】分别改变HCl浓度、温度、大理石颗粒大小；每组只改一个因素并用相同体积CO₂所需时间比较。粉碎增大接触面积，升温提高活化分子比例，增浓度提高碰撞频率。"],"visualSteps":["浓度","一次只改一项","浓度","温度","接触面积"]},{"label":"气体压强","rule":"恒温压缩使气体体积减小、反应组分浓度或分压增大，速率通常增大；恒容加惰性气体时反应组分浓度不变。","examples":["【示范：大理石与盐酸的控制变量组】分别改变HCl浓度、温度、大理石颗粒大小；每组只改一个因素并用相同体积CO₂所需时间比较。粉碎增大接触面积，升温提高活化分子比例，增浓度提高碰撞频率。"],"visualSteps":["气体压强","一次只改一项","浓度","温度","接触面积"]},{"label":"温度","rule":"升温使粒子平均动能增大，更重要的是活化分子百分数显著增大，有效碰撞增多。","examples":["【示范：大理石与盐酸的控制变量组】分别改变HCl浓度、温度、大理石颗粒大小；每组只改一个因素并用相同体积CO₂所需时间比较。粉碎增大接触面积，升温提高活化分子比例，增浓度提高碰撞频率。"],"visualSteps":["温度","一次只改一项","浓度","温度","接触面积"]},{"label":"催化剂","rule":"提供活化能较低的新途径，同时加快正、逆反应；不改变反应物和生成物能量差，也不改变平衡常数。","examples":["【示范：大理石与盐酸的控制变量组】分别改变HCl浓度、温度、大理石颗粒大小；每组只改一个因素并用相同体积CO₂所需时间比较。粉碎增大接触面积，升温提高活化分子比例，增浓度提高碰撞频率。"],"visualSteps":["催化剂","一次只改一项","浓度","温度","接触面积"]},{"label":"接触面积","rule":"固体粉碎后接触面积增大，暴露的反应位点增多，非均相反应通常加快。","examples":["【示范：大理石与盐酸的控制变量组】分别改变HCl浓度、温度、大理石颗粒大小；每组只改一个因素并用相同体积CO₂所需时间比较。粉碎增大接触面积，升温提高活化分子比例，增浓度提高碰撞频率。"],"visualSteps":["接触面积","一次只改一项","浓度","温度","接触面积"]}]},{"title":"图像与探究实验","summary":"图像先读轴，实验先控变量。","items":[{"label":"浓度—时间图","rule":"曲线斜率绝对值反映瞬时速率；曲线越陡，速率越快；达到平台不一定说明反应物耗尽，也可能达到平衡。","examples":["【示范：读浓度图和能量图】浓度—时间曲线起初最陡，说明初速最大，后来变平说明速率减慢；能量图加催化剂后峰降低但始末位置不变。探究时用相同反应进度所需时间作可比指标。"],"visualSteps":["浓度—时间图","先认横纵轴","斜率看速率","峰高看活化能","控制变量"]},{"label":"能量—反应历程图","rule":"峰高对应活化能；有催化剂的路径峰更低，始态终态和ΔH不变。","examples":["【示范：读浓度图和能量图】浓度—时间曲线起初最陡，说明初速最大，后来变平说明速率减慢；能量图加催化剂后峰降低但始末位置不变。探究时用相同反应进度所需时间作可比指标。"],"visualSteps":["能量—反应历程图","先认横纵轴","斜率看速率","峰高看活化能","控制变量"]},{"label":"控制变量","rule":"探究某因素时只改变该因素，其他条件尽量相同；用相同反应进度所需时间或单位时间变化量比较。","examples":["【示范：读浓度图和能量图】浓度—时间曲线起初最陡，说明初速最大，后来变平说明速率减慢；能量图加催化剂后峰降低但始末位置不变。探究时用相同反应进度所需时间作可比指标。"],"visualSteps":["控制变量","先认横纵轴","斜率看速率","峰高看活化能","控制变量"]}]},{"title":"测速信号、自催化与诱导期图像","summary":"把化学变化翻译成仪器能看到的量，再把曲线每一段还原为反应速率变化。","items":[{"label":"选择可观测量的三条标准","rule":"可观测量应随反应进程有明确、最好单调的变化，测量本身不明显干扰反应，并且变化幅度足以区分。常用气体体积或压强、体系质量、颜色或吸光变化、pH、导电性、沉淀浑浊度；必须结合具体反应选，不能把任何一个量通用到所有体系。","examples":["【示范：锌与稀硫酸测速】反应产生H₂，可记录相同时间内H₂体积，或达到同一H₂体积所需时间；若装置密闭则可测压强变化，若开放称量则可测逸气导致的质量减少。三种信号都要先保证气密、温度等条件一致。"],"visualSteps":["反应进程→H₂增多","选体积/压强/失重信号","统一条件再比较"],"caution":"只要求高中实验可观测量与图像推理；具体传感器原理和复杂数据拟合不进入本模块。"},{"label":"用曲线斜率读瞬时快慢","rule":"累计气体体积—时间图中，某点切线斜率越大，生成气体的瞬时速率越大；反应初期、末期不一定是直线，所以不能用整段平均斜率代替所有时刻。达到平台表示该观测量不再增加，要结合限制量或平衡判断原因。","examples":["【示范：气体体积曲线的三段】曲线起初陡、中段变缓、最后平台：切线斜率依次减小到接近0，说明可观测生成速率降低；平台总高度反映最终气体量，不能直接代表初始速率。"],"visualSteps":["读横纵轴","切线斜率→瞬时速率","平台高度→最终量"],"caution":"图像只证明被测信号的变化；若存在漏气、溶解或温度变化，需要先排除这些实验干扰。"},{"label":"自催化：产物让反应越做越快","rule":"某些反应生成的产物本身能催化该反应。开始时催化产物少，反应较慢；产物逐渐积累后反应加快；后期反应物浓度下降又使反应变慢，因此速率—时间图可能先升后降，累计量—时间图可能先平缓、再陡、后趋于平台。","examples":["【示范：酸性高锰酸根与草酸根】题目若说明生成的Mn²⁺对反应有催化作用，则初始Mn²⁺少，褪色较慢；反应产生Mn²⁺后褪色加快；后期反应物消耗又变慢。加入少量Mn²⁺作对照会缩短前期缓慢阶段，这是自催化证据。"],"visualSteps":["产物Mn²⁺少→慢","Mn²⁺积累→加快","反应物减少→再慢"],"caution":"自催化身份应由教材事实或题给信息确认，不能仅凭一条S形曲线擅自指定某种产物为催化剂。"},{"label":"诱导期：可观测变化出现前的准备阶段","rule":"有些反应开始后需要先形成少量活性中间状态、消耗抑制因素或积累到检测阈值，宏观信号在一段时间内变化很小，这段称为诱导期。读图时把“信号暂时不明显”与“反应完全没有发生”分开，并用题给机理信息或对照实验解释。","examples":["【示范：图中前20 s颜色几乎不变】先确认横轴时间、纵轴颜色信号；0～20 s斜率很小可标为诱导段，20 s后斜率显著增大说明宏观变化加快。若预先加入题给活性物质后诱导段缩短，而最终产物量不变，可支持“前期需积累活性物质”。"],"visualSteps":["前段信号近水平","转折后斜率增大","用预加入对照检验原因"],"caution":"高中只按题给信息识别诱导期和自催化，不展开微观反应机理或复杂速率方程。"}]}],"workedExamples":[{"substance":"用浓度变化算平均速率","path":"某反应中A在20 s内由0.80降至0.40 mol·L⁻¹，则v(A)=|0.40-0.80|/20=0.020 mol·L⁻¹·s⁻¹。反应物也取正值；固体本身不用浓度变化表示。","labels":["确定时间段","浓度变化取绝对值","除以时间","单位完整"]},{"substance":"N₂+3H₂→2NH₃的速率换算","path":"若v(N₂)=0.20 mol·L⁻¹·s⁻¹，则v(H₂)=0.60、v(NH₃)=0.40；比较“反应快慢”时可把各自速率除以对应计量数，得到同一个归一化速率。","labels":["读计量系数","按比例换算","统一单位","必要时归一化"]},{"substance":"为什么升温通常明显加快反应","path":"升温后粒子平均动能增大，超过活化能的粒子比例明显增加，且合适方向的有效碰撞增多；所以不能只写“分子运动变快”。","labels":["粒子能量变化","活化分子比例","有效碰撞次数","宏观速率"]},{"substance":"大理石与盐酸的控制变量组","path":"分别改变HCl浓度、温度、大理石颗粒大小；每组只改一个因素并用相同体积CO₂所需时间比较。粉碎增大接触面积，升温提高活化分子比例，增浓度提高碰撞频率。","labels":["一次只改一项","浓度","温度","接触面积"]},{"substance":"读浓度图和能量图","path":"浓度—时间曲线起初最陡，说明初速最大，后来变平说明速率减慢；能量图加催化剂后峰降低但始末位置不变。探究时用相同反应进度所需时间作可比指标。","labels":["先认横纵轴","斜率看速率","峰高看活化能","控制变量"]},{"substance":"恒容充入He","path":"容器体积和反应组分物质的量不变，所以反应组分浓度、分压均不变，正逆速率不因He直接改变；总压增大不等于有效压缩。","labels":["看分压而非总压","恒容","速率基本不变"]},{"substance":"测速信息图选择器","path":"先圈反应中单调变化的气体、质量、颜色、酸碱性或导电性，再选可连续测量的信号，最后检查装置和测量是否反过来改变温度、压强或浓度。","labels":["圈变化物理量","选传感信号","排除测量干扰"]}],"checkpoints":["我能用v=|Δc|/Δt计算并写对单位。","我会用计量数换算不同物质表示的速率。","我能分别解释浓度、温度和催化剂的微观原因。","我不会把“反应加快”自动说成“平衡向右移动”。","我能为具体反应选择合适测速量。","我能从曲线区分平均速率、瞬时斜率、自催化与诱导期。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h2_rate$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H2_RATE' and skill_id = 'H2_RATE';

update public.chem_knowledge_cards
set structured_content = $card_h2_equil${"skillId":"H2_EQUIL","version":2,"intro":"化学平衡只出现在一定条件下的可逆反应中。达到平衡不是反应停止，而是正逆反应仍在进行且速率相等；条件改变后，先看瞬间速率，再看移动方向和新平衡。","overview":["平衡标志：同一物理量正逆方向对应的速率相等，各组分含量保持不变。","移动方向由v正与v逆的瞬间大小决定：v正>v逆向右，v正<v逆向左。","浓度、压强、温度可改变平衡；催化剂只缩短到达平衡的时间。","勒夏特列原理说的是“减弱改变”，不是“完全抵消改变”。"],"visualSummary":{"kind":"balance","title":"反应方向与平衡的两层判断","center":"方向≠快慢","groups":[{"label":"能否自发｜定性","items":["焓变因素","熵变因素","温度改变倾向"]},{"label":"v正＞v逆","items":["向右移动","直到新平衡"]},{"label":"v正＜v逆","items":["向左移动","直到新平衡"]}]},"sections":[{"title":"可逆反应与动态平衡","summary":"先确定这个体系是否真的可以谈平衡。","items":[{"label":"可逆反应","rule":"同一条件下既能向正方向又能向逆方向进行，用可逆号表示；反应物和生成物共存。","examples":["【示范：N₂和H₂怎样建立平衡】密闭容器中开始只有N₂、H₂，v正大而v逆近0；NH₃增加后v逆上升，直到v正=v逆且都不为0，N₂、H₂、NH₃浓度保持不变。"],"visualSteps":["可逆反应","可逆反应共存","正逆速率变化","速率相等","组成不变"]},{"label":"平衡建立","rule":"起初v正较大、v逆较小；随组成变化，v正减小、v逆增大，直到相等。","examples":["【示范：N₂和H₂怎样建立平衡】密闭容器中开始只有N₂、H₂，v正大而v逆近0；NH₃增加后v逆上升，直到v正=v逆且都不为0，N₂、H₂、NH₃浓度保持不变。"],"visualSteps":["平衡建立","可逆反应共存","正逆速率变化","速率相等","组成不变"]},{"label":"动态与定态","rule":"平衡时v正=v逆且均不为0，宏观组成保持不变。","caution":"“各物质浓度相等”不是平衡必要条件。","examples":["【示范：N₂和H₂怎样建立平衡】密闭容器中开始只有N₂、H₂，v正大而v逆近0；NH₃增加后v逆上升，直到v正=v逆且都不为0，N₂、H₂、NH₃浓度保持不变。"],"visualSteps":["动态与定态","可逆反应共存","正逆速率变化","速率相等","组成不变"]}]},{"title":"怎样判断达到平衡","summary":"标志必须指向同一反应的正逆过程相等或某组成量不再变化。","items":[{"label":"直接标志","rule":"v正=v逆，但若用不同物质表示，要按计量数换算后再比较。","examples":["【示范：颜色不再变化能否判平衡】对2NO₂⇌N₂O₄，若温度体积固定，颜色持续不变可表示NO₂浓度不再变，是平衡标志；若某总量在整个反应中本来就不变，则它“不变”不能作标志。"],"visualSteps":["直接标志","选会随进程变化的量","保持不变","排除恒定总量","回到v正=v逆"]},{"label":"间接标志","rule":"某反应物或生成物的浓度、物质的量分数、颜色等保持不变。","examples":["【示范：颜色不再变化能否判平衡】对2NO₂⇌N₂O₄，若温度体积固定，颜色持续不变可表示NO₂浓度不再变，是平衡标志；若某总量在整个反应中本来就不变，则它“不变”不能作标志。"],"visualSteps":["间接标志","选会随进程变化的量","保持不变","排除恒定总量","回到v正=v逆"]},{"label":"不可靠表述","rule":"总物质的量、总压、密度或平均摩尔质量只有在该反应中会随进程改变时，保持不变才可作标志。","examples":["【示范：颜色不再变化能否判平衡】对2NO₂⇌N₂O₄，若温度体积固定，颜色持续不变可表示NO₂浓度不再变，是平衡标志；若某总量在整个反应中本来就不变，则它“不变”不能作标志。"],"visualSteps":["不可靠表述","选会随进程变化的量","保持不变","排除恒定总量","回到v正=v逆"]}]},{"title":"条件改变后的三层判断","summary":"瞬间、移动过程、新平衡不能混成一句话。","items":[{"label":"第一层：瞬间速率","rule":"浓度变化会直接改变涉及该物质方向的速率；温度通常同时改变正逆速率且影响程度可不同；催化剂同时加快正逆反应，在原平衡点二者仍相等，不引起平衡移动。","examples":["【示范：升温后的三层过程】放热正反应升温瞬间正逆速率都增大，但逆反应增幅更大，出现v逆>v正；组成向逆向改变，直到新平衡v正=v逆。"],"visualSteps":["第一层：瞬间速率","瞬间速率跳变","判断净方向","组成逐步变化","建立新平衡"]},{"label":"第二层：移动方向","rule":"比较条件改变瞬间的v正和v逆；较大的一侧决定净反应方向。","examples":["【示范：升温后的三层过程】放热正反应升温瞬间正逆速率都增大，但逆反应增幅更大，出现v逆>v正；组成向逆向改变，直到新平衡v正=v逆。"],"visualSteps":["第二层：移动方向","瞬间速率跳变","判断净方向","组成逐步变化","建立新平衡"]},{"label":"第三层：新平衡","rule":"组成逐渐变化直到v正再次等于v逆；新平衡速率和旧平衡不一定相同。","examples":["【示范：升温后的三层过程】放热正反应升温瞬间正逆速率都增大，但逆反应增幅更大，出现v逆>v正；组成向逆向改变，直到新平衡v正=v逆。"],"visualSteps":["第三层：新平衡","瞬间速率跳变","判断净方向","组成逐步变化","建立新平衡"]}]},{"title":"浓度、压强、温度和催化剂","summary":"先明确改变作用在哪个变量上。","items":[{"label":"浓度","rule":"增加反应物或移走生成物通常使平衡向正方向移动；纯固体或纯液体的量在仍有固相时通常不写成浓度影响。","examples":["【示范：N₂+3H₂⇌2NH₃逐个改条件】加N₂通常右移；恒温压缩向气体计量数少的右侧移动；升温因正向放热而左移；催化剂只缩短达平衡时间；恒容加He时反应气体分压不变，通常不移。"],"visualSteps":["浓度","浓度","压强","温度","催化剂与惰性气体"]},{"label":"压强","rule":"恒温改变体积时，只对有气体参加且两侧气体计量数和不同的平衡有方向性影响；增压偏向气体物质的量较少一侧。","examples":["【示范：N₂+3H₂⇌2NH₃逐个改条件】加N₂通常右移；恒温压缩向气体计量数少的右侧移动；升温因正向放热而左移；催化剂只缩短达平衡时间；恒容加He时反应气体分压不变，通常不移。"],"visualSteps":["压强","浓度","压强","温度","催化剂与惰性气体"]},{"label":"温度","rule":"把热量看作反应的一项：升温有利于吸热方向，降温有利于放热方向；温度还会改变K。","examples":["【示范：N₂+3H₂⇌2NH₃逐个改条件】加N₂通常右移；恒温压缩向气体计量数少的右侧移动；升温因正向放热而左移；催化剂只缩短达平衡时间；恒容加He时反应气体分压不变，通常不移。"],"visualSteps":["温度","浓度","压强","温度","催化剂与惰性气体"]},{"label":"催化剂","rule":"同等意义上加快正逆反应，使更快达到平衡，但不改变平衡组成和K。","examples":["【示范：N₂+3H₂⇌2NH₃逐个改条件】加N₂通常右移；恒温压缩向气体计量数少的右侧移动；升温因正向放热而左移；催化剂只缩短达平衡时间；恒容加He时反应气体分压不变，通常不移。"],"visualSteps":["催化剂","浓度","压强","温度","催化剂与惰性气体"]},{"label":"惰性气体","rule":"恒容加入时反应组分浓度/分压不变，通常不移动；恒压加入导致体积增大、分压减小，等效于减压再判断。","examples":["【示范：N₂+3H₂⇌2NH₃逐个改条件】加N₂通常右移；恒温压缩向气体计量数少的右侧移动；升温因正向放热而左移；催化剂只缩短达平衡时间；恒容加He时反应气体分压不变，通常不移。"],"visualSteps":["惰性气体","浓度","压强","温度","催化剂与惰性气体"]}]},{"title":"勒夏特列原理与工业条件","summary":"平衡、速率、成本和安全往往需要折中。","items":[{"label":"减弱而非抵消","rule":"体系移动会减弱外界改变，但不可能把改变后的量完全恢复到原值。","examples":["【示范：合成氨条件为什么要折中】低温有利于放热正反应的平衡转化率，却使速率慢；高压有利于右移但设备成本和风险上升；催化剂提高速率而不改平衡组成，所以工业条件兼顾产率、速率、成本和安全。"],"visualSteps":["减弱而非抵消","减弱外界改变","适用可逆平衡","速率限度分开","工业多目标"]},{"label":"不能脱离可逆平衡","rule":"原理用于已达到或可达到平衡的体系，不用于解释所有化学现象。","examples":["【示范：合成氨条件为什么要折中】低温有利于放热正反应的平衡转化率，却使速率慢；高压有利于右移但设备成本和风险上升；催化剂提高速率而不改平衡组成，所以工业条件兼顾产率、速率、成本和安全。"],"visualSteps":["不能脱离可逆平衡","减弱外界改变","适用可逆平衡","速率限度分开","工业多目标"]},{"label":"工业折中","rule":"选择温度、压强和催化剂时要兼顾平衡转化率、反应速率、设备成本和安全；不要求死背精确工业参数。","examples":["【示范：合成氨条件为什么要折中】低温有利于放热正反应的平衡转化率，却使速率慢；高压有利于右移但设备成本和风险上升；催化剂提高速率而不改平衡组成，所以工业条件兼顾产率、速率、成本和安全。"],"visualSteps":["工业折中","减弱外界改变","适用可逆平衡","速率限度分开","工业多目标"]}]},{"title":"反应方向：焓变与熵变共同影响","summary":"反应有无自发进行的趋势，要同时看能量变化、体系混乱程度和温度；这里只作定性判断。","items":[{"label":"“有方向”不等于“进行完全”","rule":"在给定条件下有自发进行趋势，只说明体系具有向某方向变化的热力学倾向；最终能进行到什么程度还要看平衡，能否很快观察到还要看反应速率。","examples":["【示范：金刚石转化为石墨】热力学上可以有向更稳定状态转化的趋势，但常温下过程极慢，所以“有自发趋势”不能推出“马上发生”。"],"visualSteps":["判断方向趋势","再看平衡限度","另看反应速率","不把三者混同"]},{"label":"焓变因素","rule":"其他条件相近时，体系由较高能量状态走向较低能量状态更有利，因此放热往往是有利因素；但只凭放热或吸热不能对所有反应作绝对结论。","examples":["【示范：合成氨的能量因素】N₂+3H₂⇌2NH₃为放热反应，能量因素有利于正向；仍需结合熵变、温度、平衡和速率，不能只写“放热所以一定自发且完全”。"],"visualSteps":["判断吸放热","识别有利因素","加入熵与温度","避免单因素绝对化"]},{"label":"熵变因素","rule":"体系中粒子分散程度增大、气体粒子数增多等通常对应熵增，熵增往往是有利因素；熵变也不能脱离焓变和温度单独下结论。","examples":["【示范：CaCO₃受热分解】CaCO₃(s)生成CaO(s)和CO₂(g)，出现气体使体系分散程度增大，熵变因素有利于分解；该反应又吸热，所以升高温度更有利。"],"visualSteps":["观察粒子状态","判断分散程度","识别熵变因素","联系温度"]},{"label":"两因素与温度的定性组合","rule":"放热且熵增时两种因素通常都支持正向；吸热且熵减时通常都不支持正向；一项有利、一项不利时，温度可能改变哪一因素占主导。","examples":["【示范：比较合成氨与碳酸钙分解】合成氨放热且气体粒子数减少，降低温度在热力学上更有利；CaCO₃分解吸热且生成气体，升高温度更有利。两例都还要另行讨论反应速率。"],"visualSteps":["列焓变因素","列熵变因素","判断温度影响","分开方向与速率"],"caution":"福建高中范围只要求焓变、熵变和温度的定性认识，不建立大学热力学定量计算体系。"}]}],"workedExamples":[{"substance":"N₂和H₂怎样建立平衡","path":"密闭容器中开始只有N₂、H₂，v正大而v逆近0；NH₃增加后v逆上升，直到v正=v逆且都不为0，N₂、H₂、NH₃浓度保持不变。","labels":["可逆反应共存","正逆速率变化","速率相等","组成不变"]},{"substance":"颜色不再变化能否判平衡","path":"对2NO₂⇌N₂O₄，若温度体积固定，颜色持续不变可表示NO₂浓度不再变，是平衡标志；若某总量在整个反应中本来就不变，则它“不变”不能作标志。","labels":["选会随进程变化的量","保持不变","排除恒定总量","回到v正=v逆"]},{"substance":"升温后的三层过程","path":"放热正反应升温瞬间正逆速率都增大，但逆反应增幅更大，出现v逆>v正；组成向逆向改变，直到新平衡v正=v逆。","labels":["瞬间速率跳变","判断净方向","组成逐步变化","建立新平衡"]},{"substance":"N₂+3H₂⇌2NH₃逐个改条件","path":"加N₂通常右移；恒温压缩向气体计量数少的右侧移动；升温因正向放热而左移；催化剂只缩短达平衡时间；恒容加He时反应气体分压不变，通常不移。","labels":["浓度","压强","温度","催化剂与惰性气体"]},{"substance":"合成氨条件为什么要折中","path":"低温有利于放热正反应的平衡转化率，却使速率慢；高压有利于右移但设备成本和风险上升；催化剂提高速率而不改平衡组成，所以工业条件兼顾产率、速率、成本和安全。","labels":["减弱外界改变","适用可逆平衡","速率限度分开","工业多目标"]},{"substance":"放热反应升高温度","path":"升温瞬间正逆速率都增大，但吸热的逆反应增大得更多，于是v逆>v正，平衡向逆方向移动；达到新平衡后K减小。","labels":["先瞬间速率","再移动","温度改变K"]},{"substance":"N₂+3H₂⇌2NH₃恒温压缩","path":"体积减小使各气体分压增大；平衡移动会减弱压强增加，故向气体计量数较少的右侧移动。催化剂只加快到达新平衡。","labels":["左4份气体","右2份气体","增压右移"]},{"substance":"CaCO₃受热分解的方向判断","path":"反应吸热，能量因素不利；生成CO₂气体使分散程度增大，熵变因素有利。升高温度时吸热、熵增方向更有利，但实际分解快慢仍受活化能影响。","labels":["判吸热","判熵增","联系高温","方向与速率分开"]},{"substance":"合成氨的方向、限度和速率","path":"正向放热且气体粒子数减少。较低温度在热力学和平衡上更有利，但速率变慢；工业上使用合适温度和催化剂，是方向、限度与速率的综合调控。","labels":["焓熵双因素","温度影响方向","平衡限度","速率折中"]}],"checkpoints":["我能解释“动态平衡”而不是说反应停止。","我会把瞬间速率、移动方向、新平衡分开描述。","我知道压强影响的适用条件。","我能区分恒容和恒压加入惰性气体。","我能区分反应方向、平衡限度和反应速率。","我能用焓变、熵变和温度对反应方向作定性判断，但不会引入超纲定量公式。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h2_equil$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H2_EQUIL' and skill_id = 'H2_EQUIL';

update public.chem_knowledge_cards
set structured_content = $card_h2_ph_hydro${"skillId":"H2_PH_HYDRO","version":2,"intro":"水溶液问题先找粒子来源：强酸强碱完全电离，弱酸弱碱部分电离，盐可能水解，水本身也微弱电离。计算靠平衡常数，浓度关系靠电荷守恒、物料守恒和质子守恒。","overview":["水的离子积Kw=c(H⁺)c(OH⁻)，一定温度下固定；中性本质是c(H⁺)=c(OH⁻)。","pH=−lg c(H⁺)；只有25 ℃时才常用pH+pOH=14。","盐类水解看“弱者的离子”：弱酸根水解显碱性，弱碱阳离子水解显酸性。","任何溶液都满足电荷守恒；含某一来源物质的全部形态满足物料守恒。","滴定先做物质的量反应，再判断过量粒子与平衡，指示剂变色范围应落在pH突跃内。","水解条件变化要同时区分“水解程度”和“离子实际浓度”；蒸干要追踪挥发物；滴定要把规范操作与c待测的分子、分母误差连起来。"],"visualSummary":{"kind":"network","title":"水溶液先列粒子再计算","center":"溶液粒子清单","groups":[{"label":"酸碱","items":["Kw与pH"]},{"label":"水解","items":["弱者的离子"]},{"label":"守恒","items":["电荷守恒","物料/质子守恒"]},{"label":"滴定","items":["反应→过量→平衡"]}]},"sections":[{"title":"水的电离与Kw","summary":"纯水中也有极少量H⁺和OH⁻。","items":[{"label":"水的自偶电离","rule":"2H₂O⇌H₃O⁺+OH⁻，中学常简写H₂O⇌H⁺+OH⁻。","examples":["【示范：25 ℃纯水与升温后的中性水】25 ℃纯水c(H⁺)=c(OH⁻)=10⁻⁷ mol·L⁻¹，pH=7；升温使Kw变大时两者仍相等，所以仍中性，但pH可以小于7。"],"visualSteps":["水的自偶电离","写Kw","中性看浓度相等","温度改变Kw","不死背pH=7"]},{"label":"离子积","rule":"Kw=c(H⁺)c(OH⁻)，只随温度改变；25 ℃时约为1.0×10⁻¹⁴。","examples":["【示范：25 ℃纯水与升温后的中性水】25 ℃纯水c(H⁺)=c(OH⁻)=10⁻⁷ mol·L⁻¹，pH=7；升温使Kw变大时两者仍相等，所以仍中性，但pH可以小于7。"],"visualSteps":["离子积","写Kw","中性看浓度相等","温度改变Kw","不死背pH=7"]},{"label":"酸碱影响","rule":"加入酸或碱都使水的电离平衡左移；某些盐水解消耗H⁺或OH⁻，可促进水的电离。","examples":["【示范：25 ℃纯水与升温后的中性水】25 ℃纯水c(H⁺)=c(OH⁻)=10⁻⁷ mol·L⁻¹，pH=7；升温使Kw变大时两者仍相等，所以仍中性，但pH可以小于7。"],"visualSteps":["酸碱影响","写Kw","中性看浓度相等","温度改变Kw","不死背pH=7"]},{"label":"中性不等于pH=7","rule":"任何温度下中性都是c(H⁺)=c(OH⁻)；只有Kw=10⁻¹⁴时对应pH=7。","examples":["【示范：25 ℃纯水与升温后的中性水】25 ℃纯水c(H⁺)=c(OH⁻)=10⁻⁷ mol·L⁻¹，pH=7；升温使Kw变大时两者仍相等，所以仍中性，但pH可以小于7。"],"visualSteps":["中性不等于pH=7","写Kw","中性看浓度相等","温度改变Kw","不死背pH=7"]}]},{"title":"pH计算先分体系","summary":"不要看到pH就直接套同一个公式。","items":[{"label":"强酸强碱","rule":"先由完全电离求c(H⁺)或c(OH⁻)，再由Kw换算另一种离子，最后取负对数。","examples":["【示范：三类pH计算】强酸先由完全电离求H⁺；强碱先求OH⁻再用Kw换H⁺；酸碱混合先按n(H⁺)、n(OH⁻)中和，再用剩余量除总体积。弱酸弱碱则需Ka/Kb。"],"visualSteps":["强酸强碱","判体系","完全反应优先","求剩余浓度","负对数"]},{"label":"酸碱混合","rule":"先按n(H⁺)与n(OH⁻)中和，求剩余量，再除以混合后总体积。","caution":"体积能否直接相加以题目常规近似或已知条件为准。","examples":["【示范：三类pH计算】强酸先由完全电离求H⁺；强碱先求OH⁻再用Kw换H⁺；酸碱混合先按n(H⁺)、n(OH⁻)中和，再用剩余量除总体积。弱酸弱碱则需Ka/Kb。"],"visualSteps":["酸碱混合","判体系","完全反应优先","求剩余浓度","负对数"]},{"label":"弱酸弱碱或盐","rule":"要考虑电离或水解平衡，若题给Ka、Kb或Kh则按平衡计算；不可以当完全电离。","examples":["【示范：三类pH计算】强酸先由完全电离求H⁺；强碱先求OH⁻再用Kw换H⁺；酸碱混合先按n(H⁺)、n(OH⁻)中和，再用剩余量除总体积。弱酸弱碱则需Ka/Kb。"],"visualSteps":["弱酸弱碱或盐","判体系","完全反应优先","求剩余浓度","负对数"]},{"label":"极稀溶液","rule":"当外加酸碱浓度接近水自身电离量时，不能忽略水的贡献。","examples":["【示范：三类pH计算】强酸先由完全电离求H⁺；强碱先求OH⁻再用Kw换H⁺；酸碱混合先按n(H⁺)、n(OH⁻)中和，再用剩余量除总体积。弱酸弱碱则需Ka/Kb。"],"visualSteps":["极稀溶液","判体系","完全反应优先","求剩余浓度","负对数"]}]},{"title":"盐类水解从离子来源判断","summary":"强酸强碱对应离子通常不水解，弱者的共轭离子会水解。","items":[{"label":"强酸弱碱盐","rule":"阳离子水解产生H⁺，溶液通常显酸性。","examples":["NH₄⁺+H₂O⇌NH₃·H₂O+H⁺。","【示范：NH₄Cl和CH₃COONa水解】NH₄⁺是弱碱的共轭酸，水解产生H⁺，NH₄Cl显酸性；CH₃COO⁻是弱酸的共轭碱，水解产生OH⁻，CH₃COONa显碱性。加对应酸碱或升温要再看平衡。"],"visualSteps":["强酸弱碱盐","先完全电离","找弱者离子","写水解","判断酸碱性"]},{"label":"强碱弱酸盐","rule":"阴离子水解产生OH⁻，溶液通常显碱性。","examples":["CH₃COO⁻+H₂O⇌CH₃COOH+OH⁻。","【示范：NH₄Cl和CH₃COONa水解】NH₄⁺是弱碱的共轭酸，水解产生H⁺，NH₄Cl显酸性；CH₃COO⁻是弱酸的共轭碱，水解产生OH⁻，CH₃COONa显碱性。加对应酸碱或升温要再看平衡。"],"visualSteps":["强碱弱酸盐","先完全电离","找弱者离子","写水解","判断酸碱性"]},{"label":"弱酸弱碱盐","rule":"酸碱性取决于相应Ka与Kb强弱，不能只靠类别一句话判断。","examples":["【示范：NH₄Cl和CH₃COONa水解】NH₄⁺是弱碱的共轭酸，水解产生H⁺，NH₄Cl显酸性；CH₃COO⁻是弱酸的共轭碱，水解产生OH⁻，CH₃COONa显碱性。加对应酸碱或升温要再看平衡。"],"visualSteps":["弱酸弱碱盐","先完全电离","找弱者离子","写水解","判断酸碱性"]},{"label":"水解应用","rule":"可解释盐溶液酸碱性、泡沫灭火、某些盐的保存与制备、除杂和离子浓度关系。","examples":["【示范：NH₄Cl和CH₃COONa水解】NH₄⁺是弱碱的共轭酸，水解产生H⁺，NH₄Cl显酸性；CH₃COO⁻是弱酸的共轭碱，水解产生OH⁻，CH₃COONa显碱性。加对应酸碱或升温要再看平衡。"],"visualSteps":["水解应用","先完全电离","找弱者离子","写水解","判断酸碱性"]}]},{"title":"三大守恒","summary":"守恒关系先写来源，再写各形态，最后检查电荷系数。","items":[{"label":"电荷守恒","rule":"溶液总体电中性：所有阳离子电荷浓度之和=所有阴离子电荷浓度之和；多价离子要乘电荷数。","examples":["【示范：CH₃COONa的三大守恒】物料守恒c(Na⁺)=c(CH₃COO⁻)+c(CH₃COOH)；电荷守恒c(Na⁺)+c(H⁺)=c(CH₃COO⁻)+c(OH⁻)；质子守恒可由两式组合得到。"],"visualSteps":["电荷守恒","列全部粒子","按来源守物料","按电荷系数守电荷","组合质子关系"]},{"label":"物料守恒","rule":"某一组分进入溶液的总量等于它以各种形态存在的浓度之和。","examples":["Na₂CO₃溶液中与碳有关的总量含CO₃²⁻、HCO₃⁻、H₂CO₃等形态。","【示范：CH₃COONa的三大守恒】物料守恒c(Na⁺)=c(CH₃COO⁻)+c(CH₃COOH)；电荷守恒c(Na⁺)+c(H⁺)=c(CH₃COO⁻)+c(OH⁻)；质子守恒可由两式组合得到。"],"visualSteps":["物料守恒","列全部粒子","按来源守物料","按电荷系数守电荷","组合质子关系"]},{"label":"质子守恒","rule":"可由水解或电离前后的质子得失关系建立，也可由电荷守恒与物料守恒组合得到。","examples":["【示范：CH₃COONa的三大守恒】物料守恒c(Na⁺)=c(CH₃COO⁻)+c(CH₃COOH)；电荷守恒c(Na⁺)+c(H⁺)=c(CH₃COO⁻)+c(OH⁻)；质子守恒可由两式组合得到。"],"visualSteps":["质子守恒","列全部粒子","按来源守物料","按电荷系数守电荷","组合质子关系"]}]},{"title":"酸碱中和滴定","summary":"滴定曲线每个点都对应不同的主要粒子。","items":[{"label":"滴定前","rule":"溶液的pH由待测液本身的电离或水解情况决定。","examples":["【示范：强酸滴定弱碱的整条曲线】滴定前由弱碱电离定pH；滴定中先做中和再处理共轭体系；计量点只剩弱碱的共轭酸盐，通常显酸性；过量后由强酸主导。指示剂变色区应落在突跃内。"],"visualSteps":["滴定前","滴定前","混合区","计量点","过量区与终点"]},{"label":"滴定中","rule":"先做强反应的物质的量计算，再处理剩余弱电解质、共轭离子及水解。","examples":["【示范：强酸滴定弱碱的整条曲线】滴定前由弱碱电离定pH；滴定中先做中和再处理共轭体系；计量点只剩弱碱的共轭酸盐，通常显酸性；过量后由强酸主导。指示剂变色区应落在突跃内。"],"visualSteps":["滴定中","滴定前","混合区","计量点","过量区与终点"]},{"label":"化学计量点","rule":"酸碱恰好按化学计量反应，但pH不一定为7，取决于产物是否水解和温度。","examples":["【示范：强酸滴定弱碱的整条曲线】滴定前由弱碱电离定pH；滴定中先做中和再处理共轭体系；计量点只剩弱碱的共轭酸盐，通常显酸性；过量后由强酸主导。指示剂变色区应落在突跃内。"],"visualSteps":["化学计量点","滴定前","混合区","计量点","过量区与终点"]},{"label":"指示剂和操作","rule":"变色范围应落在突跃范围；读数、润洗、气泡和终点判断会造成方向明确的误差。","examples":["【示范：强酸滴定弱碱的整条曲线】滴定前由弱碱电离定pH；滴定中先做中和再处理共轭体系；计量点只剩弱碱的共轭酸盐，通常显酸性；过量后由强酸主导。指示剂变色区应落在突跃内。"],"visualSteps":["指示剂和操作","滴定前","混合区","计量点","过量区与终点"]}]},{"title":"水解条件与蒸发所得物","summary":"先写水解方程式，再判断哪种粒子被加入、移走或因挥发离开体系。","items":[{"label":"稀释常使水解程度增大，但pH未必增大","rule":"盐的水解可看作离子与水建立的平衡。加水稀释通常促进水解比例增大，但所有溶质粒子浓度同时下降；对显碱性的弱酸盐，水解程度可增大而c(OH⁻)仍通常减小，所以pH通常降低并向中性靠近。必须把“比例”和“浓度”分开。","examples":["【示范：醋酸钠溶液稀释】CH₃COO⁻+H₂O⇌CH₃COOH+OH⁻。加水后水解百分比增大，但单位体积内总醋酸根体系变稀，c(OH⁻)通常减小，故碱性减弱、pH向7靠近。"],"visualSteps":["稀释→总浓度↓","水解比例↑","c(OH⁻)通常↓→pH靠近中性"],"caution":"结论限于高中常见稀溶液定性判断；若题给浓度、常数或极稀条件，应按题给数据计算。"},{"label":"温度和加酸加碱都要落到平衡式","rule":"课内盐类水解通常按吸热过程理解，升温常促进水解；加入能消耗水解生成H⁺或OH⁻的试剂会促进水解，加入同类生成物会抑制。最终酸碱性还要看加入试剂本身是否过量，不能只说“平衡右移”。","examples":["【示范：氯化铵水解条件】NH₄⁺+H₂O⇌NH₃·H₂O+H⁺。升温通常促进水解；加入少量酸使H⁺增加，平衡左移；加入适量碱消耗H⁺，可使平衡右移，但若碱过量，溶液pH主要由剩余OH⁻决定。"],"visualSteps":["写水解式","看H⁺被加/被消耗","平衡方向与最终pH分开"],"caution":"若题目给出具体热效应或发生其他反应，以题给信息优先；不把一般水解趋势套到有沉淀、氧化还原等并发过程。"},{"label":"蒸发与蒸干：把挥发物画出体系","rule":"蒸发减少水，使溶液浓缩并可能让水解产生的挥发性酸或碱离开，水解被继续推动；若氢氧化物受热又分解，最终固体可能变成氧化物。判断时依次写水解、挥发、受热分解三层，不能仅凭原盐名称。","examples":["【示范：AlCl₃溶液蒸干并灼烧】Al³⁺水解形成Al(OH)₃倾向并生成H⁺，Cl⁻与H⁺对应的HCl可随加热挥发，使水解继续；蒸干所得不能简单视为无水AlCl₃，进一步灼烧Al(OH)₃可得Al₂O₃。"],"visualSteps":["Al³⁺水解","HCl挥发推动","灼烧→Al₂O₃"],"caution":"是否蒸干得到原盐取决于盐的水解、挥发和热稳定性；福建高中题通常会给出或默认教材范围内事实，不扩展到陌生盐的热分解细节。"}]},{"title":"酸碱滴定完整操作与误差","summary":"每个动作都服务于“标准液浓度可靠、所取待测体积准确、终点体积可读”。","items":[{"label":"滴定操作链从查漏到平行测定","rule":"先检查滴定管是否漏水；用蒸馏水洗净后再用待装液润洗2～3次，装液、排尖嘴气泡、调零并记录初读数。用移液管准确移取待测液至锥形瓶，加适当指示剂，边滴边振荡，近终点逐滴加入，待颜色变化保持约半分钟，记录末读数；重复至相邻结果符合题给要求。","examples":["【示范：强酸滴定强碱的一次完整流程】酸式滴定管装标准酸并排气泡；移液管取定体积碱液至锥形瓶，加指示剂；先快后慢滴加，近终点用洗瓶冲下瓶壁液滴，出现规定颜色并保持后读数；用末读数减初读数得本次体积。"],"visualSteps":["查漏/润洗/排泡","移取/加指示剂/滴定","终点读数/平行复测"],"caution":"指示剂按滴定突跃范围选择；具体颜色变化以所用指示剂和酸碱装液方向为准。"},{"label":"终点、计量点和读数不是一回事","rule":"化学计量点是酸碱按方程式恰好反应的理论状态；终点是指示剂给出的实验停止信号，两者应尽量接近。滴定体积必须用末读数减初读数，滴定管“0”在上方，读数增大表示放出液体增多。","examples":["【示范：初读数不为0也能正确计算】若初读数0.20 mL、末读数24.85 mL，则消耗体积为24.65 mL；不能把24.85 mL直接当消耗量，也不能把量筒的读数习惯套到滴定管。"],"visualSteps":["认清刻度方向","V用末−初","终点信号逼近计量点"],"caution":"读数通常记录到滴定管分度值的下一位；精度要求按实际仪器和题设执行。"},{"label":"误差树先写待测浓度公式","rule":"以一元酸碱等物质的量反应为例，c待测=c标准V标准/V待测。某错误若使记录的V标准偏大，计算结果偏大；若使实际移取的待测物质的量偏小而仍用标称V待测计算，结果偏小。先判直接量，再沿分子、分母传播。","examples":["【示范：尖嘴开始有气泡、结束时气泡消失】读数变化中包含了填充尖嘴却未进入锥形瓶的体积，所以记录的V标准大于真正参加反应的体积；按记录值计算时c待测偏高。"],"visualSteps":["气泡消失占用体积","V标准记录值↑","c待测计算值↑"],"caution":"计量关系不是1∶1时要带上方程式系数，但误差仍沿实际进入反应的物质的量和记录体积判断。"},{"label":"润洗和加水要看是否改变反应物质的量","rule":"滴定管未用标准液润洗会使标准液被管内水稀释，达到终点需放出更多体积，若仍用原标准浓度计算常使结果偏高；移液管未用待测液润洗会使移取样品被稀释，待测物质的量偏小，结果偏低；锥形瓶中加少量蒸馏水只改变总体积，不改变待测物质的量，通常无影响。","examples":["【示范：三种“有水”情境对比】标准液滴定管有水→标准液被稀释→V标准读数增大→结果偏高；待测液移液管有水→移入n待测减小→结果偏低；锥形瓶加水→n待测不变→终点所需标准液n不变→结果不变。"],"visualSteps":["先定位水在哪个器皿","判断是否改变n或标准液实际c","沿计算式判方向"],"caution":"若标准液浓度已在同样器皿状态下重新标定，误差条件会改变；高中常规题默认使用标签所给标准浓度。"}]}],"workedExamples":[{"substance":"25 ℃纯水与升温后的中性水","path":"25 ℃纯水c(H⁺)=c(OH⁻)=10⁻⁷ mol·L⁻¹，pH=7；升温使Kw变大时两者仍相等，所以仍中性，但pH可以小于7。","labels":["写Kw","中性看浓度相等","温度改变Kw","不死背pH=7"]},{"substance":"三类pH计算","path":"强酸先由完全电离求H⁺；强碱先求OH⁻再用Kw换H⁺；酸碱混合先按n(H⁺)、n(OH⁻)中和，再用剩余量除总体积。弱酸弱碱则需Ka/Kb。","labels":["判体系","完全反应优先","求剩余浓度","负对数"]},{"substance":"NH₄Cl和CH₃COONa水解","path":"NH₄⁺是弱碱的共轭酸，水解产生H⁺，NH₄Cl显酸性；CH₃COO⁻是弱酸的共轭碱，水解产生OH⁻，CH₃COONa显碱性。加对应酸碱或升温要再看平衡。","labels":["先完全电离","找弱者离子","写水解","判断酸碱性"]},{"substance":"CH₃COONa的三大守恒","path":"物料守恒c(Na⁺)=c(CH₃COO⁻)+c(CH₃COOH)；电荷守恒c(Na⁺)+c(H⁺)=c(CH₃COO⁻)+c(OH⁻)；质子守恒可由两式组合得到。","labels":["列全部粒子","按来源守物料","按电荷系数守电荷","组合质子关系"]},{"substance":"强酸滴定弱碱的整条曲线","path":"滴定前由弱碱电离定pH；滴定中先做中和再处理共轭体系；计量点只剩弱碱的共轭酸盐，通常显酸性；过量后由强酸主导。指示剂变色区应落在突跃内。","labels":["滴定前","混合区","计量点","过量区与终点"]},{"substance":"25 ℃、pH=3的强酸","path":"c(H⁺)=10⁻³ mol·L⁻¹；Kw=10⁻¹⁴，所以c(OH⁻)=10⁻¹¹ mol·L⁻¹。不能把pH=3理解为c(H⁺)=3。","labels":["负对数","Kw换算","单位mol·L⁻¹"]},{"substance":"NH₄Cl为何显酸性","path":"NH₄Cl完全电离为NH₄⁺和Cl⁻；Cl⁻来自强酸，水解很弱；NH₄⁺是弱碱NH₃·H₂O的共轭酸，和水反应生成H⁺，所以溶液显酸性。","labels":["先电离","找弱者","写水解","判断酸碱性"]},{"substance":"滴定误差三问","path":"错误让真正参加反应的n怎样变？仪器记录的V怎样变？计算仍代入哪个标称量？依次回答后再给偏高、偏低或无法确定。","labels":["真实n","记录V","计算代入量"]}],"checkpoints":["我能说明中性为什么不总是pH=7。","我会先中和再算酸碱混合。","我能写电荷守恒并正确乘多价离子系数。","我能判断化学计量点pH是否等于7。","我能区分水解程度、离子浓度与pH变化。","我能沿水解—挥发—分解判断蒸干所得物。","我能完整叙述滴定操作并推导常见误差。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h2_ph_hydro$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H2_PH_HYDRO' and skill_id = 'H2_PH_HYDRO';

update public.chem_knowledge_cards
set structured_content = $card_h2_electro${"skillId":"H2_ELECTRO","version":2,"intro":"电化学题先看能量来源：自发氧化还原产生电流的是原电池，外加电源推动非自发反应的是电解池。无论哪种装置，阳极氧化、阴极还原永远不变。","overview":["原电池：负极氧化、正极还原，电子经外电路由负极流向正极。","电解池：阳极接电源正极并氧化，阴极接电源负极并还原。","电子只走金属导线；溶液和盐桥中靠离子移动维持电中性。","写电极反应时先判断介质和实际放电粒子，再配原子、电荷和电子。","所有定量都可回到电子守恒：各电极转移电子的物质的量相等。"],"visualSummary":{"kind":"compare","title":"电化学四条主线","groups":[{"label":"阳极｜氧化","items":["原电池负极","电解池接正极"]},{"label":"阴极｜还原","items":["原电池正极","电解池接负极"]},{"label":"水溶液电解","items":["判放电粒子","合并总反应","看pH/浓度","加合适物质复原"]},{"label":"金属与腐蚀","items":["镀件作阴极","粗金属作阳极","酸性析H₂","中性吸O₂"]}]},"sections":[{"title":"原电池从零建立","summary":"一个自发氧化还原反应被分成两个空间分离的半反应。","items":[{"label":"构成与作用","rule":"两个电极、电解质和闭合回路使电子经外电路流动，把化学能转化为电能。","examples":["【示范：锌铜原电池四条线】Zn失电子作负极：Zn-2e⁻=Zn²⁺；Cu²⁺在正极得电子：Cu²⁺+2e⁻=Cu。电子从Zn经外电路到Cu；盐桥阴离子移向Zn侧、阳离子移向Cu侧。"],"visualSteps":["构成与作用","负极氧化","正极还原","电子外电路","离子内电路"]},{"label":"负极","rule":"发生氧化反应，放出电子；活泼金属常作负极，但最终以实际电极反应为准。","examples":["【示范：锌铜原电池四条线】Zn失电子作负极：Zn-2e⁻=Zn²⁺；Cu²⁺在正极得电子：Cu²⁺+2e⁻=Cu。电子从Zn经外电路到Cu；盐桥阴离子移向Zn侧、阳离子移向Cu侧。"],"visualSteps":["负极","负极氧化","正极还原","电子外电路","离子内电路"]},{"label":"正极","rule":"发生还原反应，接受外电路电子；电极材料可能只导电而不消耗。","examples":["【示范：锌铜原电池四条线】Zn失电子作负极：Zn-2e⁻=Zn²⁺；Cu²⁺在正极得电子：Cu²⁺+2e⁻=Cu。电子从Zn经外电路到Cu；盐桥阴离子移向Zn侧、阳离子移向Cu侧。"],"visualSteps":["正极","负极氧化","正极还原","电子外电路","离子内电路"]},{"label":"盐桥或离子膜","rule":"连通内电路并维持两侧电中性；阴离子通常移向负极区，阳离子移向正极区。","examples":["【示范：锌铜原电池四条线】Zn失电子作负极：Zn-2e⁻=Zn²⁺；Cu²⁺在正极得电子：Cu²⁺+2e⁻=Cu。电子从Zn经外电路到Cu；盐桥阴离子移向Zn侧、阳离子移向Cu侧。"],"visualSteps":["盐桥或离子膜","负极氧化","正极还原","电子外电路","离子内电路"]}]},{"title":"电解池从零建立","summary":"外电源强迫电子流动，把电能转化为化学能。","items":[{"label":"阳极与电源正极相连","rule":"电极或溶液中的粒子失电子，发生氧化。","examples":["【示范：电解CuCl₂溶液】常规浓度、惰性电极条件下，阳极接正极，Cl⁻失电子生成Cl₂；阴极接负极，Cu²⁺得电子析Cu。若题目给出很稀溶液或特殊条件，要再比较水与离子的放电。"],"visualSteps":["阳极与电源正极相连","辨电解池","阳极氧化","阴极还原","条件复核"]},{"label":"阴极与电源负极相连","rule":"电解质中的阳离子或水等粒子在阴极得到电子，发生还原。","examples":["【示范：电解CuCl₂溶液】常规浓度、惰性电极条件下，阳极接正极，Cl⁻失电子生成Cl₂；阴极接负极，Cu²⁺得电子析Cu。若题目给出很稀溶液或特殊条件，要再比较水与离子的放电。"],"visualSteps":["阴极与电源负极相连","辨电解池","阳极氧化","阴极还原","条件复核"]},{"label":"放电顺序","rule":"由电极材料、离子氧化还原能力、浓度和过电位等共同决定；中学常规体系按已学规律，陌生体系按题给信息。","examples":["【示范：电解CuCl₂溶液】常规浓度、惰性电极条件下，阳极接正极，Cl⁻失电子生成Cl₂；阴极接负极，Cu²⁺得电子析Cu。若题目给出很稀溶液或特殊条件，要再比较水与离子的放电。"],"visualSteps":["放电顺序","辨电解池","阳极氧化","阴极还原","条件复核"]},{"label":"惰性与活性电极","rule":"惰性电极主要导电；活性阳极可能优先溶解，直接参与反应。","examples":["【示范：电解CuCl₂溶液】常规浓度、惰性电极条件下，阳极接正极，Cl⁻失电子生成Cl₂；阴极接负极，Cu²⁺得电子析Cu。若题目给出很稀溶液或特殊条件，要再比较水与离子的放电。"],"visualSteps":["惰性与活性电极","辨电解池","阳极氧化","阴极还原","条件复核"]}]},{"title":"电极反应式的稳定写法","summary":"先写半反应，再用介质补齐。","items":[{"label":"1. 定氧化或还原","rule":"阳极写失电子，阴极写得电子，电子位置不能写反。","examples":["【示范：酸性介质写燃料电池电极式】先定燃料在阳极被氧化、O₂在阴极被还原；写骨架后用H₂O补O、H⁺补H、e⁻配电荷。两式倍乘消去电子后必须等于总反应。"],"visualSteps":["1. 定氧化或还原","定氧化还原","写骨架","按介质配平","相加核对"]},{"label":"2. 定实际粒子","rule":"判断是电极材料、溶质离子还是水参加，产物还受酸碱介质影响。","examples":["【示范：酸性介质写燃料电池电极式】先定燃料在阳极被氧化、O₂在阴极被还原；写骨架后用H₂O补O、H⁺补H、e⁻配电荷。两式倍乘消去电子后必须等于总反应。"],"visualSteps":["2. 定实际粒子","定氧化还原","写骨架","按介质配平","相加核对"]},{"label":"3. 配原子和电荷","rule":"先配核心元素，再用H₂O、H⁺或OH⁻按介质补H和O，最后用e⁻配电荷。","examples":["【示范：酸性介质写燃料电池电极式】先定燃料在阳极被氧化、O₂在阴极被还原；写骨架后用H₂O补O、H⁺补H、e⁻配电荷。两式倍乘消去电子后必须等于总反应。"],"visualSteps":["3. 配原子和电荷","定氧化还原","写骨架","按介质配平","相加核对"]},{"label":"4. 合并总反应","rule":"两极电子数配成相等后相加，删除两边相同粒子并检查是否与装置物质变化一致。","examples":["【示范：酸性介质写燃料电池电极式】先定燃料在阳极被氧化、O₂在阴极被还原；写骨架后用H₂O补O、H⁺补H、e⁻配电荷。两式倍乘消去电子后必须等于总反应。"],"visualSteps":["4. 合并总反应","定氧化还原","写骨架","按介质配平","相加核对"]}]},{"title":"离子迁移、膜和多室装置","summary":"膜不是让电子通过，而是控制离子通过。","items":[{"label":"电中性要求","rule":"某侧产生正电荷，就需阴离子迁入或阳离子迁出；由此判断迁移方向。","examples":["【示范：盐桥和阳离子膜怎么判方向】锌铜原电池中负极区Zn²⁺增加，盐桥阴离子移入；正极区Cu²⁺减少，阳离子移入。若换成选择膜，先看膜允许谁通过，再用各室电中性判断方向和数量。"],"visualSteps":["电中性要求","各室做电荷账","判断离子增减","看膜选择性","维持电中性"]},{"label":"选择性交换膜","rule":"阳离子膜主要允许阳离子通过，阴离子膜主要允许阴离子通过；作用可能是隔开产物、维持电荷或富集物质。","examples":["【示范：盐桥和阳离子膜怎么判方向】锌铜原电池中负极区Zn²⁺增加，盐桥阴离子移入；正极区Cu²⁺减少，阳离子移入。若换成选择膜，先看膜允许谁通过，再用各室电中性判断方向和数量。"],"visualSteps":["选择性交换膜","各室做电荷账","判断离子增减","看膜选择性","维持电中性"]},{"label":"电子与电流","rule":"电子在外电路由供电子处流向受电子处；传统电流方向与电子相反。","caution":"不能写“电子穿过电解质溶液或离子交换膜”。","examples":["【示范：盐桥和阳离子膜怎么判方向】锌铜原电池中负极区Zn²⁺增加，盐桥阴离子移入；正极区Cu²⁺减少，阳离子移入。若换成选择膜，先看膜允许谁通过，再用各室电中性判断方向和数量。"],"visualSteps":["电子与电流","各室做电荷账","判断离子增减","看膜选择性","维持电中性"]}]},{"title":"腐蚀、防护与定量","summary":"腐蚀是微小原电池，防护就是控制电极反应。","items":[{"label":"电化学腐蚀","rule":"较活泼区域作负极被氧化；酸性或中性含氧环境中正极反应不同。","examples":["【示范：铁的腐蚀与电子定量】酸性水膜中Fe作负极失电子，较活泼金属连接可作牺牲阳极；外加电流保护时被保护铁接电源负极。若转移0.20 mol e⁻，各电极产物都按半反应电子系数换算。"],"visualSteps":["电化学腐蚀","判腐蚀电极","选择防护方式","求n(e⁻)","换质量或气体"]},{"label":"牺牲阳极保护","rule":"连接更活泼金属，使其作负极优先溶解，被保护金属作正极。","examples":["【示范：铁的腐蚀与电子定量】酸性水膜中Fe作负极失电子，较活泼金属连接可作牺牲阳极；外加电流保护时被保护铁接电源负极。若转移0.20 mol e⁻，各电极产物都按半反应电子系数换算。"],"visualSteps":["牺牲阳极保护","判腐蚀电极","选择防护方式","求n(e⁻)","换质量或气体"]},{"label":"外加电流保护","rule":"用直流电源使被保护金属连接负极，成为阴极。","examples":["【示范：铁的腐蚀与电子定量】酸性水膜中Fe作负极失电子，较活泼金属连接可作牺牲阳极；外加电流保护时被保护铁接电源负极。若转移0.20 mol e⁻，各电极产物都按半反应电子系数换算。"],"visualSteps":["外加电流保护","判腐蚀电极","选择防护方式","求n(e⁻)","换质量或气体"]},{"label":"电子守恒计算","rule":"同一回路各电极通过电子的物质的量相等；用电极半反应把e⁻与质量、气体体积、离子浓度相连。","examples":["【示范：铁的腐蚀与电子定量】酸性水膜中Fe作负极失电子，较活泼金属连接可作牺牲阳极；外加电流保护时被保护铁接电源负极。若转移0.20 mol e⁻，各电极产物都按半反应电子系数换算。"],"visualSteps":["电子守恒计算","判腐蚀电极","选择防护方式","求n(e⁻)","换质量或气体"]}]},{"title":"水溶液电解：从两极反应追到整杯溶液","summary":"先判实际放电粒子，再合并总反应，最后判断pH、浓度和复原方法。","items":[{"label":"先判电极材料和实际放电粒子","rule":"活性阳极可能先溶解；惰性电极主要导电。阴、阳极上的水和溶质离子存在竞争，必须结合电极材料、离子性质、浓度和题给信息判断，不能只背固定顺序。","examples":["【示范：惰性电极电解CuSO₄】阴极Cu²⁺得电子析出Cu；阳极SO₄²⁻通常不放电，由水失电子生成O₂和H⁺。若阳极改为铜，阳极可优先发生Cu-2e⁻=Cu²⁺。"],"visualSteps":["看电极材料","列水与溶质粒子","判实际放电","写半反应"]},{"label":"合并总反应并判断pH和浓度","rule":"两极半反应按电子数相加后，才能判断溶液中哪些离子净增加或减少；pH变化来自总反应，不可只看单个电极。","examples":["【示范：惰性电极电解CuSO₄】阴极2Cu²⁺+4e⁻=2Cu，阳极2H₂O-4e⁻=O₂↑+4H⁺；合并后Cu²⁺减少、H⁺增加，溶液酸性增强。"],"visualSteps":["配平两极电子","合并总反应","找净增减粒子","判断pH与浓度"]},{"label":"电解后的复原","rule":"复原要补回实际从体系中移出的原子组合，并尽量不引入新杂质。若只电解出H₂和O₂可考虑补水；若析出金属并放出O₂，常需补相应金属氧化物等，具体由总反应决定。","examples":["【示范：CuSO₄溶液复原】惰性电极电解后析Cu、放O₂并生成H₂SO₄，可加入适量CuO：CuO+2H⁺=Cu²⁺+H₂O，使Cu²⁺和酸度回到原关系；只加CuSO₄会额外引入SO₄²⁻。"],"visualSteps":["读总反应损失","选不引杂质物质","补回相应原子","核对浓度关系"]}]},{"title":"电镀、精炼和电冶金：先看装置目的","summary":"同样遵守阳极氧化、阴极还原，但电极材料和电解质由生产目标决定。","items":[{"label":"电镀","rule":"待镀物作阴极，镀层金属离子在阴极还原；常用镀层金属作阳极补充相应离子，电解质含镀层金属离子。","examples":["【示范：铁件镀铜】铁件接电源负极作阴极：Cu²⁺+2e⁻=Cu；铜片接正极作阳极：Cu-2e⁻=Cu²⁺；CuSO₄溶液提供并维持Cu²⁺。"],"visualSteps":["明确镀层金属","镀件作阴极","镀层金属作阳极","写两极反应"]},{"label":"电解精炼","rule":"粗金属作阳极并溶解，纯金属薄片作阴极并析出目标金属。比目标金属不活泼的杂质可能形成阳极泥，较活泼杂质可能进入溶液，具体按题给性质判断。","examples":["【示范：粗铜精炼】阳极Cu-2e⁻=Cu²⁺，阴极Cu²⁺+2e⁻=Cu；纯铜在阴极增厚。不能把“所有杂质都进入阳极泥”作为绝对结论。"],"visualSteps":["粗金属阳极","目标金属溶解","纯片阴极析出","按性质追踪杂质"]},{"label":"电冶金","rule":"很活泼的金属不能从水溶液中直接电解析出，因为水或H⁺会优先在阴极还原，通常采用熔融盐或熔融氧化物电解。","examples":["【示范：熔融NaCl制钠】阴极Na⁺+e⁻=Na，阳极2Cl⁻-2e⁻=Cl₂；若改用NaCl水溶液，阴极主要生成H₂而不是Na。"],"visualSteps":["判断金属活泼性","排除水溶液","选择熔融电解质","写电极式"]}]},{"title":"金属腐蚀：析氢与吸氧两条阴极路线","summary":"铁失电子是共同主线，阴极反应由水膜的酸碱性和含氧情况决定。","items":[{"label":"化学腐蚀与电化学腐蚀","rule":"金属直接与氧化剂接触发生反应可视为化学腐蚀；当不纯金属在电解质水膜中形成微小原电池时，较活泼区域作负极溶解，属于电化学腐蚀。","examples":["【示范：潮湿空气中的钢铁】Fe和杂质碳在含盐水膜中形成微小原电池，Fe区发生Fe-2e⁻=Fe²⁺，电子流向较不活泼的区域。"],"visualSteps":["确认电解质水膜","找活泼区","负极金属溶解","电子流向阴极区"]},{"label":"析氢腐蚀","rule":"酸性较强且有可还原H⁺时，阴极可发生2H⁺+2e⁻=H₂↑；负极仍是金属失电子。总反应由两半反应相加。","examples":["【示范：铁在酸性水膜中腐蚀】负极Fe-2e⁻=Fe²⁺，正极2H⁺+2e⁻=H₂↑，总反应Fe+2H⁺=Fe²⁺+H₂↑。"],"visualSteps":["负极写Fe氧化","阴极写H⁺还原","电子数相等","相加得总反应"]},{"label":"吸氧腐蚀与铁锈形成","rule":"近中性或弱碱性、含氧水膜中，阴极常发生O₂+2H₂O+4e⁻=4OH⁻。Fe²⁺与OH⁻形成Fe(OH)₂，继续被O₂氧化并逐步形成铁锈。","examples":["【示范：中性食盐水中的铁】负极2Fe-4e⁻=2Fe²⁺，正极O₂+2H₂O+4e⁻=4OH⁻；随后Fe²⁺+2OH⁻=Fe(OH)₂↓，再被氧化成更高价含铁物质。"],"visualSteps":["Fe失电子","O₂得电子","生成Fe(OH)₂","继续氧化成锈"],"caution":"铁锈成分复杂，不能把整个过程压成唯一一步反应。"}]}],"workedExamples":[{"substance":"锌铜原电池四条线","path":"Zn失电子作负极：Zn-2e⁻=Zn²⁺；Cu²⁺在正极得电子：Cu²⁺+2e⁻=Cu。电子从Zn经外电路到Cu；盐桥阴离子移向Zn侧、阳离子移向Cu侧。","labels":["负极氧化","正极还原","电子外电路","离子内电路"]},{"substance":"电解CuCl₂溶液","path":"常规浓度、惰性电极条件下，阳极接正极，Cl⁻失电子生成Cl₂；阴极接负极，Cu²⁺得电子析Cu。若题目给出很稀溶液或特殊条件，要再比较水与离子的放电。","labels":["辨电解池","阳极氧化","阴极还原","条件复核"]},{"substance":"酸性介质写燃料电池电极式","path":"先定燃料在阳极被氧化、O₂在阴极被还原；写骨架后用H₂O补O、H⁺补H、e⁻配电荷。两式倍乘消去电子后必须等于总反应。","labels":["定氧化还原","写骨架","按介质配平","相加核对"]},{"substance":"盐桥和阳离子膜怎么判方向","path":"锌铜原电池中负极区Zn²⁺增加，盐桥阴离子移入；正极区Cu²⁺减少，阳离子移入。若换成选择膜，先看膜允许谁通过，再用各室电中性判断方向和数量。","labels":["各室做电荷账","判断离子增减","看膜选择性","维持电中性"]},{"substance":"铁的腐蚀与电子定量","path":"酸性水膜中Fe作负极失电子，较活泼金属连接可作牺牲阳极；外加电流保护时被保护铁接电源负极。若转移0.20 mol e⁻，各电极产物都按半反应电子系数换算。","labels":["判腐蚀电极","选择防护方式","求n(e⁻)","换质量或气体"]},{"substance":"锌铜原电池","path":"负极Zn−2e⁻=Zn²⁺；正极Cu²⁺+2e⁻=Cu；电子从Zn经导线流向Cu。盐桥阴离子移向Zn侧、阳离子移向Cu侧以维持电中性。","labels":["负极氧化","正极还原","电子走外电路","离子走内电路"]},{"substance":"电解CuSO₄溶液析铜","path":"阴极Cu²⁺+2e⁻=Cu。若外电路通过0.20 mol e⁻，析出Cu为0.10 mol，质量约6.4 g；另一电极也对应转移0.20 mol e⁻。","labels":["2 mol e⁻/mol Cu","电子守恒","再换质量"]},{"substance":"惰性电极电解CuSO₄并复原","path":"先写阴极Cu²⁺析铜、阳极水放氧的半反应；相加得Cu²⁺减少、H⁺增加。根据净损失选择CuO补回Cu²⁺并中和相应H⁺，而不是机械加水或CuSO₄。","labels":["实际放电","合并总反应","判断酸化","按损失复原"]},{"substance":"铁件镀铜与粗铜精炼对比","path":"两者阴极都可发生Cu²⁺+2e⁻=Cu；电镀的阴极是待镀铁件，精炼的阴极是纯铜薄片；阳极和电解质由目标决定。","labels":["先看目的","定阴极对象","定阳极材料","追踪Cu²⁺"]},{"substance":"钢铁在两类水膜中的腐蚀","path":"共同负极为Fe-2e⁻=Fe²⁺；酸性水膜阴极还原H⁺析H₂，近中性含氧水膜阴极还原O₂生成OH⁻。先判环境，再选阴极式。","labels":["共同氧化半反应","判酸碱与氧气","选择阴极路线","合并与防护"]}],"checkpoints":["我能先判断装置是原电池还是电解池。","我不会混淆正负极和阴阳极。","我能用电中性判断膜两侧离子迁移。","我能把电极反应与电子守恒计算连起来。","我能从两极实际放电粒子推出电解后溶液的pH、浓度和复原方法。","我能区分电镀、电解精炼和熔融电解冶金的电极角色。","我能依据水膜环境写出析氢腐蚀或吸氧腐蚀的阴极反应。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h2_electro$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H2_ELECTRO' and skill_id = 'H2_ELECTRO';

update public.chem_knowledge_cards
set structured_content = $card_h3_stoich${"skillId":"H3_STOICH","version":2,"intro":"高三计量综合仍然只有一个枢纽n。先把单位、对象和条件补回，再用质量、粒子数、气体体积、溶液浓度进入n，最后用方程式或守恒连接不同物质。","overview":["四条入口：n=m/M，n=N/Nₐ，气体n=V/Vₘ，溶液n=cV。","Nₐ判断先查对象、状态、反应、电离/水解、可逆性和化学式倍数。","反应计量只使用配平后的系数比；多反应物要先判断限制量。","复杂过程优先寻找质量、元素、电子、电荷或质子守恒，减少逐步追算。","高三溶液综合把c=1000ρw/M、稀释守恒和配制误差放进同一数量链，并用n实际/V实际追踪误差。"],"visualSummary":{"kind":"flow","title":"综合计量的最短路线","steps":[{"label":"识别已知量","caption":"01"},{"label":"全部换算为n","caption":"02"},{"label":"判断限制量","caption":"03"},{"label":"按系数比转移","caption":"04"},{"label":"优先找守恒","caption":"05"},{"label":"单位/数量级校验","caption":"06"}]},"sections":[{"title":"先补回五个量和四个公式","summary":"每个符号、单位和适用条件都要说完整。","items":[{"label":"n、N与Nₐ","rule":"物质的量n以mol计；微粒数N=nNₐ；对象必须明确到分子、原子、离子、电子或化学键。","examples":["【示范：两个样品贯通五个量】0.50 mol CO₂的质量为22 g、分子数为0.50Nₐ、标况体积为11.2 L；另将0.50 mol NaCl配成500 mL溶液，c(NaCl)=1.0 mol·L⁻¹。每次转换都先回到n，并核对物态和总体积。"],"visualSteps":["n、N与Nₐ","识别对象","用对应公式到n","按物态和条件转换","单位贯穿"]},{"label":"m与M","rule":"n=m/M；质量m常用g，摩尔质量M常用g·mol⁻¹。相对分子质量无单位。","examples":["【示范：两个样品贯通五个量】0.50 mol CO₂的质量为22 g、分子数为0.50Nₐ、标况体积为11.2 L；另将0.50 mol NaCl配成500 mL溶液，c(NaCl)=1.0 mol·L⁻¹。每次转换都先回到n，并核对物态和总体积。"],"visualSteps":["m与M","识别对象","用对应公式到n","按物态和条件转换","单位贯穿"]},{"label":"V与Vₘ","rule":"气体n=V/Vₘ；标准状况下Vₘ≈22.4 L·mol⁻¹，但必须先确认物态和状态条件。","examples":["【示范：两个样品贯通五个量】0.50 mol CO₂的质量为22 g、分子数为0.50Nₐ、标况体积为11.2 L；另将0.50 mol NaCl配成500 mL溶液，c(NaCl)=1.0 mol·L⁻¹。每次转换都先回到n，并核对物态和总体积。"],"visualSteps":["V与Vₘ","识别对象","用对应公式到n","按物态和条件转换","单位贯穿"]},{"label":"c与溶液体积","rule":"n=cV，V用L且指溶液总体积；稀释无反应时溶质n守恒。","examples":["【示范：两个样品贯通五个量】0.50 mol CO₂的质量为22 g、分子数为0.50Nₐ、标况体积为11.2 L；另将0.50 mol NaCl配成500 mL溶液，c(NaCl)=1.0 mol·L⁻¹。每次转换都先回到n，并核对物态和总体积。"],"visualSteps":["c与溶液体积","识别对象","用对应公式到n","按物态和条件转换","单位贯穿"]}]},{"title":"阿伏加德罗常数选择题的六关","summary":"每个选项都逐关检查，不凭熟悉感。","items":[{"label":"1. 对象关","rule":"粒子名称是否明确，化学式下标和离子电荷带来的倍数是否计入。","examples":["【示范：NA选择题六关扫描】判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。"],"visualSteps":["1. 对象关","对象","状态与溶液","反应","结构倍数与守恒"]},{"label":"2. 状态关","rule":"给体积时是否为气体、是否在标准状况；标准状况下H₂O、SO₃等常见物态要核对。","examples":["【示范：NA选择题六关扫描】判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。"],"visualSteps":["2. 状态关","对象","状态与溶液","反应","结构倍数与守恒"]},{"label":"3. 溶液关","rule":"给浓度却没给体积通常不能求总粒子数；弱电解质电离、盐水解使粒子种类更复杂。","examples":["【示范：NA选择题六关扫描】判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。"],"visualSteps":["3. 溶液关","对象","状态与溶液","反应","结构倍数与守恒"]},{"label":"4. 反应关","rule":"可逆反应不完全、过量与不足、歧化、聚合和混合后反应都会改变粒子数。","examples":["【示范：NA选择题六关扫描】判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。"],"visualSteps":["4. 反应关","对象","状态与溶液","反应","结构倍数与守恒"]},{"label":"5. 结构关","rule":"质子、中子、电子、价电子、化学键数需按一个粒子的结构逐一计数。","examples":["【示范：NA选择题六关扫描】判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。"],"visualSteps":["5. 结构关","对象","状态与溶液","反应","结构倍数与守恒"]},{"label":"6. 守恒关","rule":"必要时用原子、电子或电荷守恒检查，而非追逐所有中间物。","examples":["【示范：NA选择题六关扫描】判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。"],"visualSteps":["6. 守恒关","对象","状态与溶液","反应","结构倍数与守恒"]}]},{"title":"反应计量和限制量","summary":"所有已知量先变成mol，再按反应进度分配。","items":[{"label":"配平方程式","rule":"系数比就是物质的量比；未配平的式子不能用于定量。","examples":["【示范：Fe和Cl₂谁限制产物】先配2Fe+3Cl₂=2FeCl₃，分别算n(Fe)/2和n(Cl₂)/3，较小者为反应进度上限；由它求FeCl₃理论量，再与实际产量比较产率。"],"visualSteps":["配平方程式","配平方程式","全部换n","比较n/系数","理论量与产率"]},{"label":"限制量","rule":"分别计算每种反应物可支持的反应进度n/系数，最小者先耗尽。","examples":["【示范：Fe和Cl₂谁限制产物】先配2Fe+3Cl₂=2FeCl₃，分别算n(Fe)/2和n(Cl₂)/3，较小者为反应进度上限；由它求FeCl₃理论量，再与实际产量比较产率。"],"visualSteps":["限制量","配平方程式","全部换n","比较n/系数","理论量与产率"]},{"label":"过量与产率","rule":"理论产量由限制量决定；实际产率=实际产量/理论产量×100%。","examples":["【示范：Fe和Cl₂谁限制产物】先配2Fe+3Cl₂=2FeCl₃，分别算n(Fe)/2和n(Cl₂)/3，较小者为反应进度上限；由它求FeCl₃理论量，再与实际产量比较产率。"],"visualSteps":["过量与产率","配平方程式","全部换n","比较n/系数","理论量与产率"]},{"label":"连续与并行反应","rule":"连续反应可建立总关系式；并行反应通常配合元素守恒、电子守恒或总量关系求解。","examples":["【示范：Fe和Cl₂谁限制产物】先配2Fe+3Cl₂=2FeCl₃，分别算n(Fe)/2和n(Cl₂)/3，较小者为反应进度上限；由它求FeCl₃理论量，再与实际产量比较产率。"],"visualSteps":["连续与并行反应","配平方程式","全部换n","比较n/系数","理论量与产率"]}]},{"title":"四类守恒怎样选","summary":"守恒量要对应过程始终不变的对象。","items":[{"label":"质量守恒","rule":"封闭体系中反应前后总质量相等；有气体逸出或外界物质进入时要明确系统边界。","examples":["【示范：多步炼铁选哪种守恒】从Fe₂O₃经中间氧化物到Fe，若只求最终Fe可直接用Fe元素守恒；若同时涉及CO/CO₂可用C或O守恒；涉及变价氧化剂还可用电子守恒；溶液离子关系用电荷守恒。"],"visualSteps":["质量守恒","圈不变对象","选最短守恒","列等量关系","用另一守恒验算"]},{"label":"元素守恒","rule":"某元素的原子总数在化学变化中守恒，适合多步转化、混合物组成和工艺流程。","examples":["【示范：多步炼铁选哪种守恒】从Fe₂O₃经中间氧化物到Fe，若只求最终Fe可直接用Fe元素守恒；若同时涉及CO/CO₂可用C或O守恒；涉及变价氧化剂还可用电子守恒；溶液离子关系用电荷守恒。"],"visualSteps":["元素守恒","圈不变对象","选最短守恒","列等量关系","用另一守恒验算"]},{"label":"电子守恒","rule":"氧化还原中总失电子=总得电子，适合滴定、电化学和多步变价。","examples":["【示范：多步炼铁选哪种守恒】从Fe₂O₃经中间氧化物到Fe，若只求最终Fe可直接用Fe元素守恒；若同时涉及CO/CO₂可用C或O守恒；涉及变价氧化剂还可用电子守恒；溶液离子关系用电荷守恒。"],"visualSteps":["电子守恒","圈不变对象","选最短守恒","列等量关系","用另一守恒验算"]},{"label":"电荷/质子守恒","rule":"溶液总体电中性；酸碱与水解体系可用质子得失关系。","examples":["【示范：多步炼铁选哪种守恒】从Fe₂O₃经中间氧化物到Fe，若只求最终Fe可直接用Fe元素守恒；若同时涉及CO/CO₂可用C或O守恒；涉及变价氧化剂还可用电子守恒；溶液离子关系用电荷守恒。"],"visualSteps":["电荷/质子守恒","圈不变对象","选最短守恒","列等量关系","用另一守恒验算"]}]},{"title":"数据、图像与计算表达","summary":"计算题既要结果，也要可检查的过程。","items":[{"label":"单位贯穿","rule":"公式代入前统一L、mL、g、kg等单位，最终结果带单位和合理有效数字。","examples":["【示范：从图表读数到规范结果】先读清横纵轴、单位和刻度，从曲线取有效数字；把图中体积mL换成L后代式，分步写公式—代数—结果，并用数量级、极限情况和守恒检查。"],"visualSteps":["单位贯穿","读轴与单位","提取数据","分步计算","数量级复核"]},{"label":"图像先读轴","rule":"热重、滴定或反应进程图先看横轴条件、纵轴物理量和平台/拐点，再把变化量换算为n。","examples":["【示范：从图表读数到规范结果】先读清横纵轴、单位和刻度，从曲线取有效数字；把图中体积mL换成L后代式，分步写公式—代数—结果，并用数量级、极限情况和守恒检查。"],"visualSteps":["图像先读轴","读轴与单位","提取数据","分步计算","数量级复核"]},{"label":"数量级检查","rule":"微粒数通常为10²³量级；浓度、转化率、质量分数必须落在物理合理范围。","examples":["【示范：从图表读数到规范结果】先读清横纵轴、单位和刻度，从曲线取有效数字；把图中体积mL换成L后代式，分步写公式—代数—结果，并用数量级、极限情况和守恒检查。"],"visualSteps":["数量级检查","读轴与单位","提取数据","分步计算","数量级复核"]}]},{"title":"溶液组成换算与容量操作误差","summary":"复杂题先选一份有确定体积的溶液作为基准，再沿质量—溶质质量—物质的量—浓度转换。","items":[{"label":"质量分数、密度和c的双向桥","rule":"当ρ用g·cm⁻³、w用小数、M用g·mol⁻¹时，c=1000ρw/M；反求质量分数得w=cM/(1000ρ)。公式来自同一份1 L溶液，不能把溶液质量和溶剂质量混用。","examples":["【示范：由浓度反求质量分数】某NaOH溶液c=2.00 mol·L⁻¹、ρ=1.08 g·cm⁻³，M=40.0 g·mol⁻¹，则w=2.00×40.0÷(1000×1.08)=0.0741，约为7.41%。"],"visualSteps":["1 L溶液质量=1000ρ","溶质质量=cM","w=cM/(1000ρ)"],"caution":"适用于题给均匀溶液的宏观换算；多溶质体系要明确w和c分别属于哪一种溶质。"},{"label":"配制步骤是一条防损失链","rule":"固体配液依次称量、溶解、冷却、转移、洗涤并合并、定容、摇匀、装瓶贴签；浓溶液稀释则先计算、量取，再稀释、冷却后转移定容。每一步都在保护n准确或V准确。","examples":["【示范：用NaCl固体配制标准溶液】称取计算质量，在烧杯中用适量水溶解；沿玻璃棒转移入容量瓶，用蒸馏水洗涤烧杯和玻璃棒2～3次并合并；加水至距刻度1～2 cm改用胶头滴管，凹液面最低点与刻度相切，塞紧摇匀。"],"visualSteps":["称量/溶解保护n","洗涤转移保护n","定容/摇匀锁定V"],"caution":"放热溶解或浓酸稀释放热后必须冷却到容量瓶规定温度附近再定容；不在容量瓶内直接稀释放热液体。"},{"label":"配液误差用n实际/V实际传播","rule":"称量、转移、洗涤主要影响n实际；冷却、定容和读液面主要影响V实际。俯视定容时视线在刻度线上方，为让视觉中的液面最低点与刻度相切，真实液面会低于刻度，V实际偏小，浓度偏高；仰视相反。","examples":["【示范：定容俯视】溶质n实际未变；真实凹液面低于刻度，V实际小于标称体积，所以c实际=n实际/V实际偏高。画“眼睛—刻度—凹液面”三条水平关系比背结论可靠。"],"visualSteps":["俯视→真实液面低","V实际↓、n不变","c实际↑"],"caution":"读数方向只适用于容量瓶定容情境；滴定管刻度方向相反，必须重新看仪器刻度和直接读数。"},{"label":"移液稀释的误差分成取样端和定容端","rule":"移液管未用待取液润洗，管内水会稀释所取储备液，使移入的溶质n偏小；容量瓶有蒸馏水不影响；定容过线使V偏大。先分别判断，再组合，不把“器皿湿润”一律判错。","examples":["【示范：移液管未润洗后又定容过线】未润洗使移取的n偏小；定容过线使V偏大，两种错误都使最终c=n/V偏低，因此方向能够叠加确定。"],"visualSteps":["取样端：n↓","定容端：V↑","两条路径都指向c↓"],"caution":"若两个错误方向相反，只能说存在竞争，不能在没有定量信息时武断判断总误差。"}]}],"workedExamples":[{"substance":"两个样品贯通五个量","path":"0.50 mol CO₂的质量为22 g、分子数为0.50Nₐ、标况体积为11.2 L；另将0.50 mol NaCl配成500 mL溶液，c(NaCl)=1.0 mol·L⁻¹。每次转换都先回到n，并核对物态和总体积。","labels":["识别对象","用对应公式到n","按物态和条件转换","单位贯穿"]},{"substance":"NA选择题六关扫描","path":"判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。","labels":["对象","状态与溶液","反应","结构倍数与守恒"]},{"substance":"Fe和Cl₂谁限制产物","path":"先配2Fe+3Cl₂=2FeCl₃，分别算n(Fe)/2和n(Cl₂)/3，较小者为反应进度上限；由它求FeCl₃理论量，再与实际产量比较产率。","labels":["配平方程式","全部换n","比较n/系数","理论量与产率"]},{"substance":"多步炼铁选哪种守恒","path":"从Fe₂O₃经中间氧化物到Fe，若只求最终Fe可直接用Fe元素守恒；若同时涉及CO/CO₂可用C或O守恒；涉及变价氧化剂还可用电子守恒；溶液离子关系用电荷守恒。","labels":["圈不变对象","选最短守恒","列等量关系","用另一守恒验算"]},{"substance":"从图表读数到规范结果","path":"先读清横纵轴、单位和刻度，从曲线取有效数字；把图中体积mL换成L后代式，分步写公式—代数—结果，并用数量级、极限情况和守恒检查。","labels":["读轴与单位","提取数据","分步计算","数量级复核"]},{"substance":"标况气体与粒子数","path":"标况11.2 L CO₂为0.5 mol CO₂，含0.5Nₐ个CO₂分子、0.5Nₐ个C原子、1.0Nₐ个O原子，总原子数1.5Nₐ。","labels":["状态关","对象关","化学式倍数"]},{"substance":"Fe与盐酸的限制量","path":"先求n(Fe)和n(HCl)，按Fe+2HCl=FeCl₂+H₂比较n(Fe)/1与n(HCl)/2，较小者决定H₂理论物质的量；再换成体积或质量。","labels":["都先换n","除以系数","最小值决定产量"]},{"substance":"溶液综合四格图","path":"左上写给定溶液体积，向右乘密度得溶液质量，向下乘质量分数得溶质质量，再除摩尔质量得n；最后除总体积得到c。","labels":["体积","溶液质量","溶质质量","n与c"]}],"checkpoints":["我能画出以n为中心的完整换算网络。","我做Nₐ题会逐项过六关。","我会用n/系数判断限制量。","我能为复杂过程选择合适的守恒。","我能在质量分数、密度与物质的量浓度之间双向换算。","我会把配制错误分别放到n和V两条分支。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h3_stoich$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_STOICH' and skill_id = 'H3_STOICH';

update public.chem_knowledge_cards
set structured_content = $card_h3_inorganic${"skillId":"H3_INORGANIC","version":2,"intro":"元素化合物知识量大，但组织方式很少：先画元素价态阶梯，再给每一种物质贴上类别标签，最后用反应条件连接转化。这样遇到陌生物质也能推，而不是背孤立方程式。","overview":["三条主轴：元素价态决定氧化还原方向，物质类别决定酸碱/离子反应，条件决定具体产物。","金属主线常见Na、Mg、Al、Fe、Cu；非金属主线常见Cl、S、N、C、Si及其化合物。","制备、检验、除杂必须形成“试剂—操作—现象—结论”闭环，并排除干扰。","陌生转化先守恒中心元素，再用题给性质、价态和条件预测。"],"visualSummary":{"kind":"network","title":"常见元素价态—类别网络","center":"条件决定产物","groups":[{"label":"Al","items":["Al³⁺","Al(OH)₃","含铝酸根"]},{"label":"Fe","items":["Fe⁰/Fe²⁺/Fe³⁺","沉淀颜色","KSCN检验"]},{"label":"S","items":["SO₂多重性质","浓H₂SO₄","SO₄²⁻检验"]},{"label":"N","items":["NH₃/NH₄⁺","NO/NO₂","HNO₃"]},{"label":"C/Si","items":["CO₂阶段反应","SiO₂边界","资源冶炼"]}]},"sections":[{"title":"价态—类别—条件三维框架","summary":"每个反应都能在三条轴上定位。","items":[{"label":"价态轴","rule":"低价态常有还原性，高价态常有氧化性，中间价态可能兼有；具体强弱由物质和介质决定。","examples":["【示范：Fe的三条坐标轴】先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。"],"visualSteps":["价态轴","标价态","判物质类别","读反应条件","连接网络"]},{"label":"类别轴","rule":"氧化物、酸、碱、盐、单质各有通性；两性物质能在合适条件下与强酸和强碱反应。","examples":["【示范：Fe的三条坐标轴】先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。"],"visualSteps":["类别轴","标价态","判物质类别","读反应条件","连接网络"]},{"label":"条件轴","rule":"浓度、温度、酸碱介质、试剂用量、空气/光照可改变产物或反应程度。","examples":["【示范：Fe的三条坐标轴】先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。"],"visualSteps":["条件轴","标价态","判物质类别","读反应条件","连接网络"]},{"label":"网络轴","rule":"先守住中心元素，再看它从哪种价态和类别转到哪一种，方程式自然成为网络的连线。","examples":["【示范：Fe的三条坐标轴】先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。"],"visualSteps":["网络轴","标价态","判物质类别","读反应条件","连接网络"]}]},{"title":"常见金属主线","summary":"抓特征反应和价态转化，不背百科。","items":[{"label":"Na及其化合物","rule":"Na强还原性；Na₂O₂中O为-1；Na₂CO₃/NaHCO₃关注水解、热稳定性和转化。","examples":["【示范：Na、Al、Fe各抓一条主线】Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。"],"visualSteps":["Na及其化合物","结构性质","典型化合物","价态/两性转化","实验现象"]},{"label":"Al及其化合物","rule":"Al、Al₂O₃、Al(OH)₃具有典型两性；Al³⁺与OH⁻的少量/过量会出现沉淀生成与溶解。","examples":["【示范：Na、Al、Fe各抓一条主线】Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。"],"visualSteps":["Al及其化合物","结构性质","典型化合物","价态/两性转化","实验现象"]},{"label":"Fe及其化合物","rule":"Fe常见0、+2、+3价；Fe²⁺有还原性，Fe³⁺有氧化性，利用颜色、沉淀和KSCN等建立检验与转化。","examples":["【示范：Na、Al、Fe各抓一条主线】Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。"],"visualSteps":["Fe及其化合物","结构性质","典型化合物","价态/两性转化","实验现象"]},{"label":"金属制备与防护","rule":"活泼性决定冶炼方法的大方向；腐蚀防护从原电池电极反应解释。","examples":["【示范：Na、Al、Fe各抓一条主线】Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。"],"visualSteps":["金属制备与防护","结构性质","典型化合物","价态/两性转化","实验现象"]}]},{"title":"常见非金属主线","summary":"用氧化还原和酸碱性把族内物质连接起来。","items":[{"label":"Cl","rule":"Cl₂强氧化性，氯水多粒子共存，HClO负责氧化漂白和消毒；Cl⁻用酸化AgNO₃检验。","examples":["【示范：C、Si、N、S、Cl网络定位】C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。"],"visualSteps":["Cl","中心元素","常见价态","物质类别","条件与环境"]},{"label":"S","rule":"H₂S中S为-2、SO₂中+4、H₂SO₄中+6；SO₂兼有还原性、氧化性并具有特定漂白现象。","examples":["【示范：C、Si、N、S、Cl网络定位】C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。"],"visualSteps":["S","中心元素","常见价态","物质类别","条件与环境"]},{"label":"N","rule":"NH₃/NH₄⁺、N₂、NO/NO₂、HNO₃构成价态网络；NH₃制备检验、硝酸氧化性和氮氧化物转化常考。","examples":["【示范：C、Si、N、S、Cl网络定位】C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。"],"visualSteps":["N","中心元素","常见价态","物质类别","条件与环境"]},{"label":"C与Si","rule":"CO₂/碳酸盐平衡、CO还原性；SiO₂网络结构及无机非金属材料联系性质与用途。","examples":["【示范：C、Si、N、S、Cl网络定位】C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。"],"visualSteps":["C与Si","中心元素","常见价态","物质类别","条件与环境"]}]},{"title":"制备、检验和除杂","summary":"答案不能只写试剂名。","items":[{"label":"制备","rule":"选择原料和反应，控制条件，设计发生—净化—收集—尾气处理，兼顾安全和纯度。","examples":["【示范：Fe²⁺、Fe³⁺的检验和除杂】检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。"],"visualSteps":["制备","制备要防副反应","取样检验","先排干扰","选择性除杂"]},{"label":"检验","rule":"加入特异试剂，写操作和明显现象，再给不超出证据的结论。","examples":["【示范：Fe²⁺、Fe³⁺的检验和除杂】检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。"],"visualSteps":["检验","制备要防副反应","取样检验","先排干扰","选择性除杂"]},{"label":"除杂","rule":"除去杂质但不引入新杂质、不损失主体，试剂适量或过量后的处理要交代。","examples":["【示范：Fe²⁺、Fe³⁺的检验和除杂】检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。"],"visualSteps":["除杂","制备要防副反应","取样检验","先排干扰","选择性除杂"]},{"label":"鉴别","rule":"同一操作下产生不同现象，或设计最少步骤的顺序实验；先排除干扰。","examples":["【示范：Fe²⁺、Fe³⁺的检验和除杂】检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。"],"visualSteps":["鉴别","制备要防副反应","取样检验","先排干扰","选择性除杂"]}]},{"title":"陌生信息题的迁移","summary":"陌生名称不等于陌生规律。","items":[{"label":"读信息","rule":"把氧化性、溶解性、颜色、热稳定性或给定方程式标到物质节点上。","examples":["【示范：陌生钴化合物信息题】题给Co²⁺/Co³⁺颜色、电势或反应条件时，先抄出中心元素价态和物质类别；再判断氧化/还原、酸碱或配位变化，写方程式并用原子、电荷、电子守恒核验。"],"visualSteps":["读信息","读题给信息","映射熟悉模型","写反应","守恒校验"]},{"label":"守中心元素","rule":"跟踪目标元素在每一步的价态和去向，先判断反应类型。","examples":["【示范：陌生钴化合物信息题】题给Co²⁺/Co³⁺颜色、电势或反应条件时，先抄出中心元素价态和物质类别；再判断氧化/还原、酸碱或配位变化，写方程式并用原子、电荷、电子守恒核验。"],"visualSteps":["守中心元素","读题给信息","映射熟悉模型","写反应","守恒校验"]},{"label":"写并校验","rule":"根据介质和条件写方程式，再用电子、原子、电荷守恒核验。","examples":["【示范：陌生钴化合物信息题】题给Co²⁺/Co³⁺颜色、电势或反应条件时，先抄出中心元素价态和物质类别；再判断氧化/还原、酸碱或配位变化，写方程式并用原子、电荷、电子守恒核验。"],"visualSteps":["写并校验","读题给信息","映射熟悉模型","写反应","守恒校验"]}]},{"title":"铝：两性和少量—过量反应网络","summary":"把Al、Al³⁺、Al(OH)₃和含铝酸根放在同一张条件网络中。","items":[{"label":"铝单质的条件边界","rule":"Al易失电子但常温下表面有致密氧化膜；它能与合适的酸或强碱反应放出H₂，遇冷的浓硫酸、浓硝酸可发生钝化。","examples":["【示范：铝片先打磨再反应】未打磨铝片反应可能先出现诱导阶段，因为要先破坏氧化膜；与NaOH溶液反应时Al最终进入含铝酸根，H来自水，需用电子守恒配平。"],"visualSteps":["识别氧化膜","看酸碱与浓度","判断Al失电子","按条件写产物"]},{"label":"Al₂O₃与Al(OH)₃的两性","rule":"两性指在合适条件下既能与强酸反应，也能与强碱反应；不是与任意酸、任意碱都同样迅速反应。","examples":["【示范：Al(OH)₃的两条路】与酸：Al(OH)₃+3H⁺=Al³⁺+3H₂O；与强碱可写Al(OH)₃+OH⁻=[Al(OH)₄]⁻。"],"visualSteps":["先认两性物质","遇酸生成Al³⁺","遇强碱生成含铝酸根","检查介质"],"caution":"含铝酸根的具体表示按苏教版教材或题目给定形式书写。"},{"label":"Al³⁺与OH⁻的阶段反应","rule":"向Al³⁺溶液逐滴加OH⁻，先生成Al(OH)₃沉淀；OH⁻继续过量，沉淀溶解生成含铝酸根。反向滴加时局部过量会改变现象和阶段。","examples":["【示范：AlCl₃中滴NaOH至过量】先Al³⁺+3OH⁻=Al(OH)₃↓，再Al(OH)₃+OH⁻=[Al(OH)₄]⁻；沉淀量经历0→增多→最多→减少至0。"],"visualSteps":["少量OH⁻成沉淀","达到最大沉淀","过量OH⁻溶解","对应沉淀曲线"]}]},{"title":"铁：0、+2、+3价与检验闭环","summary":"每次反应同时追踪价态、颜色、沉淀和检验干扰。","items":[{"label":"Fe单质的价态由氧化剂决定","rule":"Fe与非氧化性酸通常生成Fe²⁺和H₂；与Cl₂等较强氧化剂反应常生成Fe³⁺；与盐溶液反应还要看氧化性和用量。","examples":["【示范：Fe分别与HCl和Cl₂反应】Fe+2H⁺=Fe²⁺+H₂↑；2Fe+3Cl₂点燃生成2FeCl₃。不能把“铁通常+2价”机械套到强氧化剂条件。"],"visualSteps":["辨认氧化剂强弱","确定Fe终价态","写电子转移","核对条件"]},{"label":"Fe²⁺与Fe³⁺相互转化","rule":"Fe²⁺遇合适氧化剂失电子生成Fe³⁺；Fe³⁺遇Fe、Cu、I⁻等还原剂时可得电子生成Fe²⁺，具体能否反应以已知强弱和题给事实为准。","examples":["【示范：Fe³⁺与Fe反应】2Fe³⁺+Fe=3Fe²⁺；同一元素同时出现0、+3价并归中到+2价，用电子守恒可快速确定1∶2。"],"visualSteps":["标0与+3价","判断归中方向","电子守恒定比例","得到Fe²⁺"]},{"label":"Fe(OH)₂制备、氧化和离子检验","rule":"制Fe(OH)₂要减少溶液和装置中的O₂；生成的浅色沉淀会迅速变灰绿并最终转为红褐色Fe(OH)₃。Fe³⁺可用SCN⁻显色检验，但要排除本底颜色和能改变价态的试剂。","examples":["【示范：观察Fe(OH)₂氧化】Fe²⁺+2OH⁻=Fe(OH)₂↓；4Fe(OH)₂+O₂+2H₂O=4Fe(OH)₃。用煮沸冷却的水、液封或导管伸入液面下可减小O₂干扰。"],"visualSteps":["隔绝O₂制备","生成Fe(OH)₂","记录颜色时间链","再用检验闭环"],"caution":"仅凭溶液颜色不能唯一认定Fe²⁺或Fe³⁺，检验必须有特征反应并考虑干扰。"}]},{"title":"硫：多价态、漂白和硫酸性质","summary":"把-2、0、+4、+6价沿电子转移连接，并把SO₂漂白与氧化漂白分开。","items":[{"label":"SO₂的酸性、还原性和氧化性","rule":"SO₂是酸性氧化物；S为+4中间价，既可被氧化到+6，又可被还原到0或-2。某个具体反应体现哪种性质，要看S的价态是否变化。","examples":["【示范：SO₂通入酸性KMnO₄】SO₂中S由+4升到+6，体现还原性；而SO₂+2H₂S=3S↓+2H₂O中，SO₂的S由+4降到0，体现氧化性。"],"visualSteps":["先认酸性氧化物","标S为+4","看升价或降价","判断还原性或氧化性"]},{"label":"SO₂漂白的边界","rule":"SO₂可与某些有色物质形成不稳定的无色物，漂白常可逆且有选择性；HClO、O₃、H₂O₂等主要靠氧化破坏发色结构，通常不可逆。","examples":["【示范：品红和石蕊的现象分工】SO₂使品红褪色可体现漂白性；使紫色石蕊变红首先体现酸性，不能把所有颜色变化都归为漂白。加热后颜色恢复可支持SO₂漂白的可逆性。"],"visualSteps":["先识别有色物","判断酸碱变色","再判断漂白","用恢复性区分机理"]},{"label":"浓硫酸与SO₄²⁻检验","rule":"浓硫酸具有吸水性、脱水性和强氧化性，三者要按物质变化区分；检验SO₄²⁻通常先加稀盐酸排除CO₃²⁻、SO₃²⁻等，再加BaCl₂观察白色沉淀。","examples":["【示范：铜与浓硫酸】Cu+2H₂SO₄(浓)加热生成CuSO₄、SO₂和H₂O，S由+6降到+4体现强氧化性；这不能推广到稀硫酸。"],"visualSteps":["判断浓稀条件","区分三种性质","检验先排干扰","现象支持有限结论"],"caution":"用Ba(NO₃)₂并先加硝酸时，酸性NO₃⁻可能氧化SO₃²⁻制造SO₄²⁻证据，需警惕试剂引入干扰。"}]},{"title":"氮：氨—铵盐—氮氧化物—硝酸","summary":"按-3、0、+2、+4、+5价连接氮元素主线，同时保留实验条件和安全。","items":[{"label":"NH₃的溶解、碱性与喷泉","rule":"NH₃极易溶于水，且与水建立平衡生成NH₄⁺和OH⁻。喷泉形成首先来自气体快速溶解造成压强差，酸碱反应可进一步促进吸收。","examples":["【示范：氨喷泉实验】烧瓶充满干燥NH₃，少量水进入后NH₃迅速溶解，瓶内压强降低，外界大气压把滴有指示剂的水压入形成喷泉；溶液显碱性使指示剂变色。"],"visualSteps":["NH₃快速溶解","瓶内压强下降","大气压推液体进入","碱性使指示剂变色"]},{"label":"NH₄⁺检验与NH₃制备","rule":"检验NH₄⁺要取样、加浓碱并加热，使其转化为NH₃，再用湿润红色石蕊试纸等确认；实验室可由铵盐与碱加热制氨，并选择合适干燥、收集和尾气处理。","examples":["【示范：检验NH₄Cl】NH₄⁺+OH⁻加热生成NH₃↑+H₂O；逸出气体使湿润红色石蕊试纸变蓝。不能只凭“闻到气味”下结论。"],"visualSteps":["取少量样品","加碱并加热","检验NH₃","写出检出结论"],"caution":"禁止把鼻孔凑近容器直接闻气味；若需辨气味，应使用规范扇闻并以特征试纸作主要证据。"},{"label":"NO、NO₂与硝酸","rule":"NO通常无色，遇O₂迅速生成红棕色NO₂；NO₂与水反应可生成HNO₃和NO。硝酸既显酸性又有强氧化性，与金属反应通常不放H₂，产物受浓度和条件影响。","examples":["【示范：NO遇空气】2NO+O₂=2NO₂；3NO₂+H₂O=2HNO₃+NO。观察到无色气体接触空气变红棕，可作为NO被氧化的证据链。"],"visualSteps":["先识别NO无色","遇O₂变NO₂","NO₂与水反应","连接到HNO₃"],"caution":"浓、稀硝酸与金属的产物不能脱离题设绝对化，陌生条件以题给信息为准。"}]},{"title":"碳、硅与金属资源：性质要落到流程","summary":"把阶段反应、结构性质和冶炼方法用于真实分离与资源利用。","items":[{"label":"CO₂与碳酸盐的阶段反应","rule":"CO₂与碱的产物由物质的量比决定：OH⁻足量时主要生成CO₃²⁻，CO₂继续过量可转为HCO₃⁻；碳酸盐与酸也常分阶段。","examples":["【示范：CO₂通入NaOH】先CO₂+2OH⁻=CO₃²⁻+H₂O；继续通入CO₂，CO₃²⁻+CO₂+H₂O=2HCO₃⁻。先定少量物质再确定终点。"],"visualSteps":["读少量过量","先生成CO₃²⁻","继续生成HCO₃⁻","按终点合并方程"]},{"label":"Si、SiO₂和硅酸盐","rule":"SiO₂由原子构成共价网络，不存在独立SiO₂分子；它是酸性氧化物但不与水直接生成硅酸，能与强碱反应，也能与HF发生特殊反应。","examples":["【示范：SiO₂与NaOH】SiO₂+2OH⁻=SiO₃²⁻+H₂O，体现酸性氧化物与碱反应；“酸性氧化物都与水反应”在SiO₂处不成立。"],"visualSteps":["先认共价网络","判断酸性氧化物","写与强碱反应","检查通性例外"],"caution":"HF与玻璃反应属于教材特殊事实，不能由一般酸性氧化物通性推出。"},{"label":"冶炼方法与资源流程","rule":"很活泼金属常用熔融电解，中等活泼金属常用还原法，较不活泼金属可用热分解等方法；具体流程还要看矿物形态、能耗、纯度和安全。","examples":["【示范：海水提镁】海水中的Mg²⁺先转为Mg(OH)₂沉淀，再与酸转为无水MgCl₂，最后电解熔融MgCl₂制Mg；水溶液电解不能直接得到Mg。"],"visualSteps":["富集目标离子","沉淀分离","转为无水熔盐","熔融电解制金属"]}]}],"workedExamples":[{"substance":"Fe的三条坐标轴","path":"先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。","labels":["标价态","判物质类别","读反应条件","连接网络"]},{"substance":"Na、Al、Fe各抓一条主线","path":"Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。","labels":["结构性质","典型化合物","价态/两性转化","实验现象"]},{"substance":"C、Si、N、S、Cl网络定位","path":"C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。","labels":["中心元素","常见价态","物质类别","条件与环境"]},{"substance":"Fe²⁺、Fe³⁺的检验和除杂","path":"检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。","labels":["制备要防副反应","取样检验","先排干扰","选择性除杂"]},{"substance":"陌生钴化合物信息题","path":"题给Co²⁺/Co³⁺颜色、电势或反应条件时，先抄出中心元素价态和物质类别；再判断氧化/还原、酸碱或配位变化，写方程式并用原子、电荷、电子守恒核验。","labels":["读题给信息","映射熟悉模型","写反应","守恒校验"]},{"substance":"Fe²⁺和Fe³⁺相互转化","path":"Fe²⁺失e⁻可变Fe³⁺，需氧化剂；Fe³⁺得e⁻可变Fe²⁺，需还原剂。检验Fe³⁺可用KSCN出现血红色，但该现象只能证明检出Fe³⁺。","labels":["价态轴","选氧化剂/还原剂","证据边界"]},{"substance":"Al³⁺中滴加NaOH至过量","path":"先Al³⁺+3OH⁻=Al(OH)₃↓；继续加OH⁻，两性氢氧化物溶解生成含铝酸根的溶液粒子。要根据苏教版题设采用相应表示式。","labels":["先沉淀","后溶解","少量过量"]},{"substance":"AlCl₃中滴加NaOH至过量","path":"先生成Al(OH)₃沉淀，达到最大后在过量OH⁻中转化为含铝酸根。用两段离子方程式和沉淀量曲线共同表示。","labels":["少量成沉淀","最大值","过量溶解","图式对应"]},{"substance":"隔绝空气制Fe(OH)₂","path":"先除去水和装置中的O₂，再让Fe²⁺与OH⁻接触；记录浅色—灰绿—红褐的时间变化，并用4Fe(OH)₂+O₂+2H₂O=4Fe(OH)₃解释。","labels":["排O₂","生成沉淀","时间序列","氧化方程"]},{"substance":"S、N两条价态网络","path":"S抓-2、0、+4、+6和SO₂双重氧化还原性；N抓-3、0、+2、+4、+5和NH₃、NO、NO₂、HNO₃。每条连线都标氧化剂/还原剂和条件。","labels":["标价态节点","连接代表物质","注明反应条件","用电子守恒"]},{"substance":"海水提镁的四步主线","path":"由Mg²⁺沉淀为Mg(OH)₂，酸化成MgCl₂，脱水得到无水熔盐，再熔融电解。每步写清目标元素在哪一相和为何不能跳步。","labels":["沉淀富集","转化氯化物","无水化","熔融电解"]}],"checkpoints":["我能为一种元素画出价态阶梯。","我能从类别通性预测反应而不是只背方程式。","我会把检验答案写成操作、现象、结论。","我能用题给信息解决陌生物质转化。","我能画出Al³⁺—Al(OH)₃—含铝酸根的少量过量网络。","我能用价态、沉淀和检验现象连接Fe、S、N的核心反应。","我能区分SO₂漂白、酸碱变色和氧化还原褪色。","我能把C、Si和金属冶炼知识放进阶段反应或资源流程中。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h3_inorganic$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_INORGANIC' and skill_id = 'H3_INORGANIC';

update public.chem_knowledge_cards
set structured_content = $card_h3_thermo_rate${"skillId":"H3_THERMO_RATE","version":2,"intro":"能量问题看始态和终态，速率问题看反应途径和有效碰撞。二者常出现在同一图或同一工业背景中，但ΔH、活化能、反应速率和平衡限度必须分开。","overview":["ΔH=生成物焓−反应物焓，只由始终态决定；反应式变形时ΔH同步变形。","活化能控制反应路径难易；催化剂降低能垒，不改变ΔH和K。","平均速率由浓度变化表示，不同物质速率按计量数换算。","工业条件同时考虑速率、平衡、能耗、成本与安全，不要求背精确参数。"],"visualSummary":{"kind":"network","title":"方向、速率与工业条件","center":"多目标权衡","groups":[{"label":"反应方向｜定性","items":["焓变因素","熵变因素","温度改变倾向"]},{"label":"动力学","items":["Ea与速率","自发≠快速"]},{"label":"平衡","items":["Q/K与组成","催化剂不改K"]},{"label":"工程","items":["能耗/成本","安全/产率"]}]},"sections":[{"title":"热化学基础补回","summary":"先判正负，再谈数值。","items":[{"label":"吸放热与ΔH","rule":"放热ΔH<0，吸热ΔH>0；反应式逆写ΔH变号，系数乘k则ΔH乘k。","examples":["【示范：燃烧反应的ΔH三种算法】由能量图可读生成物减反应物；由键能用断键总能−成键总能；由多步反应用盖斯定律相加。无论哪种方法，都先核对物态、系数和正负号。"],"visualSteps":["吸放热与ΔH","判吸放热","物态系数","选择能量/键能/盖斯","核对ΔH"]},{"label":"盖斯定律","rule":"反应热只与始终态有关，可把已知反应式线性组合得到目标反应。","examples":["【示范：燃烧反应的ΔH三种算法】由能量图可读生成物减反应物；由键能用断键总能−成键总能；由多步反应用盖斯定律相加。无论哪种方法，都先核对物态、系数和正负号。"],"visualSteps":["盖斯定律","判吸放热","物态系数","选择能量/键能/盖斯","核对ΔH"]},{"label":"键能法","rule":"ΔH≈断裂反应物化学键吸能总和−形成生成物化学键放能总和。","examples":["【示范：燃烧反应的ΔH三种算法】由能量图可读生成物减反应物；由键能用断键总能−成键总能；由多步反应用盖斯定律相加。无论哪种方法，都先核对物态、系数和正负号。"],"visualSteps":["键能法","判吸放热","物态系数","选择能量/键能/盖斯","核对ΔH"]}]},{"title":"反应历程图","summary":"横轴是历程，不是时间；纵轴通常是能量。","items":[{"label":"峰与谷","rule":"从反应物能级到峰顶的差是正反应活化能；中间谷可能对应中间体。","examples":["【示范：催化剂反应历程图】无催化路径峰高，加入催化剂出现另一条低峰路径；正逆活化能都降低，而始态、终态和ΔH不变。若图中有多个峰，峰谷间可对应中间体和分步反应。"],"visualSteps":["峰与谷","读始终态","看峰谷","比较活化能","区分路径与ΔH"]},{"label":"正逆活化能","rule":"正、逆活化能之差与ΔH相关；始终态能量差不因催化剂改变。","examples":["【示范：催化剂反应历程图】无催化路径峰高，加入催化剂出现另一条低峰路径；正逆活化能都降低，而始态、终态和ΔH不变。若图中有多个峰，峰谷间可对应中间体和分步反应。"],"visualSteps":["正逆活化能","读始终态","看峰谷","比较活化能","区分路径与ΔH"]},{"label":"催化路径","rule":"催化剂提供新的低能垒路径，可能增加步骤，但最高能垒降低。","examples":["【示范：催化剂反应历程图】无催化路径峰高，加入催化剂出现另一条低峰路径；正逆活化能都降低，而始态、终态和ΔH不变。若图中有多个峰，峰谷间可对应中间体和分步反应。"],"visualSteps":["催化路径","读始终态","看峰谷","比较活化能","区分路径与ΔH"]}]},{"title":"速率表示和影响因素","summary":"统一表示后再比较。","items":[{"label":"平均速率","rule":"v=|Δc|/Δt；不同物质表示的速率比等于系数比。","examples":["【示范：N₂+3H₂合成NH₃的速率因素】用Δc/Δt表示平均速率并按1:3:2换算；升温、增反应气分压、加催化剂通常提速。对题给基元步骤只据其信息判断，不自行套更高层次数学模型。"],"visualSteps":["平均速率","算平均速率","按系数换算","解释因素","题给机理优先"]},{"label":"浓度与压强","rule":"提高有效反应粒子的浓度或分压通常增加碰撞频率；恒容加惰性气体不改变反应组分浓度。","examples":["【示范：N₂+3H₂合成NH₃的速率因素】用Δc/Δt表示平均速率并按1:3:2换算；升温、增反应气分压、加催化剂通常提速。对题给基元步骤只据其信息判断，不自行套更高层次数学模型。"],"visualSteps":["浓度与压强","算平均速率","按系数换算","解释因素","题给机理优先"]},{"label":"温度","rule":"升温显著增加活化分子比例，使有效碰撞增加。","examples":["【示范：N₂+3H₂合成NH₃的速率因素】用Δc/Δt表示平均速率并按1:3:2换算；升温、增反应气分压、加催化剂通常提速。对题给基元步骤只据其信息判断，不自行套更高层次数学模型。"],"visualSteps":["温度","算平均速率","按系数换算","解释因素","题给机理优先"]},{"label":"催化剂和表面积","rule":"催化剂降低活化能；固体粉碎增大接触面积，两者机制不同。","examples":["【示范：N₂+3H₂合成NH₃的速率因素】用Δc/Δt表示平均速率并按1:3:2换算；升温、增反应气分压、加催化剂通常提速。对题给基元步骤只据其信息判断，不自行套更高层次数学模型。"],"visualSteps":["催化剂和表面积","算平均速率","按系数换算","解释因素","题给机理优先"]}]},{"title":"图表、实验与表达","summary":"答案要把数据趋势和化学原因连接起来。","items":[{"label":"浓度—时间曲线","rule":"斜率绝对值表示瞬时速率，平台可能是反应结束或达到平衡，需结合可逆性判断。","examples":["【示范：由曲线和实验表判断快慢】先读轴和单位，浓度—时间曲线斜率绝对值越大速率越快；实验表比较时只选其余条件相同的两组。若用初段数据算初速，要统一时间和浓度单位。"],"visualSteps":["浓度—时间曲线","图像读轴","斜率","控制变量","表格计算"]},{"label":"初速或表格比较","rule":"选择只有一个条件不同的实验组做对照；若多因素同时改变不能直接归因。","examples":["【示范：由曲线和实验表判断快慢】先读轴和单位，浓度—时间曲线斜率绝对值越大速率越快；实验表比较时只选其余条件相同的两组。若用初段数据算初速，要统一时间和浓度单位。"],"visualSteps":["初速或表格比较","图像读轴","斜率","控制变量","表格计算"]},{"label":"机理信息","rule":"高中只根据题给基元步骤、中间体或能垒信息判断快慢和催化作用，不展开大学动力学的定量理论。","examples":["【示范：由曲线和实验表判断快慢】先读轴和单位，浓度—时间曲线斜率绝对值越大速率越快；实验表比较时只选其余条件相同的两组。若用初段数据算初速，要统一时间和浓度单位。"],"visualSteps":["机理信息","图像读轴","斜率","控制变量","表格计算"]}]},{"title":"工业条件的多目标权衡","summary":"“平衡最有利”不一定等于“生产最合适”。","items":[{"label":"温度折中","rule":"温度影响速率和放/吸热反应的平衡方向，选择兼顾两者的条件。","examples":["【示范：合成氨为何不用最低温最高压】降低温度有利于放热平衡但速率下降；增压提高平衡转化率却增加设备成本和风险；催化剂提高速率不改K。最终条件在速率、转化率、能耗、安全和设备间折中。"],"visualSteps":["温度折中","分开速率与限度","温度折中","压强成本","安全能耗"]},{"label":"压强与浓度","rule":"提高反应物分压可加快速率，也可能改变气相平衡，但高压设备成本和安全要求更高。","examples":["【示范：合成氨为何不用最低温最高压】降低温度有利于放热平衡但速率下降；增压提高平衡转化率却增加设备成本和风险；催化剂提高速率不改K。最终条件在速率、转化率、能耗、安全和设备间折中。"],"visualSteps":["压强与浓度","分开速率与限度","温度折中","压强成本","安全能耗"]},{"label":"催化剂","rule":"提高单位时间产量并降低所需温度，但不提高平衡转化率。","examples":["【示范：合成氨为何不用最低温最高压】降低温度有利于放热平衡但速率下降；增压提高平衡转化率却增加设备成本和风险；催化剂提高速率不改K。最终条件在速率、转化率、能耗、安全和设备间折中。"],"visualSteps":["催化剂","分开速率与限度","温度折中","压强成本","安全能耗"]}]},{"title":"反应方向：焓变—熵变—温度的定性链","summary":"高三综合题要把方向、限度和速率分开作答，再说明它们如何共同决定工业条件。","items":[{"label":"方向、限度、速率是三个问题","rule":"方向说明给定条件下哪一方向具有自发趋势；限度由平衡组成和K描述；速率说明到达某状态所需快慢。三者有关但不能互相代替。","examples":["【示范：放热反应也可能极慢】某反应能量上有利，但若活化能很高，常温下可能几乎观察不到；催化剂可以加快，却不改变焓变和平衡常数。"],"visualSteps":["先问方向","再问平衡限度","另问反应速率","最后综合调控"]},{"label":"焓变和熵变的定性作用","rule":"放热、熵增通常分别是有利因素；吸热、熵减通常分别是不利因素。任何一个因素都不能脱离另一个因素和温度单独绝对化。","examples":["【示范：两种因素一利一不利】合成氨正向放热但气体粒子数减少；CaCO₃分解吸热但生成气体、分散程度增大。两者都不能只凭ΔH或粒子数一句话判断。"],"visualSteps":["判断吸放热","判断分散程度","列出有利不利","拒绝单因素绝对化"]},{"label":"温度改变两因素的相对作用","rule":"当焓变和熵变因素方向相反时，温度可能改变反应的有利方向；高中只需结合题给事实和典型例子作定性判断。","examples":["【示范：CaCO₃高温分解】分解吸热且熵增，升高温度更有利于分解；达到什么程度还要看该温度下的平衡，分解快慢还受活化能影响。"],"visualSteps":["找相反因素","加入温度条件","判断方向倾向","再分开限度和速率"],"caution":"不建立大学热力学定量计算体系，题目若给新模型只按题给信息代数处理。"},{"label":"工业条件的完整表达","rule":"工业选择要依次说明温度和压强对速率、平衡与方向的影响，再加入催化剂选择性、能耗、设备成本和安全，不能只给“越低越好”或“越高越好”。","examples":["【示范：合成氨温度折中】低温在热力学和平衡上更有利于放热、熵减的正向，但反应速率慢；采用适宜温度和催化剂可提高单位时间产量，同时高压还需考虑设备成本和风险。"],"visualSteps":["方向与平衡","速率","催化剂","成本安全折中"]}]}],"workedExamples":[{"substance":"燃烧反应的ΔH三种算法","path":"由能量图可读生成物减反应物；由键能用断键总能−成键总能；由多步反应用盖斯定律相加。无论哪种方法，都先核对物态、系数和正负号。","labels":["判吸放热","物态系数","选择能量/键能/盖斯","核对ΔH"]},{"substance":"催化剂反应历程图","path":"无催化路径峰高，加入催化剂出现另一条低峰路径；正逆活化能都降低，而始态、终态和ΔH不变。若图中有多个峰，峰谷间可对应中间体和分步反应。","labels":["读始终态","看峰谷","比较活化能","区分路径与ΔH"]},{"substance":"N₂+3H₂合成NH₃的速率因素","path":"用Δc/Δt表示平均速率并按1:3:2换算；升温、增反应气分压、加催化剂通常提速。对题给基元步骤只据其信息判断，不自行套更高层次数学模型。","labels":["算平均速率","按系数换算","解释因素","题给机理优先"]},{"substance":"由曲线和实验表判断快慢","path":"先读轴和单位，浓度—时间曲线斜率绝对值越大速率越快；实验表比较时只选其余条件相同的两组。若用初段数据算初速，要统一时间和浓度单位。","labels":["图像读轴","斜率","控制变量","表格计算"]},{"substance":"合成氨为何不用最低温最高压","path":"降低温度有利于放热平衡但速率下降；增压提高平衡转化率却增加设备成本和风险；催化剂提高速率不改K。最终条件在速率、转化率、能耗、安全和设备间折中。","labels":["分开速率与限度","温度折中","压强成本","安全能耗"]},{"substance":"催化剂能量图","path":"催化曲线的始态和终态与无催化曲线相同，峰值更低；因此正逆反应活化能都降低、反应更快，而ΔH和一定温度下K不变。","labels":["路径变","始终态不变","速率变","限度不变"]},{"substance":"放热可逆反应升温","path":"升温使正逆速率都增大，反应更快；同时平衡向吸热的逆向移动，K减小。必须分别回答“速率”和“限度”。","labels":["速率都增大","平衡逆移","K减小"]},{"substance":"CaCO₃分解的三层分析","path":"吸热且熵增使高温更有利于分解；该温度下的平衡决定分解限度；粉碎、升温等还会影响到达平衡的速度。三层结论分别表达。","labels":["方向","限度","速率","条件边界"]},{"substance":"合成氨工业条件的完整答案","path":"从放热、气体粒子数减少判断温度和压强的平衡作用，再说明升温加快速率、催化剂只改变速率，最后加入能耗、设备和安全约束。","labels":["焓熵因素","平衡","速率","工程折中"]}],"checkpoints":["我能区分ΔH、活化能、速率和K。","我会正确读取反应历程图的横纵轴。","我能设计单变量速率实验。","我能用多目标权衡解释工业条件。","我能把反应方向、平衡限度和反应速率分成三句话说明。","我能在福建高中范围内用焓变、熵变和温度作定性判断。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h3_thermo_rate$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_THERMO_RATE' and skill_id = 'H3_THERMO_RATE';

update public.chem_knowledge_cards
set structured_content = $card_h3_equilibrium${"skillId":"H3_EQUILIBRIUM","version":2,"intro":"高三平衡综合需要同时说清三件事：体系是否达到平衡、条件改变后向哪边移动、平衡能进行到什么限度。工具分别是平衡标志、v正/v逆或Q-K、三段式与K。","overview":["平衡是动态的：v正=v逆且不为0，各组分含量保持不变。","Q<K向右，Q>K向左，Q=K平衡；温度不变时K固定。","三段式用一个变化量按计量数展开，平衡量代入K并验根。","图像先读坐标和控制条件，再区分瞬间、过程、新平衡。","等效平衡的核心是相同条件下能否归算到相同的起始投料状态或相同平衡组成。","真实c—t、v—t图要同时画出条件改变瞬间的跳变和随后到新平衡的连续变化；谁能瞬间跳变由操作直接决定。"],"visualSummary":{"kind":"cycle","title":"平衡受到扰动后的完整循环","steps":[{"label":"旧平衡","caption":"01"},{"label":"外界扰动","caption":"02"},{"label":"瞬时v正/v逆","caption":"03"},{"label":"Q与K判方向","caption":"04"},{"label":"定向移动","caption":"05"},{"label":"新平衡","caption":"06"}]},"sections":[{"title":"状态：怎样确认平衡","summary":"标志必须对该反应具有判别力。","items":[{"label":"直接标志","rule":"同一反应的正逆速率相等；用不同物质表示时要按系数归一。","examples":["【示范：2NO₂⇌N₂O₄确认平衡】密闭恒温下颜色不再变化，说明NO₂浓度保持不变；微观上正逆反应仍继续且v正=v逆。若选总质量等本来恒定的量，则不能据此判平衡。"],"visualSteps":["直接标志","可逆体系","v正=v逆","可变宏观量不变","排除恒量"]},{"label":"组成不变","rule":"反应物或生成物浓度、物质的量分数、颜色等不再变化。","examples":["【示范：2NO₂⇌N₂O₄确认平衡】密闭恒温下颜色不再变化，说明NO₂浓度保持不变；微观上正逆反应仍继续且v正=v逆。若选总质量等本来恒定的量，则不能据此判平衡。"],"visualSteps":["组成不变","可逆体系","v正=v逆","可变宏观量不变","排除恒量"]},{"label":"总量指标的条件","rule":"总压、密度、平均摩尔质量等只有在随反应进程会改变时，其不变才是有效标志。","examples":["【示范：2NO₂⇌N₂O₄确认平衡】密闭恒温下颜色不再变化，说明NO₂浓度保持不变；微观上正逆反应仍继续且v正=v逆。若选总质量等本来恒定的量，则不能据此判平衡。"],"visualSteps":["总量指标的条件","可逆体系","v正=v逆","可变宏观量不变","排除恒量"]}]},{"title":"方向：速率法与Q-K法","summary":"两种方法应给出同一结论。","items":[{"label":"速率法","rule":"条件改变瞬间v正>v逆向右，v正<v逆向左。","examples":["【示范：放热反应升温的速率法和Q-K法】升温瞬间正逆速率都增大但逆向增幅更大，故左移；也可由升温使放热反应K减小，而瞬间组成未变、Q仍为旧K，所以Q>K向左。"],"visualSteps":["速率法","瞬间速率比较","判断移动","温度改变K","Q与新K比较"]},{"label":"Q-K法","rule":"把当前组成代入反应商；Q<K向正方向，Q>K向逆方向。","examples":["【示范：放热反应升温的速率法和Q-K法】升温瞬间正逆速率都增大但逆向增幅更大，故左移；也可由升温使放热反应K减小，而瞬间组成未变、Q仍为旧K，所以Q>K向左。"],"visualSteps":["Q-K法","瞬间速率比较","判断移动","温度改变K","Q与新K比较"]},{"label":"勒夏特列法","rule":"用于定性判断浓度、压强、温度影响；对复杂或多条件题优先用Q-K更稳。","examples":["【示范：放热反应升温的速率法和Q-K法】升温瞬间正逆速率都增大但逆向增幅更大，故左移；也可由升温使放热反应K减小，而瞬间组成未变、Q仍为旧K，所以Q>K向左。"],"visualSteps":["勒夏特列法","瞬间速率比较","判断移动","温度改变K","Q与新K比较"]}]},{"title":"限度：K、转化率和三段式","summary":"K是平衡定量的中心。","items":[{"label":"K表达式","rule":"按平衡浓度/分压和计量数书写，纯固体纯液体通常不写。","examples":["【示范：A+B⇌2C的三段式和转化率】由起始量列-x、-x、+2x，写平衡浓度并代K；解出x后检查非负，再算某反应物转化率=x/初始量。反应倒转K取倒数，系数倍乘K取幂。"],"visualSteps":["K表达式","写K","三段式","验根","算转化率"]},{"label":"三段式","rule":"起始—变化—平衡，变化量服从计量数，代入K求解并排除负浓度等无意义根。","examples":["【示范：A+B⇌2C的三段式和转化率】由起始量列-x、-x、+2x，写平衡浓度并代K；解出x后检查非负，再算某反应物转化率=x/初始量。反应倒转K取倒数，系数倍乘K取幂。"],"visualSteps":["三段式","写K","三段式","验根","算转化率"]},{"label":"转化率与产率","rule":"转化率的分母是某反应物初始量；条件改变时K可能不变但转化率可变。","examples":["【示范：A+B⇌2C的三段式和转化率】由起始量列-x、-x、+2x，写平衡浓度并代K；解出x后检查非负，再算某反应物转化率=x/初始量。反应倒转K取倒数，系数倍乘K取幂。"],"visualSteps":["转化率与产率","写K","三段式","验根","算转化率"]},{"label":"反应式变换","rule":"逆反应K倒数，系数倍乘K取幂，多反应相加K相乘。","examples":["【示范：A+B⇌2C的三段式和转化率】由起始量列-x、-x、+2x，写平衡浓度并代K；解出x后检查非负，再算某反应物转化率=x/初始量。反应倒转K取倒数，系数倍乘K取幂。"],"visualSteps":["反应式变换","写K","三段式","验根","算转化率"]}]},{"title":"平衡图像的读取","summary":"任何图都先说清横轴改变了什么。","items":[{"label":"浓度—时间","rule":"突变表示瞬间直接改变的物质；随后曲线方向反映移动；新平台是新平衡。","examples":["【示范：浓度突变图完整读法】某反应物曲线在t时刻竖直上跳，表示直接加入；随后它下降、生成物上升，表示向正向移动；新平台表示新平衡。温度不变，所以新旧K相同。"],"visualSteps":["浓度—时间","读轴","找瞬间跳变","看随后趋势","判断新平台"]},{"label":"速率—时间","rule":"条件改变瞬间正逆速率的跳变大小决定移动方向，最终重新相等。","examples":["【示范：浓度突变图完整读法】某反应物曲线在t时刻竖直上跳，表示直接加入；随后它下降、生成物上升，表示向正向移动；新平台表示新平衡。温度不变，所以新旧K相同。"],"visualSteps":["速率—时间","读轴","找瞬间跳变","看随后趋势","判断新平台"]},{"label":"转化率—温度/压强","rule":"结合反应热和气体计量数判断趋势；催化剂只影响达到平衡速度，不改变平衡曲线终值。","examples":["【示范：浓度突变图完整读法】某反应物曲线在t时刻竖直上跳，表示直接加入；随后它下降、生成物上升，表示向正向移动；新平台表示新平衡。温度不变，所以新旧K相同。"],"visualSteps":["转化率—温度/压强","读轴","找瞬间跳变","看随后趋势","判断新平台"]},{"label":"控制变量","rule":"比较曲线前先确认除横轴外其他条件相同，不能把浓度和温度效应混在一起。","examples":["【示范：浓度突变图完整读法】某反应物曲线在t时刻竖直上跳，表示直接加入；随后它下降、生成物上升，表示向正向移动；新平台表示新平衡。温度不变，所以新旧K相同。"],"visualSteps":["控制变量","读轴","找瞬间跳变","看随后趋势","判断新平台"]}]},{"title":"等效平衡与工业优化","summary":"先归算投料，再谈是否等效。","items":[{"label":"恒温恒容","rule":"对反应前后气体物质的量改变的体系，通常要求归算后的各物质起始量相同才能得到相同平衡。","examples":["【示范：等效平衡和工业条件】恒温恒容时先把投料按反应计量关系归算到同一侧，再比较起始量；恒温恒压还要看投料比例与体积条件。工业选择同时考虑平衡组成、到达速度、设备成本和安全。"],"visualSteps":["恒温恒容","确认容器条件","归算投料","判断等效","多目标优化"]},{"label":"恒温恒压","rule":"按相同投料比例可能得到组成相同的平衡，具体结合反应和容器条件判断。","examples":["【示范：等效平衡和工业条件】恒温恒容时先把投料按反应计量关系归算到同一侧，再比较起始量；恒温恒压还要看投料比例与体积条件。工业选择同时考虑平衡组成、到达速度、设备成本和安全。"],"visualSteps":["恒温恒压","确认容器条件","归算投料","判断等效","多目标优化"]},{"label":"工业优化","rule":"高转化率、快速率、低成本、低能耗和安全之间折中；催化剂加快速率而不改K。","examples":["【示范：等效平衡和工业条件】恒温恒容时先把投料按反应计量关系归算到同一侧，再比较起始量；恒温恒压还要看投料比例与体积条件。工业选择同时考虑平衡组成、到达速度、设备成本和安全。"],"visualSteps":["工业优化","确认容器条件","归算投料","判断等效","多目标优化"]}]},{"title":"真实c—t与v—t图像","summary":"先在改变时刻画竖虚线，再分“瞬间”和“再平衡过程”两段作图。","items":[{"label":"c—t图：只有被直接改变的浓度能在瞬间跳变","rule":"恒温恒容下直接加入某反应物，该物质浓度在操作时刻竖直增大，其他未直接加入的物质浓度瞬间不变；随后反应移动，各浓度按计量关系连续变化到新平台。若改变体积，则所有气体浓度可能同时跳变。","examples":["【示范：A+B⇌C中突然加入A】t₁时c(A)先竖直上跳，c(B)、c(C)在t₁连续；随后平衡向右，c(A)从跳高值回落一部分，c(B)下降、c(C)上升，三条曲线最终到新平台。"],"visualSteps":["t₁：仅c(A)竖跳","随后A/B降、C升","新平台表示再次平衡"],"caution":"图形趋势限于题给单一可逆反应和明确操作；发生稀释、反应或相变等并发过程时先逐项判断直接影响。"},{"label":"压缩时先全体跳高，再按平衡方向分叉","rule":"恒温瞬间减小容器体积，所有气体组分的物质的量来不及改变，但c=n/V中的V减小，所以各气体浓度同时竖直增大；随后平衡才向气体计量数较少的一侧移动，反应物和生成物曲线沿相反方向渐变。","examples":["【示范：N₂+3H₂⇌2NH₃瞬间压缩】t₁时N₂、H₂、NH₃浓度都因V减小而上跳；随后向右移动，N₂、H₂从各自跳高值下降，NH₃继续上升，最终三者在更高压的新平衡平台稳定。"],"visualSteps":["V↓→三种c同时↑","右移：N₂/H₂↓、NH₃↑","到新平衡"],"caution":"“增压向少气体侧移动”只适用于有气体参加且两侧气体计量数和不同的平衡。"},{"label":"v—t图：比较正逆速率在瞬间谁跳得更多","rule":"平衡时v正=v逆。加入反应物会使v正立即增大，而v逆在瞬间通常不因生成物浓度改变；随后右移使反应物减少、生成物增加，v正下降、v逆上升，直到在新的非零值再次相等。","examples":["【示范：加入反应物后的v—t图】t₁前两条速率线重合；t₁时v正竖直上跳、v逆保持连续；t₁后v正逐渐回落、v逆逐渐升高，两线在新平衡时再次相交并重合。"],"visualSteps":["原平衡：v正=v逆","t₁：v正跳高","渐变后重新相等"],"caution":"瞬间哪条速率改变取决于操作直接改变了哪些组分和题给速率信息；陌生反应应服从题图或实验事实。"},{"label":"温度和催化剂图要分开画","rule":"升温通常使正、逆速率都瞬间增大，但吸热方向增大的程度更大，因此两条线跳高不同并引起移动；催化剂使正、逆速率在同一时刻按相同意义加快，原平衡组成不变，两条线同时跳到相等的更高值，不出现再平衡的分叉过程。","examples":["【示范：放热正反应升温与加催化剂对照】升温：v正、v逆都上跳，吸热的逆反应上跳更多，之后左移并重新相等；加催化剂：v正、v逆同时上跳且仍相等，c—t图没有瞬间浓度变化，也没有新的终值。"],"visualSteps":["升温：两线都跳、幅度不同","逆向占优→左移","催化剂：两线等幅意义加快、组成不变"],"caution":"催化剂不改变平衡常数和平衡组成；温度方向必须先看正反应是吸热还是放热。"},{"label":"用计量数检查曲线变化量","rule":"从操作后的瞬间值到新平衡值，各物质浓度变化量的绝对值之比等于化学计量数之比，反应物与生成物变化方向相反。它检查的是同一再平衡过程的渐变量，不包括加料或压缩造成的竖直跳变量。","examples":["【示范：A+2B⇌3C的图像校验】若再平衡过程中c(A)下降0.10 mol·L⁻¹，则c(B)应下降0.20 mol·L⁻¹、c(C)上升0.30 mol·L⁻¹；先从各自瞬间值量到新平台，不能把A因加料上跳的部分计入反应变化量。"],"visualSteps":["截取“瞬间值→新平台”","Δc比1∶2∶3","反应物降、生成物升"],"caution":"若反应过程中体积继续变化，浓度变化同时含体积效应，需按题给条件重新建模。"}]}],"workedExamples":[{"substance":"2NO₂⇌N₂O₄确认平衡","path":"密闭恒温下颜色不再变化，说明NO₂浓度保持不变；微观上正逆反应仍继续且v正=v逆。若选总质量等本来恒定的量，则不能据此判平衡。","labels":["可逆体系","v正=v逆","可变宏观量不变","排除恒量"]},{"substance":"放热反应升温的速率法和Q-K法","path":"升温瞬间正逆速率都增大但逆向增幅更大，故左移；也可由升温使放热反应K减小，而瞬间组成未变、Q仍为旧K，所以Q>K向左。","labels":["瞬间速率比较","判断移动","温度改变K","Q与新K比较"]},{"substance":"A+B⇌2C的三段式和转化率","path":"由起始量列-x、-x、+2x，写平衡浓度并代K；解出x后检查非负，再算某反应物转化率=x/初始量。反应倒转K取倒数，系数倍乘K取幂。","labels":["写K","三段式","验根","算转化率"]},{"substance":"浓度突变图完整读法","path":"某反应物曲线在t时刻竖直上跳，表示直接加入；随后它下降、生成物上升，表示向正向移动；新平台表示新平衡。温度不变，所以新旧K相同。","labels":["读轴","找瞬间跳变","看随后趋势","判断新平台"]},{"substance":"等效平衡和工业条件","path":"恒温恒容时先把投料按反应计量关系归算到同一侧，再比较起始量；恒温恒压还要看投料比例与体积条件。工业选择同时考虑平衡组成、到达速度、设备成本和安全。","labels":["确认容器条件","归算投料","判断等效","多目标优化"]},{"substance":"浓度突变图","path":"某反应物浓度在t时刻竖直升高，说明直接加入该反应物；随后其浓度下降、生成物上升，说明平衡向右；最终各浓度到新平台，K因温度不变而不变。","labels":["瞬间跳变","过程方向","新平台","K不变"]},{"substance":"Q-K方向判断","path":"A+B⇌2C，K=4。某时刻c(A)=c(B)=1、c(C)=1，则Q=1²/(1×1)=1<K，体系向右，直到Q增至4。","labels":["写Q","比较K","方向"]},{"substance":"平衡图像四层标注","path":"标t₁操作→画瞬间跳变→画移动过程的连续曲线→标新平台；最后用速率相等和计量数变化比双重检查。","labels":["操作时刻","瞬间","过程","新平衡"]}],"checkpoints":["我能分别回答状态、方向和限度。","我会选择速率法或Q-K法判断移动。","我能读出图中的瞬间变化和渐变。","我能列三段式并判断解是否合理。","我能在c—t图中区分直接跳变和反应渐变。","我能画出加料、压缩、升温和催化剂对应的v—t关键形状。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h3_equilibrium$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_EQUILIBRIUM' and skill_id = 'H3_EQUILIBRIUM';

update public.chem_knowledge_cards
set structured_content = $card_h3_aq${"skillId":"H3_AQ","version":2,"intro":"水溶液综合的底层是“粒子+平衡+守恒”。先列实际粒子和主要反应，再写Ka、Kb、Kw或Ksp控制趋势，最后用电荷、物料、质子守恒锁定数量。","overview":["弱电解质部分电离，盐可能水解，水始终微弱电离；粒子种类先列全。","Kw、Ka、Kb、Kh、Ksp在一定温度下固定，外界改变通过Q与K决定平衡方向。","电荷守恒适用于所有溶液，物料守恒跟踪来源，质子守恒联系酸碱转移。","滴定曲线按滴定前—缓冲/混合区—化学计量点—过量区分段。","沉淀问题用Qsp-Ksp；“沉淀完全”是低于题给残余标准，不是浓度为0。","分布曲线把同一酸碱组分的各种形态画成比例；读图先认横纵轴，再找优势形态、交点和题给pH。"],"visualSummary":{"kind":"network","title":"水溶液综合题的中心地图","center":"列全粒子","groups":[{"label":"平衡常数","items":["Kw/Ka/Kb/Kh/Ksp"]},{"label":"方向","items":["Q与K"]},{"label":"数量关系","items":["电荷/物料/质子守恒"]},{"label":"应用","items":["滴定四阶段","沉淀Qsp"]}]},"sections":[{"title":"粒子清单和主次判断","summary":"先决定谁大量存在，谁只是微量。","items":[{"label":"完全电离来源","rule":"强酸、强碱、可溶性盐先按化学计量数给出主要离子。","examples":["【示范：CH₃COONa溶液粒子清单】先完全电离得Na⁺、CH₃COO⁻；再由CH₃COO⁻水解补CH₃COOH、OH⁻，水还贡献极少H⁺。主要粒子先列，微弱平衡后处理。"],"visualSteps":["完全电离来源","完全电离","找弱者水解","列全部粒子","分主次"]},{"label":"弱平衡来源","rule":"弱酸弱碱分子与离子共存；能水解的盐离子、水的H⁺和OH⁻都要列入。","examples":["【示范：CH₃COONa溶液粒子清单】先完全电离得Na⁺、CH₃COO⁻；再由CH₃COO⁻水解补CH₃COOH、OH⁻，水还贡献极少H⁺。主要粒子先列，微弱平衡后处理。"],"visualSteps":["弱平衡来源","完全电离","找弱者水解","列全部粒子","分主次"]},{"label":"主次关系","rule":"强反应先做完全，再处理剩余粒子的弱电离、水解或沉淀平衡。","examples":["【示范：CH₃COONa溶液粒子清单】先完全电离得Na⁺、CH₃COO⁻；再由CH₃COO⁻水解补CH₃COOH、OH⁻，水还贡献极少H⁺。主要粒子先列，微弱平衡后处理。"],"visualSteps":["主次关系","完全电离","找弱者水解","列全部粒子","分主次"]}]},{"title":"四类常数的统一理解","summary":"表达式不同，逻辑都是平衡时Q=K。","items":[{"label":"Ka/Kb","rule":"描述弱酸/弱碱电离；同温下越大通常越强。","examples":["【示范：Ka、Kw、Ksp放在同一框架】醋酸电离用Ka，水用Kw，AgCl溶解用Ksp；三者都由相应平衡式写浓度幂之比且在一定温度下固定。外界改变先改变Q，再由Q与K判方向。"],"visualSteps":["Ka/Kb","写平衡式","写常数","温度条件","Q-K方向"]},{"label":"Kw","rule":"Kw=c(H⁺)c(OH⁻)，只随温度；中性为两者相等。","examples":["【示范：Ka、Kw、Ksp放在同一框架】醋酸电离用Ka，水用Kw，AgCl溶解用Ksp；三者都由相应平衡式写浓度幂之比且在一定温度下固定。外界改变先改变Q，再由Q与K判方向。"],"visualSteps":["Kw","写平衡式","写常数","温度条件","Q-K方向"]},{"label":"水解常数","rule":"共轭酸碱的水解可由相应Ka或Kb联系，具体按题给关系使用。","examples":["【示范：Ka、Kw、Ksp放在同一框架】醋酸电离用Ka，水用Kw，AgCl溶解用Ksp；三者都由相应平衡式写浓度幂之比且在一定温度下固定。外界改变先改变Q，再由Q与K判方向。"],"visualSteps":["水解常数","写平衡式","写常数","温度条件","Q-K方向"]},{"label":"Ksp","rule":"描述难溶电解质的溶解平衡；表达式含离子浓度的计量数次方。","examples":["【示范：Ka、Kw、Ksp放在同一框架】醋酸电离用Ka，水用Kw，AgCl溶解用Ksp；三者都由相应平衡式写浓度幂之比且在一定温度下固定。外界改变先改变Q，再由Q与K判方向。"],"visualSteps":["Ksp","写平衡式","写常数","温度条件","Q-K方向"]}]},{"title":"离子浓度排序与三大守恒","summary":"先守恒，再比较平衡强弱。","items":[{"label":"电荷守恒","rule":"正电荷浓度总和=负电荷浓度总和，多价离子乘电荷数。","examples":["【示范：CH₃COONa的浓度排序与守恒】由完全电离和少量水解知c(Na⁺)>c(CH₃COO⁻)>c(OH⁻)>c(H⁺)常为合理主次；再用物料守恒与电荷守恒核对，不能只背排序。"],"visualSteps":["电荷守恒","先判主要粒子","比较弱平衡","写物料守恒","写电荷守恒"]},{"label":"物料守恒","rule":"某元素或某组分所有存在形态的浓度之和等于投入总量关系。","examples":["【示范：CH₃COONa的浓度排序与守恒】由完全电离和少量水解知c(Na⁺)>c(CH₃COO⁻)>c(OH⁻)>c(H⁺)常为合理主次；再用物料守恒与电荷守恒核对，不能只背排序。"],"visualSteps":["物料守恒","先判主要粒子","比较弱平衡","写物料守恒","写电荷守恒"]},{"label":"质子守恒","rule":"由质子转移建立，可由电荷和物料守恒组合；写时明确参考态。","examples":["【示范：CH₃COONa的浓度排序与守恒】由完全电离和少量水解知c(Na⁺)>c(CH₃COO⁻)>c(OH⁻)>c(H⁺)常为合理主次；再用物料守恒与电荷守恒核对，不能只背排序。"],"visualSteps":["质子守恒","先判主要粒子","比较弱平衡","写物料守恒","写电荷守恒"]},{"label":"排序步骤","rule":"先比较大量的完全电离离子，再用电离/水解程度比较次要粒子，最后用守恒式核查。","examples":["【示范：CH₃COONa的浓度排序与守恒】由完全电离和少量水解知c(Na⁺)>c(CH₃COO⁻)>c(OH⁻)>c(H⁺)常为合理主次；再用物料守恒与电荷守恒核对，不能只背排序。"],"visualSteps":["排序步骤","先判主要粒子","比较弱平衡","写物料守恒","写电荷守恒"]}]},{"title":"pH与滴定曲线","summary":"每个区段的主要粒子不同，算法也不同。","items":[{"label":"滴定前","rule":"由待测酸碱本身决定；弱电解质需Ka/Kb。","examples":["【示范：强酸滴定弱碱曲线】滴定前用Kb；混合区先完全反应；计量点为共轭酸盐水解，pH通常<7；强酸过量后由剩余H⁺决定。指示剂变色范围要落在突跃内。"],"visualSteps":["滴定前","滴定前","混合反应","计量点水解","过量与终点"]},{"label":"反应进行中","rule":"先做n(H⁺)/n(OH⁻)或酸碱化学计量反应，再处理剩余和共轭体系。","examples":["【示范：强酸滴定弱碱曲线】滴定前用Kb；混合区先完全反应；计量点为共轭酸盐水解，pH通常<7；强酸过量后由剩余H⁺决定。指示剂变色范围要落在突跃内。"],"visualSteps":["反应进行中","滴定前","混合反应","计量点水解","过量与终点"]},{"label":"化学计量点","rule":"恰好反应完全不等于pH=7；强弱组合决定产物水解。","examples":["【示范：强酸滴定弱碱曲线】滴定前用Kb；混合区先完全反应；计量点为共轭酸盐水解，pH通常<7；强酸过量后由剩余H⁺决定。指示剂变色范围要落在突跃内。"],"visualSteps":["化学计量点","滴定前","混合反应","计量点水解","过量与终点"]},{"label":"过量区","rule":"由过量强酸或强碱主导；计算用混合后总体积。","examples":["【示范：强酸滴定弱碱曲线】滴定前用Kb；混合区先完全反应；计量点为共轭酸盐水解，pH通常<7；强酸过量后由剩余H⁺决定。指示剂变色范围要落在突跃内。"],"visualSteps":["过量区","滴定前","混合反应","计量点水解","过量与终点"]},{"label":"指示剂与终点","rule":"指示剂变色区间应落在pH突跃内；终点是实验指示，化学计量点是理论点。","examples":["【示范：强酸滴定弱碱曲线】滴定前用Kb；混合区先完全反应；计量点为共轭酸盐水解，pH通常<7；强酸过量后由剩余H⁺决定。指示剂变色范围要落在突跃内。"],"visualSteps":["指示剂与终点","滴定前","混合反应","计量点水解","过量与终点"]}]},{"title":"沉淀溶解与综合分离","summary":"把瞬时离子积与平衡限度分开。","items":[{"label":"Qsp判断","rule":"混合后先求瞬时浓度，Qsp>Ksp析出，Qsp<Ksp未饱和。","examples":["【示范：调pH分离Fe³⁺和Mg²⁺】按题给Ksp或沉淀pH范围，选择一个窗口使Fe(OH)₃的Qsp>Ksp充分沉淀，而Mg(OH)₂仍Qsp<Ksp；过滤分离。酸耗OH⁻可促氢氧化物溶解。"],"visualSteps":["Qsp判断","算瞬时Qsp","选择pH窗口","控制选择沉淀","说明完全标准"]},{"label":"pH控制","rule":"OH⁻或弱酸根浓度随pH变化，可用于分步沉淀、溶解和分离。","examples":["【示范：调pH分离Fe³⁺和Mg²⁺】按题给Ksp或沉淀pH范围，选择一个窗口使Fe(OH)₃的Qsp>Ksp充分沉淀，而Mg(OH)₂仍Qsp<Ksp；过滤分离。酸耗OH⁻可促氢氧化物溶解。"],"visualSteps":["pH控制","算瞬时Qsp","选择pH窗口","控制选择沉淀","说明完全标准"]},{"label":"沉淀转化","rule":"消耗一种离子或生成更稳定沉淀能推动转化；定量时构造总平衡常数。","examples":["【示范：调pH分离Fe³⁺和Mg²⁺】按题给Ksp或沉淀pH范围，选择一个窗口使Fe(OH)₃的Qsp>Ksp充分沉淀，而Mg(OH)₂仍Qsp<Ksp；过滤分离。酸耗OH⁻可促氢氧化物溶解。"],"visualSteps":["沉淀转化","算瞬时Qsp","选择pH窗口","控制选择沉淀","说明完全标准"]}]},{"title":"分布曲线从零读图","summary":"每条曲线回答“在这个pH下，总组分有多少以该形态存在”，所有同源形态的分数之和为1。","items":[{"label":"先认纵轴：分布分数不是浓度本身","rule":"分布分数表示某形态的量占该组分总量的比例，常写成0～1或0%～100%；同一pH处所有同源形态的分布分数之和为1。若总分析浓度为C，某形态浓度=其分布分数×C。","examples":["【示范：某pH下HA占20%】若HA/A⁻体系总浓度C=0.050 mol·L⁻¹，图上该pH处HA分布分数为0.20，则c(HA)=0.20×0.050=0.010 mol·L⁻¹；另一形态A⁻分数为0.80。"],"visualSteps":["读纵轴α=0.20","乘总浓度C","同源分数和=1核对"],"caution":"分布曲线只表示题中定义的同源酸碱形态；溶液还可能有旁观离子、水的H⁺和OH⁻，仍需另列。"},{"label":"一元弱酸：低pH分子形态占优，高pH离子形态占优","rule":"HA⇌H⁺+A⁻。pH较低意味着H⁺较多，平衡偏向HA，HA曲线高；pH升高时H⁺减少，平衡向A⁻方向移动，A⁻曲线上升。两曲线交点表示c(HA)=c(A⁻)，不是“酸完全电离”。","examples":["【示范：读HA与A⁻交点】从图的低pH端向右看：HA曲线由接近1下降，A⁻由接近0上升；交点处两者各占约50%；再向高pH端，A⁻成为优势形态。"],"visualSteps":["低pH：HA主导","交点：HA=A⁻","高pH：A⁻主导"],"caution":"不使用脱离曲线和题给常数的近似公式；需要定量时按Ka表达式、物料守恒和电荷守恒计算。"},{"label":"多元酸逐级失去质子，优势区依次更替","rule":"多元弱酸随pH升高通常按分子形态→少失一个H的阴离子→继续失H的阴离子依次占优。读图时逐条标物种电荷和相邻曲线交点，不跨级假设；中间形态常在中间pH区形成峰值。","examples":["【示范：碳酸体系三条分布曲线】低pH端H₂CO₃形态占优；pH升高后HCO₃⁻先成为主要形态；更高pH时CO₃²⁻比例继续上升并最终占优。任一点三种形态分数之和为1。"],"visualSteps":["H₂CO₃低pH占优","HCO₃⁻中间形成峰","CO₃²⁻高pH占优"],"caution":"曲线中的H₂CO₃是否包含溶解CO₂以题目定义为准；不要自行改动题给物种名称。"},{"label":"把题给pH竖线落到每条曲线","rule":"确定目标pH后画竖线，读取各形态比例和最大者；再把比例与总浓度、沉淀反应或守恒关系连接。若pH改变跨过交点，优势形态才发生更替；曲线高低不能直接证明酸的总浓度大小。","examples":["【示范：判断哪个pH更利于沉淀CO₃²⁻】在两种pH处分别画竖线；较高pH处若CO₃²⁻分布分数更大，在碳酸体系总浓度相同的前提下c(CO₃²⁻)更大，更容易使金属碳酸盐的Qsp增大并达到沉淀条件。"],"visualSteps":["pH处画竖线","读CO₃²⁻分数","乘总浓度后接Qsp"],"caution":"沉淀能否真正生成仍由混合后实际浓度和Qsp与Ksp比较决定，不能只凭分布分数大小下结论。"}]}],"workedExamples":[{"substance":"CH₃COONa溶液粒子清单","path":"先完全电离得Na⁺、CH₃COO⁻；再由CH₃COO⁻水解补CH₃COOH、OH⁻，水还贡献极少H⁺。主要粒子先列，微弱平衡后处理。","labels":["完全电离","找弱者水解","列全部粒子","分主次"]},{"substance":"Ka、Kw、Ksp放在同一框架","path":"醋酸电离用Ka，水用Kw，AgCl溶解用Ksp；三者都由相应平衡式写浓度幂之比且在一定温度下固定。外界改变先改变Q，再由Q与K判方向。","labels":["写平衡式","写常数","温度条件","Q-K方向"]},{"substance":"CH₃COONa的浓度排序与守恒","path":"由完全电离和少量水解知c(Na⁺)>c(CH₃COO⁻)>c(OH⁻)>c(H⁺)常为合理主次；再用物料守恒与电荷守恒核对，不能只背排序。","labels":["先判主要粒子","比较弱平衡","写物料守恒","写电荷守恒"]},{"substance":"强酸滴定弱碱曲线","path":"滴定前用Kb；混合区先完全反应；计量点为共轭酸盐水解，pH通常<7；强酸过量后由剩余H⁺决定。指示剂变色范围要落在突跃内。","labels":["滴定前","混合反应","计量点水解","过量与终点"]},{"substance":"调pH分离Fe³⁺和Mg²⁺","path":"按题给Ksp或沉淀pH范围，选择一个窗口使Fe(OH)₃的Qsp>Ksp充分沉淀，而Mg(OH)₂仍Qsp<Ksp；过滤分离。酸耗OH⁻可促氢氧化物溶解。","labels":["算瞬时Qsp","选择pH窗口","控制选择沉淀","说明完全标准"]},{"substance":"CH₃COONa溶液浓度关系","path":"Na⁺来自完全电离，CH₃COO⁻部分水解生成CH₃COOH和OH⁻。物料守恒c(Na⁺)=c(CH₃COO⁻)+c(CH₃COOH)；电荷守恒c(Na⁺)+c(H⁺)=c(CH₃COO⁻)+c(OH⁻)。","labels":["先列粒子","物料守恒","电荷守恒","显碱性"]},{"substance":"强酸滴定弱碱计量点","path":"计量点时弱碱恰好转化为其共轭酸盐；共轭酸发生水解产生H⁺，因此计量点通常显酸性，pH<7（常温常规条件）。","labels":["先完全反应","产物水解","计量点不等于中性"]},{"substance":"分布曲线四步读法","path":"认横轴pH→认纵轴比例→在目标pH画竖线→读取优势形态和各比例，再与总浓度、守恒或沉淀条件相连。","labels":["认轴","画竖线","读比例","接计算"]}],"checkpoints":["我能先列粒子再写平衡。","我会用守恒关系检查离子浓度排序。","我能分段分析滴定曲线。","我会用Qsp-Ksp而不是“看起来难溶”判断沉淀。","我能区分分布分数与实际浓度。","我能读出一元、多元弱酸在不同pH下的优势形态。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h3_aq$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_AQ' and skill_id = 'H3_AQ';

update public.chem_knowledge_cards
set structured_content = $card_h3_electro${"skillId":"H3_ELECTRO","version":2,"intro":"高三电化学装置可以很陌生，但解法稳定：判能量来源和装置类型，找氧化还原两端，写电极反应，按电中性判断膜迁移，最后用电子守恒做定量。","overview":["阳极氧化、阴极还原恒成立；原电池负极=阳极、正极=阴极。","电子经外电路移动，离子在电解质/膜中移动；不能让电子穿膜。","电极反应受介质影响，H⁺、OH⁻、H₂O必须按酸碱环境配平。","新型电池先找总反应和变价元素，充放电方向要分开。","定量统一到e⁻：两极、串联池、物质变化和电量都由电子守恒连接。"],"visualSummary":{"kind":"network","title":"电化学综合四线图","center":"电子守恒","groups":[{"label":"电极","items":["阳极氧化","阴极还原"]},{"label":"通道","items":["e⁻走外电路","离子走膜/溶液"]},{"label":"水溶液电解","items":["放电竞争","pH/浓度","溶液复原"]},{"label":"腐蚀","items":["析氢路径","吸氧路径","防护"]}]},"sections":[{"title":"装置类型与四个极名","summary":"先判原电池/电解池，再翻译极名。","items":[{"label":"原电池放电","rule":"自发反应输出电能：负极（阳极）氧化，正极（阴极）还原。","examples":["【示范：同一电池放电和充电】放电是原电池：负极氧化、正极还原；充电是电解池：阳极接电源正极氧化、阴极接负极还原。同一物理电极的氧化/还原及阴、阳极角色会反向，正负端按当前连接判断。"],"visualSteps":["原电池放电","先判放电/充电","看电源连接","定阴阳极","写氧化还原"]},{"label":"电解池","rule":"外加电源输入电能：阳极接正极并氧化，阴极接负极并还原。","examples":["【示范：同一电池放电和充电】放电是原电池：负极氧化、正极还原；充电是电解池：阳极接电源正极氧化、阴极接负极还原。同一物理电极的氧化/还原及阴、阳极角色会反向，正负端按当前连接判断。"],"visualSteps":["电解池","先判放电/充电","看电源连接","定阴阳极","写氧化还原"]},{"label":"充电电池","rule":"放电时是原电池，充电时是电解池；同一物理电极在充、放电时发生的氧化/还原反应及阴、阳极角色反向，判断正负端要看当前过程和电源连接。","examples":["【示范：同一电池放电和充电】放电是原电池：负极氧化、正极还原；充电是电解池：阳极接电源正极氧化、阴极接负极还原。同一物理电极的氧化/还原及阴、阳极角色会反向，正负端按当前连接判断。"],"visualSteps":["充电电池","先判放电/充电","看电源连接","定阴阳极","写氧化还原"]}]},{"title":"电极式从总反应反推","summary":"陌生装置不必先认识名称。","items":[{"label":"找变价元素","rule":"从总反应或物质变化判断谁失电子、谁得电子。","examples":["【示范：碱性氢氧燃料电池电极式】阳极H₂+2OH⁻-2e⁻=2H₂O；阴极O₂+2H₂O+4e⁻=4OH⁻。两式配成4e⁻后相加得到2H₂+O₂=2H₂O，并与介质中粒子变化核对。"],"visualSteps":["找变价元素","找变价","写骨架","按碱性介质配平","相加得总式"]},{"label":"写骨架","rule":"阳极把还原态写到左边并在右边放e⁻；阴极把氧化态和e⁻写左边。","examples":["【示范：碱性氢氧燃料电池电极式】阳极H₂+2OH⁻-2e⁻=2H₂O；阴极O₂+2H₂O+4e⁻=4OH⁻。两式配成4e⁻后相加得到2H₂+O₂=2H₂O，并与介质中粒子变化核对。"],"visualSteps":["写骨架","找变价","写骨架","按碱性介质配平","相加得总式"]},{"label":"按介质配平","rule":"酸性常用H⁺、H₂O，碱性常用OH⁻、H₂O；固体氧化物电解质还要跟踪O²⁻。","examples":["【示范：碱性氢氧燃料电池电极式】阳极H₂+2OH⁻-2e⁻=2H₂O；阴极O₂+2H₂O+4e⁻=4OH⁻。两式配成4e⁻后相加得到2H₂+O₂=2H₂O，并与介质中粒子变化核对。"],"visualSteps":["按介质配平","找变价","写骨架","按碱性介质配平","相加得总式"]},{"label":"相加核对","rule":"电子消去后应得到总反应，且与两极质量、气体和溶液pH变化一致。","examples":["【示范：碱性氢氧燃料电池电极式】阳极H₂+2OH⁻-2e⁻=2H₂O；阴极O₂+2H₂O+4e⁻=4OH⁻。两式配成4e⁻后相加得到2H₂+O₂=2H₂O，并与介质中粒子变化核对。"],"visualSteps":["相加核对","找变价","写骨架","按碱性介质配平","相加得总式"]}]},{"title":"膜与离子迁移","summary":"电荷在哪里增加，就要有相反电荷补偿。","items":[{"label":"盐桥","rule":"阴离子移向产生阳离子的负极区，阳离子移向消耗阳离子的正极区。","examples":["【示范：三室电解槽的膜方向】先写两极反应，标每室哪些阳/阴离子增加或减少；阳膜只让阳离子主要通过，阴膜只让阴离子主要通过；按电场与电中性共同确定迁移方向和物质的量。"],"visualSteps":["盐桥","两极反应","各室电荷账","膜选择性","电子数对应迁移量"]},{"label":"交换膜","rule":"阳膜允许阳离子主要通过，阴膜允许阴离子主要通过；方向由电场和电中性共同决定。","examples":["【示范：三室电解槽的膜方向】先写两极反应，标每室哪些阳/阴离子增加或减少；阳膜只让阳离子主要通过，阴膜只让阴离子主要通过；按电场与电中性共同确定迁移方向和物质的量。"],"visualSteps":["交换膜","两极反应","各室电荷账","膜选择性","电子数对应迁移量"]},{"label":"多室装置","rule":"逐室做电荷账：电极产生/消耗哪些离子，膜允许谁通过，溶液浓度和pH如何变化。","examples":["【示范：三室电解槽的膜方向】先写两极反应，标每室哪些阳/阴离子增加或减少；阳膜只让阳离子主要通过，阴膜只让阴离子主要通过；按电场与电中性共同确定迁移方向和物质的量。"],"visualSteps":["多室装置","两极反应","各室电荷账","膜选择性","电子数对应迁移量"]},{"label":"物质跨膜数","rule":"由每转移一定mol e⁻产生的净电荷数确定迁移离子量。","examples":["【示范：三室电解槽的膜方向】先写两极反应，标每室哪些阳/阴离子增加或减少；阳膜只让阳离子主要通过，阴膜只让阴离子主要通过；按电场与电中性共同确定迁移方向和物质的量。"],"visualSteps":["物质跨膜数","两极反应","各室电荷账","膜选择性","电子数对应迁移量"]}]},{"title":"常见装置与应用","summary":"用同一规则解释，不背设备外形。","items":[{"label":"燃料电池","rule":"燃料在阳极被氧化，氧化剂在阴极被还原；产物和电极式取决于酸、碱、熔融盐或固体氧化物介质。","examples":["【示范：燃料电池、精炼和腐蚀】燃料电池中燃料在阳极氧化；电解精炼时粗金属作阳极、纯金属在阴极析出；牺牲阳极保护让更活泼金属先氧化。每套装置都回到“阳极氧化、阴极还原”。"],"visualSteps":["燃料电池","判装置目的","阳极氧化","阴极还原","联系应用"]},{"label":"二次电池","rule":"放电总反应自发，充电总反应逆向；标注题目讨论的是充电还是放电。","examples":["【示范：燃料电池、精炼和腐蚀】燃料电池中燃料在阳极氧化；电解精炼时粗金属作阳极、纯金属在阴极析出；牺牲阳极保护让更活泼金属先氧化。每套装置都回到“阳极氧化、阴极还原”。"],"visualSteps":["二次电池","判装置目的","阳极氧化","阴极还原","联系应用"]},{"label":"电解精炼/电镀","rule":"精炼时粗金属阳极溶解、纯金属阴极析出；电镀件作阴极，镀层金属离子在阴极还原。","examples":["【示范：燃料电池、精炼和腐蚀】燃料电池中燃料在阳极氧化；电解精炼时粗金属作阳极、纯金属在阴极析出；牺牲阳极保护让更活泼金属先氧化。每套装置都回到“阳极氧化、阴极还原”。"],"visualSteps":["电解精炼/电镀","判装置目的","阳极氧化","阴极还原","联系应用"]},{"label":"腐蚀防护","rule":"牺牲阳极、外加电流和涂层保护分别从改变电极角色或隔绝介质解释。","examples":["【示范：燃料电池、精炼和腐蚀】燃料电池中燃料在阳极氧化；电解精炼时粗金属作阳极、纯金属在阴极析出；牺牲阳极保护让更活泼金属先氧化。每套装置都回到“阳极氧化、阴极还原”。"],"visualSteps":["腐蚀防护","判装置目的","阳极氧化","阴极还原","联系应用"]}]},{"title":"电子守恒定量","summary":"无论装置多复杂，电子账必须相等。","items":[{"label":"半反应系数","rule":"先读出生成1 mol产物需要或放出几mol e⁻。","examples":["【示范：串联电解池电子守恒】第一池析出0.10 mol Cu，由Cu²⁺+2e⁻=Cu知通过0.20 mol e⁻；串联第二池同样通过0.20 mol e⁻，再按其电极式求气体、质量或pH变化。"],"visualSteps":["半反应系数","由已知产物求e⁻","串联电量相同","按半反应换算","考虑总体积"]},{"label":"串联电解池","rule":"串联各池通过的电量相同，所以转移电子的物质的量相同。","examples":["【示范：串联电解池电子守恒】第一池析出0.10 mol Cu，由Cu²⁺+2e⁻=Cu知通过0.20 mol e⁻；串联第二池同样通过0.20 mol e⁻，再按其电极式求气体、质量或pH变化。"],"visualSteps":["串联电解池","由已知产物求e⁻","串联电量相同","按半反应换算","考虑总体积"]},{"label":"质量/气体/pH","rule":"由n(e⁻)经电极式转成金属质量、气体体积或H⁺/OH⁻变化，再考虑溶液体积。","examples":["【示范：串联电解池电子守恒】第一池析出0.10 mol Cu，由Cu²⁺+2e⁻=Cu知通过0.20 mol e⁻；串联第二池同样通过0.20 mol e⁻，再按其电极式求气体、质量或pH变化。"],"visualSteps":["质量/气体/pH","由已知产物求e⁻","串联电量相同","按半反应换算","考虑总体积"]}]},{"title":"水溶液电解与复原：从电极走回溶液","summary":"高三电化学不能停在电极式，还要追踪整池物质、pH和复原。","items":[{"label":"放电竞争的判断顺序","rule":"先看阳极是否为活性电极，再列阴、阳极附近可能放电的水和离子，结合浓度、介质与题给信息确定实际粒子。陌生体系优先使用题给总反应或电极信息。","examples":["【示范：CuSO₄使用惰性或铜阳极】惰性阳极时水放电生成O₂和H⁺；铜阳极时Cu可失电子生成Cu²⁺。只改电极材料就会改变总反应和溶液组成。"],"visualSteps":["看电极材料","列竞争粒子","结合介质条件","确定实际电极式"]},{"label":"总反应决定pH和浓度","rule":"配平并相加两极反应，删除没有净变化的粒子后，再判断H⁺、OH⁻、溶质和水的净增减；只看某一极容易得出错误pH结论。","examples":["【示范：惰性电极电解CuSO₄】2Cu²⁺+2H₂O通电生成2Cu+O₂↑+4H⁺；Cu²⁺减小、H⁺增加，所以溶液酸性增强。"],"visualSteps":["两极电子配平","合并总反应","找净增减","判断pH浓度"]},{"label":"按净损失选择复原物质","rule":"复原不是把原溶质机械加回，而是补回电解移走的元素组合并恢复体积；选择的物质不能引入额外离子。","examples":["【示范：CuSO₄电解液用CuO复原】CuO+2H⁺=Cu²⁺+H₂O，可同时补回析出的Cu并消耗因放氧产生的H⁺；若只有水被电解成H₂、O₂，则补适量水即可。"],"visualSteps":["读净损失","选择补加物","避免新杂质","核对体积与浓度"]}]},{"title":"腐蚀半反应与防护：环境决定阴极","summary":"共同负极是金属氧化，酸性或含氧水膜选择不同阴极路线。","items":[{"label":"析氢腐蚀","rule":"酸性较强的电解质水膜中，铁作负极失电子，较不活泼区域的H⁺得电子析H₂。","examples":["【示范：酸性水膜中的铁】负极Fe-2e⁻=Fe²⁺，正极2H⁺+2e⁻=H₂↑，相加得Fe+2H⁺=Fe²⁺+H₂↑。"],"visualSteps":["判酸性环境","Fe作负极","H⁺在阴极还原","相加总反应"]},{"label":"吸氧腐蚀","rule":"近中性或弱碱性、含O₂的水膜中，阴极常还原O₂生成OH⁻；随后Fe²⁺形成氢氧化物并继续氧化。","examples":["【示范：中性水膜中的铁】负极2Fe-4e⁻=2Fe²⁺，正极O₂+2H₂O+4e⁻=4OH⁻；Fe²⁺与OH⁻结合后继续被O₂氧化。"],"visualSteps":["判含氧水膜","Fe失电子","O₂生成OH⁻","连接铁锈过程"]},{"label":"腐蚀快慢与防护设计","rule":"腐蚀快慢除金属活泼性外，还受电极面积比、介质、含氧量、温度和接触方式影响。防护可隔绝介质、让更活泼金属牺牲，或用外电源使被保护金属作阴极。","examples":["【示范：钢铁连接锌或铜】连接Zn时Zn作负极被氧化，Fe受保护；连接Cu时Fe更易作负极，可能加快腐蚀。判断必须写出谁失电子。"],"visualSteps":["识别金属组合","判断负极","比较腐蚀对象","选择防护方案"]}]}],"workedExamples":[{"substance":"同一电池放电和充电","path":"放电是原电池：负极氧化、正极还原；充电是电解池：阳极接电源正极氧化、阴极接负极还原。同一物理电极的氧化/还原及阴、阳极角色会反向，正负端按当前连接判断。","labels":["先判放电/充电","看电源连接","定阴阳极","写氧化还原"]},{"substance":"碱性氢氧燃料电池电极式","path":"阳极H₂+2OH⁻-2e⁻=2H₂O；阴极O₂+2H₂O+4e⁻=4OH⁻。两式配成4e⁻后相加得到2H₂+O₂=2H₂O，并与介质中粒子变化核对。","labels":["找变价","写骨架","按碱性介质配平","相加得总式"]},{"substance":"三室电解槽的膜方向","path":"先写两极反应，标每室哪些阳/阴离子增加或减少；阳膜只让阳离子主要通过，阴膜只让阴离子主要通过；按电场与电中性共同确定迁移方向和物质的量。","labels":["两极反应","各室电荷账","膜选择性","电子数对应迁移量"]},{"substance":"燃料电池、精炼和腐蚀","path":"燃料电池中燃料在阳极氧化；电解精炼时粗金属作阳极、纯金属在阴极析出；牺牲阳极保护让更活泼金属先氧化。每套装置都回到“阳极氧化、阴极还原”。","labels":["判装置目的","阳极氧化","阴极还原","联系应用"]},{"substance":"串联电解池电子守恒","path":"第一池析出0.10 mol Cu，由Cu²⁺+2e⁻=Cu知通过0.20 mol e⁻；串联第二池同样通过0.20 mol e⁻，再按其电极式求气体、质量或pH变化。","labels":["由已知产物求e⁻","串联电量相同","按半反应换算","考虑总体积"]},{"substance":"碱性氢氧燃料电池","path":"阳极H₂+2OH⁻−2e⁻=2H₂O；阴极O₂+2H₂O+4e⁻=4OH⁻；配成4e⁻相加得2H₂+O₂=2H₂O。","labels":["燃料阳极氧化","氧阴极还原","碱性用OH⁻/H₂O"]},{"substance":"串联两电解池","path":"若第一池析出0.10 mol Cu，由Cu²⁺+2e⁻=Cu知通过0.20 mol e⁻；串联第二池也通过0.20 mol e⁻，再按其电极式求产物。","labels":["先由产物求e⁻","串联电子相同","再换第二池"]},{"substance":"惰性电极电解CuSO₄的完整物质账","path":"写两极式、配平电子、合成总式，推出Cu²⁺下降和H⁺增加，再按净损失选择CuO复原。答案依次覆盖电极、溶液和操作。","labels":["两极式","总反应","pH与浓度","复原"]},{"substance":"钢铁析氢与吸氧腐蚀对比","path":"负极均为Fe失电子；酸性水膜由H⁺在阴极得电子，近中性含氧水膜由O₂在阴极得电子。环境条件是选择阴极式的开关。","labels":["共同负极","判环境","两条阴极式","联系防护"]}],"checkpoints":["我能在充电、放电中分别标极。","我能从总反应写出适合介质的半反应。","我会逐室做电荷账判断膜迁移。","我能用电子守恒连接串联装置。","我能从水溶液电解的两极反应推出pH、浓度和复原方法。","我能依据水膜环境选择析氢或吸氧腐蚀的阴极式。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h3_electro$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_ELECTRO' and skill_id = 'H3_ELECTRO';

update public.chem_knowledge_cards
set structured_content = $card_h3_experiment${"skillId":"H3_EXPERIMENT","version":2,"intro":"实验综合不是背装置，而是建立证据链：目的决定原理，原理决定装置和操作，操作产生现象，现象支持结论；最后检查干扰、安全和误差。","overview":["完整实验链：目的—原理—装置/试剂—操作—现象—结论—误差。","制备实验按发生、净化、干燥、收集、检验、尾气处理组织。","探究实验必须控制变量、设置对照、排除干扰，结论不得超过证据。","定量实验先写测量量与待求量关系，再判断误差如何传递。","安全优先：气密性、防倒吸、防爆沸、有毒气体处理和规范加热。"],"visualSummary":{"kind":"network","title":"实验操作先按目的选","center":"实验目的","groups":[{"label":"固液分离","items":["过滤/洗涤","蒸发/结晶"]},{"label":"互溶液体","items":["蒸馏/分馏","温度计位置","冷凝水下进上出"]},{"label":"不互溶液体","items":["萃取/分液","振荡放气","下层先放"]},{"label":"证据链","items":["装置/操作","现象→结论","误差与安全"]}]},"sections":[{"title":"先把常见仪器和操作补回","summary":"每个操作都对应一个目的。","items":[{"label":"测量仪器","rule":"量筒量取近似体积，滴定管精确放液，容量瓶配制固定体积，移液管移取准确体积。滴定管、移液管按要求用待装液润洗；容量瓶不能用待配溶液润洗。","examples":["【示范：配液—加热—过滤的仪器链】用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。"],"visualSteps":["测量仪器","选择测量仪器","规范加热","过滤洗涤","检查气密性"]},{"label":"加热与冷却","rule":"试管、烧杯、坩埚等加热方式不同；加热前检查装置，停止加热后防倒吸，热玻璃不能骤冷。","examples":["【示范：配液—加热—过滤的仪器链】用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。"],"visualSteps":["加热与冷却","选择测量仪器","规范加热","过滤洗涤","检查气密性"]},{"label":"过滤、洗涤、结晶","rule":"过滤分固液；洗涤除表面可溶杂质；蒸发浓缩—冷却结晶适合溶解度随温度变化明显的物质。","examples":["【示范：配液—加热—过滤的仪器链】用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。"],"visualSteps":["过滤、洗涤、结晶","选择测量仪器","规范加热","过滤洗涤","检查气密性"]},{"label":"气密性","rule":"形成密闭体系，通过压强变化产生气泡、液面差等现象判断；装药前完成。","examples":["【示范：配液—加热—过滤的仪器链】用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。"],"visualSteps":["气密性","选择测量仪器","规范加热","过滤洗涤","检查气密性"]}]},{"title":"气体制备装置链","summary":"从反应物状态和条件选发生装置。","items":[{"label":"发生","rule":"固—固加热、固—液不加热或液—液加热决定装置；需要控制速率时用滴液漏斗等。","examples":["【示范：制备干燥NH₃的装置链】发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。"],"visualSteps":["发生","发生","净化干燥","收集","尾气与安全"]},{"label":"净化与干燥","rule":"先除杂再干燥；洗气试剂不能消耗主体或引入新杂质，气体通常长管进。","examples":["【示范：制备干燥NH₃的装置链】发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。"],"visualSteps":["净化与干燥","发生","净化干燥","收集","尾气与安全"]},{"label":"收集","rule":"由气体密度、溶解性、是否与水/空气反应选择排水、向上或向下排空气。","examples":["【示范：制备干燥NH₃的装置链】发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。"],"visualSteps":["收集","发生","净化干燥","收集","尾气与安全"]},{"label":"尾气与防倒吸","rule":"有毒、刺激性气体要吸收；易溶气体吸收时设置安全瓶、倒扣漏斗等防倒吸。","examples":["【示范：制备干燥NH₃的装置链】发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。"],"visualSteps":["尾气与防倒吸","发生","净化干燥","收集","尾气与安全"]}]},{"title":"检验与性质探究","summary":"现象必须具有唯一或经排干扰后的指向。","items":[{"label":"检验三件套","rule":"写“取样—加试剂/操作—观察现象—得出检出结论”，不能只报试剂名。","examples":["【示范：检验SO₄²⁻的完整证据】取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。"],"visualSteps":["检验三件套","取样","排除干扰","现象","对照与结论边界"]},{"label":"排除干扰","rule":"先除去或掩蔽会产生相同现象的粒子；试剂加入顺序可能决定结论是否可靠。","examples":["【示范：检验SO₄²⁻的完整证据】取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。"],"visualSteps":["排除干扰","取样","排除干扰","现象","对照与结论边界"]},{"label":"控制变量","rule":"只改变研究因素，其余物质用量、浓度、温度、接触面积等保持一致。","examples":["【示范：检验SO₄²⁻的完整证据】取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。"],"visualSteps":["控制变量","取样","排除干扰","现象","对照与结论边界"]},{"label":"对照与空白","rule":"阳性对照证明体系能出现预期现象，空白对照排除试剂或装置本身造成的现象。","examples":["【示范：检验SO₄²⁻的完整证据】取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。"],"visualSteps":["对照与空白","取样","排除干扰","现象","对照与结论边界"]}]},{"title":"定量实验和数据处理","summary":"先建计算模型，再操作。","items":[{"label":"滴定","rule":"标准液浓度和体积通过方程式计量关系求待测量；平行测定剔除明显异常，取相近值平均。","examples":["【示范：滴定数据和误差方向】平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。"],"visualSteps":["滴定","记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]},{"label":"称量法/气体法","rule":"由沉淀质量、质量差或气体体积反推组分；要保证转化完全、产物组成明确。","examples":["【示范：滴定数据和误差方向】平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。"],"visualSteps":["称量法/气体法","记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]},{"label":"有效数字与记录","rule":"记录精度由仪器决定；中间保留足够位数，最终按要求表达。","examples":["【示范：滴定数据和误差方向】平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。"],"visualSteps":["有效数字与记录","记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]},{"label":"误差方向","rule":"沿“操作错误→直接测量量偏大/偏小→公式中分子分母→结果方向”推，不背孤立结论。","examples":["【示范：滴定数据和误差方向】平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。"],"visualSteps":["误差方向","记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]}]},{"title":"方案评价和开放设计","summary":"评价要指出问题、后果和改进。","items":[{"label":"可行性","rule":"反应能否发生、现象是否明显、仪器条件是否满足。","examples":["【示范：评价一个气体制备方案】依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。"],"visualSteps":["可行性","可行性","科学性","安全环保","简约准确"]},{"label":"科学性","rule":"变量是否唯一、证据是否充分、结论是否超范围、是否有重复验证。","examples":["【示范：评价一个气体制备方案】依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。"],"visualSteps":["科学性","可行性","科学性","安全环保","简约准确"]},{"label":"安全与环保","rule":"有毒、腐蚀、易燃、爆炸风险是否控制，废液和尾气是否处理。","examples":["【示范：评价一个气体制备方案】依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。"],"visualSteps":["安全与环保","可行性","科学性","安全环保","简约准确"]},{"label":"简约与准确","rule":"在保证可靠前提下步骤更少、误差更小、资源更省；不能为简化牺牲证据。","examples":["【示范：评价一个气体制备方案】依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。"],"visualSteps":["简约与准确","可行性","科学性","安全环保","简约准确"]}]},{"title":"蒸馏、分馏、萃取和分液：按物性选操作","summary":"先判断混合物是否互溶、沸点差和溶解度差，再选择装置；操作细节决定安全和分离效果。","items":[{"label":"蒸馏","rule":"蒸馏利用互溶液体沸点不同，或从溶液中蒸出易挥发组分。温度计水银球应位于蒸馏烧瓶支管口附近；冷凝水下口进、上口出；加入沸石并避免蒸干。","examples":["【示范：从含少量非挥发杂质的水中制蒸馏水】水蒸气经冷凝得到馏出液，非挥发杂质留在烧瓶；温度计测的是进入支管的蒸气温度，不应插入液面下。"],"visualSteps":["按沸点差选择","温度计对准支管","冷凝水下进上出","接收馏分不蒸干"]},{"label":"分馏","rule":"多种互溶液体沸点接近时，使用分馏柱进行多次汽化—冷凝，可提高不同沸点馏分的分离程度；各馏分仍可能是混合物。","examples":["【示范：石油分馏】原油先受热汽化，不同沸点范围的组分在分馏塔不同高度冷凝；这是物理分离，不能写成裂化或裂解反应。"],"visualSteps":["互溶多组分","分馏柱多次平衡","按沸点范围收集","馏分仍可能混合"],"caution":"分馏与裂化、裂解不同，后两者涉及化学键变化。"},{"label":"萃取","rule":"萃取剂应与原溶剂互不相溶、不与溶质反应，且目标溶质在其中溶解度更大。加入分液漏斗后振荡、适时放气、静置分层。","examples":["【示范：从溴水中萃取Br₂】按题给选择一种与水不互溶且能较好溶解Br₂的有机溶剂；振荡放气后静置，Br₂主要转入有机层。不能只凭颜色判断上下层。"],"visualSteps":["检查萃取剂条件","振荡并放气","静置分层","确认目标所在层"]},{"label":"分液","rule":"分液用于分开互不相溶的液层。先打开上口塞或使内外相通，再从下口放出下层液体；到界面时关闭活塞，上层液体从上口倒出。上下层由密度或取样验证。","examples":["【示范：分开水层和有机层】先查题给密度判断哪层在下；若信息不足，可取少量某层滴入水中观察是否相溶。下层从活塞放出，上层从漏斗上口倒出，避免交叉污染。"],"visualSteps":["确认两液互不相溶","判断上下层","下层由下口放","上层由上口倒"]}]}],"workedExamples":[{"substance":"配液—加热—过滤的仪器链","path":"用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。","labels":["选择测量仪器","规范加热","过滤洗涤","检查气密性"]},{"substance":"制备干燥NH₃的装置链","path":"发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。","labels":["发生","净化干燥","收集","尾气与安全"]},{"substance":"检验SO₄²⁻的完整证据","path":"取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。","labels":["取样","排除干扰","现象","对照与结论边界"]},{"substance":"滴定数据和误差方向","path":"平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。","labels":["记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]},{"substance":"评价一个气体制备方案","path":"依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。","labels":["可行性","科学性","安全环保","简约准确"]},{"substance":"检验SO₄²⁻","path":"取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂溶液；若出现白色沉淀，可支持检出SO₄²⁻。若原样含Ag⁺等，还需考虑新增干扰。","labels":["取样","排干扰","加试剂","现象与边界"]},{"substance":"滴定读数偏差","path":"若滴定管尖嘴开始有气泡、结束时气泡消失，读出的标准液体积包含填充尖嘴的体积，读数偏大；由计算式判断待测浓度通常偏高。","labels":["先判V偏大","再看公式","结论方向"]},{"substance":"四种分离操作的选择树","path":"互溶液体先看沸点差：差较大可蒸馏，较接近且为多组分可分馏；互不相溶或可借助溶解度差转移溶质时先萃取，再用分液分层。","labels":["先判互溶性","再看沸点差","萃取转移","分液分层"]},{"substance":"溴水萃取—分液完整操作","path":"选择合适萃取剂，振荡并放气，静置分层；依据密度或取样确定目标层，先从下口放下层，再从上口倒出上层。每一步写出目的。","labels":["选剂","振荡放气","静置分层","规范分液"]}],"checkpoints":["我能把实验答案写成完整证据链。","我会按发生—净化—收集—尾气处理检查装置。","我能设计单变量和对照实验。","我会从直接测量量推导误差方向。","我能由互溶性、沸点差和溶解度差选择蒸馏、分馏、萃取或分液。","我能指出蒸馏温度计和冷凝水方向，并规范写出分液操作。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h3_experiment$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_EXPERIMENT' and skill_id = 'H3_EXPERIMENT';

update public.chem_knowledge_cards
set structured_content = $card_h3_structure${"skillId":"H3_STRUCTURE","version":2,"intro":"物质结构与性质按尺度逐层解释：电子排布决定成键倾向，价层电子对决定空间构型，粒子间作用决定晶体结构，晶体结构再决定熔沸点、硬度和导电性。","overview":["原子层：电子排布、价电子、周期位置、电离能/电负性等趋势。","分子层：Lewis结构、VSEPR、杂化、σ/π键、极性和分子间作用力。","晶体层：分子、离子、共价、金属晶体的构成粒子与作用力。","晶胞计算按“均摊计数—配位—几何关系—密度”完成。","只使用福建高中范围内模型，不展开大学层次的高级成键与晶体理论。"],"visualSummary":{"kind":"tree","title":"结构决定性质与证据的完整树","tree":{"label":"结构决定性质","children":[{"label":"原子层","children":[{"label":"电子云/轨道"},{"label":"基态/激发态/光谱"},{"label":"电离能/电负性"}]},{"label":"分子层","children":[{"label":"Lewis/VSEPR/杂化"},{"label":"极性/氢键"},{"label":"配合物"}]},{"label":"晶体层","children":[{"label":"晶体类型/非晶体"},{"label":"晶胞计算"},{"label":"X射线衍射证据"}]}]},"axes":[{"label":"最终落点","items":["宏观性质","结构测定证据"]}]},"sections":[{"title":"原子结构和电子排布","summary":"先找到价电子，才能解释化学性质。","items":[{"label":"能层、能级与轨道","rule":"电子按能量由低到高排布，遵守泡利原理、洪特规则和能量最低原理；每个轨道最多2个自旋相反电子。","examples":["【示范：Fe与Fe²⁺的电子排布】先按能量最低、泡利和洪特规则写Fe基态排布；形成Fe²⁺时先失较外层4s电子，再核对未成对电子数。周期趋势比较时说明电子层、有效核电荷和亚层稳定性的局部例外。"],"visualSteps":["能层、能级与轨道","能层能级轨道","价电子","原子到离子","周期趋势"]},{"label":"价电子排布","rule":"主族元素价电子决定主要成键和周期性质；过渡元素还要考虑(n−1)d与ns电子。","examples":["【示范：Fe与Fe²⁺的电子排布】先按能量最低、泡利和洪特规则写Fe基态排布；形成Fe²⁺时先失较外层4s电子，再核对未成对电子数。周期趋势比较时说明电子层、有效核电荷和亚层稳定性的局部例外。"],"visualSteps":["价电子排布","能层能级轨道","价电子","原子到离子","周期趋势"]},{"label":"电子排布表示","rule":"可用电子排布式、简化排布式、轨道表示式；失电子时按外层和题给规律处理。","examples":["【示范：Fe与Fe²⁺的电子排布】先按能量最低、泡利和洪特规则写Fe基态排布；形成Fe²⁺时先失较外层4s电子，再核对未成对电子数。周期趋势比较时说明电子层、有效核电荷和亚层稳定性的局部例外。"],"visualSteps":["电子排布表示","能层能级轨道","价电子","原子到离子","周期趋势"]},{"label":"周期趋势","rule":"原子半径、电离能、电负性总体有周期性，但第一电离能等存在由电子亚层稳定性导致的局部例外。","examples":["【示范：Fe与Fe²⁺的电子排布】先按能量最低、泡利和洪特规则写Fe基态排布；形成Fe²⁺时先失较外层4s电子，再核对未成对电子数。周期趋势比较时说明电子层、有效核电荷和亚层稳定性的局部例外。"],"visualSteps":["周期趋势","能层能级轨道","价电子","原子到离子","周期趋势"]}]},{"title":"化学键与Lewis结构","summary":"先数价电子，再画连接和孤电子对。","items":[{"label":"离子键/共价键/金属键","rule":"分别来自阴阳离子静电作用、原子间共享电子对、金属阳离子与自由电子的作用模型。","examples":["【示范：由CO₂画Lewis结构】统计总价电子，O—C—O先以单键连接，补外围八电子后中心C仍缺电子，形成两个C=O双键；再用形式电荷和总电子数核对。"],"visualSteps":["离子键/共价键/金属键","统计价电子","搭骨架","补八电子/多键","核对形式"]},{"label":"Lewis结构","rule":"统计价电子总数，选中心原子，先单键连接，补外围八电子，再把剩余电子给中心，必要时形成多键。","examples":["【示范：由CO₂画Lewis结构】统计总价电子，O—C—O先以单键连接，补外围八电子后中心C仍缺电子，形成两个C=O双键；再用形式电荷和总电子数核对。"],"visualSteps":["Lewis结构","统计价电子","搭骨架","补八电子/多键","核对形式"]},{"label":"形式与实际","rule":"Lewis式是电子计数模型，真实键可有离域；按课标和题给信息使用，不作大学理论展开。","examples":["【示范：由CO₂画Lewis结构】统计总价电子，O—C—O先以单键连接，补外围八电子后中心C仍缺电子，形成两个C=O双键；再用形式电荷和总电子数核对。"],"visualSteps":["形式与实际","统计价电子","搭骨架","补八电子/多键","核对形式"]}]},{"title":"VSEPR、杂化与分子性质","summary":"电子域相互排斥，决定大致空间排列。","items":[{"label":"价层电子对数","rule":"中心原子的成键电子域和孤电子对共同决定电子对构型；多键通常算一个电子域。","examples":["【示范：NH₃的空间结构与极性】N周围3个成键电子域和1个孤电子对，共4域，电子对构型四面体、sp³杂化；去掉孤对看分子为三角锥，键偶极不完全抵消，分子有极性。"],"visualSteps":["价层电子对数","数电子域","定VSEPR/杂化","去孤对定构型","矢量判极性"]},{"label":"常见对应","rule":"2域直线/sp，3域平面三角/sp²，4域四面体/sp³；分子构型还要去掉孤电子对位置。","examples":["【示范：NH₃的空间结构与极性】N周围3个成键电子域和1个孤电子对，共4域，电子对构型四面体、sp³杂化；去掉孤对看分子为三角锥，键偶极不完全抵消，分子有极性。"],"visualSteps":["常见对应","数电子域","定VSEPR/杂化","去孤对定构型","矢量判极性"]},{"label":"σ键与π键","rule":"单键通常1个σ键；双键1σ+1π；三键1σ+2π。","examples":["【示范：NH₃的空间结构与极性】N周围3个成键电子域和1个孤电子对，共4域，电子对构型四面体、sp³杂化；去掉孤对看分子为三角锥，键偶极不完全抵消，分子有极性。"],"visualSteps":["σ键与π键","数电子域","定VSEPR/杂化","去孤对定构型","矢量判极性"]},{"label":"分子极性","rule":"先看键的极性，再做空间矢量合成；对称分子可能含极性键但整体非极性。","examples":["【示范：NH₃的空间结构与极性】N周围3个成键电子域和1个孤电子对，共4域，电子对构型四面体、sp³杂化；去掉孤对看分子为三角锥，键偶极不完全抵消，分子有极性。"],"visualSteps":["分子极性","数电子域","定VSEPR/杂化","去孤对定构型","矢量判极性"]},{"label":"分子间作用力","rule":"范德华力、氢键等影响熔沸点、溶解性；它们不同于分子内化学键。","examples":["【示范：NH₃的空间结构与极性】N周围3个成键电子域和1个孤电子对，共4域，电子对构型四面体、sp³杂化；去掉孤对看分子为三角锥，键偶极不完全抵消，分子有极性。"],"visualSteps":["分子间作用力","数电子域","定VSEPR/杂化","去孤对定构型","矢量判极性"]}]},{"title":"配合物与晶体类型","summary":"先认构成粒子，再认作用力。","items":[{"label":"配位概念","rule":"中心离子/原子接受配体孤电子对形成配位键；识别配体、配位原子和配位数。","caution":"只按教材要求识别，不展开大学层次的配合物理论。","examples":["【示范：NaCl、金刚石、干冰和Cu】NaCl由离子构成，金刚石由原子共价网络构成，干冰由CO₂分子构成，Cu用金属键模型；从构成粒子和作用力解释熔点、硬度及导电性。配合物则另识别中心、配体和配位数。"],"visualSteps":["配位概念","识别构成粒子","判断作用力","晶体类型","结构解释性质"]},{"label":"分子晶体","rule":"构成粒子是分子，粒子间作用较弱，熔沸点通常较低；部分能形成氢键。","examples":["【示范：NaCl、金刚石、干冰和Cu】NaCl由离子构成，金刚石由原子共价网络构成，干冰由CO₂分子构成，Cu用金属键模型；从构成粒子和作用力解释熔点、硬度及导电性。配合物则另识别中心、配体和配位数。"],"visualSteps":["分子晶体","识别构成粒子","判断作用力","晶体类型","结构解释性质"]},{"label":"离子晶体","rule":"阴阳离子以静电作用构成，熔点较高，熔融或溶于水后常能导电。","examples":["【示范：NaCl、金刚石、干冰和Cu】NaCl由离子构成，金刚石由原子共价网络构成，干冰由CO₂分子构成，Cu用金属键模型；从构成粒子和作用力解释熔点、硬度及导电性。配合物则另识别中心、配体和配位数。"],"visualSteps":["离子晶体","识别构成粒子","判断作用力","晶体类型","结构解释性质"]},{"label":"共价晶体","rule":"原子以共价键形成空间网络，常硬、熔点高，导电性视结构而异。","examples":["【示范：NaCl、金刚石、干冰和Cu】NaCl由离子构成，金刚石由原子共价网络构成，干冰由CO₂分子构成，Cu用金属键模型；从构成粒子和作用力解释熔点、硬度及导电性。配合物则另识别中心、配体和配位数。"],"visualSteps":["共价晶体","识别构成粒子","判断作用力","晶体类型","结构解释性质"]},{"label":"金属晶体","rule":"用金属键模型解释金属晶体能够导电、导热并具有延展性。","examples":["【示范：NaCl、金刚石、干冰和Cu】NaCl由离子构成，金刚石由原子共价网络构成，干冰由CO₂分子构成，Cu用金属键模型；从构成粒子和作用力解释熔点、硬度及导电性。配合物则另识别中心、配体和配位数。"],"visualSteps":["金属晶体","识别构成粒子","判断作用力","晶体类型","结构解释性质"]}]},{"title":"晶胞与结构—性质解释","summary":"把图形问题拆成计数和几何。","items":[{"label":"均摊计数","rule":"顶点1/8、棱上1/4、面心1/2、体心1；边界外共享情况结合晶胞定义。","examples":["【示范：NaCl晶胞密度】按顶点1/8、面心1/2等均摊得到一个晶胞中的化学式单位数Z；数最近邻得配位数；用ρ=(ZM/Nₐ)/Vcell，先把边长换成cm。"],"visualSteps":["均摊计数","均摊计数","最近邻配位","晶胞质量","体积与单位"]},{"label":"配位数","rule":"以目标粒子为中心，数最近邻粒子；注意晶胞外同样存在邻居。","examples":["【示范：NaCl晶胞密度】按顶点1/8、面心1/2等均摊得到一个晶胞中的化学式单位数Z；数最近邻得配位数；用ρ=(ZM/Nₐ)/Vcell，先把边长换成cm。"],"visualSteps":["配位数","均摊计数","最近邻配位","晶胞质量","体积与单位"]},{"label":"密度公式","rule":"ρ=晶胞质量/晶胞体积=(Z·M/Nₐ)/Vcell；单位要统一。","examples":["【示范：NaCl晶胞密度】按顶点1/8、面心1/2等均摊得到一个晶胞中的化学式单位数Z；数最近邻得配位数；用ρ=(ZM/Nₐ)/Vcell，先把边长换成cm。"],"visualSteps":["密度公式","均摊计数","最近邻配位","晶胞质量","体积与单位"]},{"label":"性质解释链","rule":"明确“构成粒子—粒子间作用—需要克服的作用—宏观性质”，避免只说“结构稳定”。","examples":["【示范：NaCl晶胞密度】按顶点1/8、面心1/2等均摊得到一个晶胞中的化学式单位数Z；数最近邻得配位数；用ρ=(ZM/Nₐ)/Vcell，先把边长换成cm。"],"visualSteps":["性质解释链","均摊计数","最近邻配位","晶胞质量","体积与单位"]}]},{"title":"电子云、轨道和光谱：模型不能当真实轨迹","summary":"从电子运动概率模型出发，连接基态、激发态、跃迁和光谱证据。","items":[{"label":"电子云与原子轨道","rule":"电子云表示电子在核外空间出现概率密度的大小，不是电子真实运动轨迹；原子轨道是描述电子空间运动状态的模型，一个轨道最多容纳两个自旋相反电子。","examples":["【示范：读电子云图】图中颜色更深或点更密表示电子出现概率密度较大，不能说电子沿着图中边界作圆周运动，也不能把p轨道的两瓣当成两个轨道。"],"visualSteps":["概率密度","识别一个轨道","不画真实轨迹","联系最多2电子"]},{"label":"基态、激发态与跃迁","rule":"基态是电子按规则处于较低能量的稳定排布；吸收能量后电子可跃迁到较高能级形成激发态，回到较低能级时可释放能量。","examples":["【示范：判断排布是否为激发态】若某电子从低能轨道跃迁到更高能轨道，而总电子数不变且不违反泡利原理，该排布可为激发态；不能把它误判成新元素。"],"visualSteps":["先核总电子数","比较能级占据","吸收能量上跃","回落释放能量"]},{"label":"发射光谱与焰色证据","rule":"不同元素能级结构不同，激发态电子回落时可发出特征光谱；焰色是这一现象的宏观表现，可用于元素检出但不能唯一确定化合物或含量。","examples":["【示范：钠的黄色焰色】钠原子受热后电子被激发，回落时发出特征黄色光；看到黄色支持含钠元素，但NaCl、Na₂CO₃等都可能给出同类现象。"],"visualSteps":["受热激发","电子回落","发出特征光","结论落到元素"]}]},{"title":"第一电离能与电负性：总体趋势中找局部原因","summary":"先写定义，再用有效核电荷、半径和亚层稳定性解释趋势与例外。","items":[{"label":"第一电离能与电负性的含义","rule":"第一电离能反映气态基态原子失去第一个电子的难易；电负性表示成键原子吸引共用电子的能力。二者相关但不是同一个概念。","examples":["【示范：Na与Cl比较】同周期中Cl半径较小、有效核吸引较强，第一电离能和电负性总体高于Na；这分别对应失电子难易和成键时吸电子能力。"],"visualSteps":["先分清两个定义","比较核吸引与半径","判断失电子难易","判断共用电子偏移"]},{"label":"同周期和同主族总体趋势","rule":"同周期从左到右第一电离能、电负性总体增大；同主族从上到下通常总体减小。使用“总体”是因为电子亚层排布会带来局部例外。","examples":["【示范：第三周期总体趋势】Na到Cl有效核吸引总体增强，因此第一电离能和电负性总体上升；比较具体相邻元素时还要检查电子排布。"],"visualSteps":["先限定周期或族","写总体趋势","查看价电子排布","检查局部例外"]},{"label":"半充满、全充满造成的局部例外","rule":"同一能级中电子处于全充满或半充满状态时相对稳定，可能使第一电离能偏离简单单调趋势；解释要落到具体价电子排布。","examples":["【示范：Mg与Al、P与S】Mg的3s²全充满使其第一电离能可高于Al；P的3p³半充满使其第一电离能可高于S。不能因此推翻同周期总体趋势。"],"visualSteps":["写价电子排布","找全满或半满","解释局部反常","保留总体规律"],"caution":"局部例外只在教材常见范围和题给信息内使用，不无限扩展冷僻元素。"}]},{"title":"分子间作用力、氢键与溶解性","summary":"沸点和溶解性要先看粒子，再看分子间作用，不能只比较相对分子质量。","items":[{"label":"范德华力的比较边界","rule":"分子组成、相对分子质量、极化程度和分子形状都会影响范德华力；同系列中相对分子质量增大时，作用通常增强，但不能跨类型只用一个因素绝对比较。","examples":["【示范：卤素单质熔沸点】从Cl₂到Br₂到I₂，电子数和可极化性增大，分子间作用增强，熔沸点总体升高；这不是分子内共价键变强造成的。"],"visualSteps":["先认分子晶体","比较可极化性","判断分子间作用","解释熔沸点"]},{"label":"分子间与分子内氢键","rule":"与电负性较强的N、O、F相连的H可参与氢键。分子间氢键通常增强分子缔合并提高沸点；分子内氢键可能减少分子间缔合，二者对性质的影响不同。","examples":["【示范：H₂O与H₂S沸点】H₂O分子间能形成较强氢键，沸点显著高于同族相邻氢化物的一般趋势；不能把氢键写成H₂O分子内的O—H共价键。"],"visualSteps":["找N/O/F—H","判断氢键位置","比较分子间缔合","解释沸点异常"]},{"label":"相似相溶是经验规律","rule":"极性相近的物质通常较易互溶，但溶解还受氢键、反应、电离和分子大小等影响；“相似相溶”不能替代具体结构和相互作用分析。","examples":["【示范：乙醇与水互溶】乙醇的羟基可与水形成氢键，较短烃基的疏水影响有限，因此乙醇与水互溶；随烃链增长，水溶性通常下降。"],"visualSteps":["判断分子极性","寻找氢键","考虑非极性骨架","给出溶解趋势"]}]},{"title":"配合物、晶体与结构证据","summary":"颜色变化、衍射图样和晶胞模型分别提供不同层次的结构证据。","items":[{"label":"配合物的构成和颜色变化","rule":"中心离子或原子接受配体孤电子对形成配位键；要识别中心、配体、配位原子和配位数。配体变化可引起颜色变化，不应把所有颜色变化都判为氧化还原。","examples":["【示范：Cu²⁺与过量NH₃】先可能生成浅蓝色沉淀，继续加过量NH₃可形成深蓝色含铜配离子；Cu仍为+2价，主要变化是配位环境而非氧化还原。"],"visualSteps":["找中心Cu²⁺","找NH₃配体","观察颜色变化","核对价态未变"]},{"label":"晶体与非晶体","rule":"晶体内部粒子具有长程有序排列，常有确定熔点和各向异性等特征；非晶体缺少长程周期性。判断应结合结构证据，不能只凭外形是否规则。","examples":["【示范：石英与玻璃】石英是晶体，SiO₂结构长程有序；普通玻璃通常属于非晶态，宏观透明不代表内部具有晶格周期。"],"visualSteps":["观察宏观性质","联系长程有序","区分晶体非晶体","不凭外形独断"]},{"label":"结构测定方法的证据边界","rule":"X射线衍射可为晶体中粒子排列和晶胞参数提供证据；原子光谱用于元素和能级信息，分子光谱可反映某些键或结构信息。每种证据都有边界，通常需多证据交叉。","examples":["【示范：由X射线衍射确定晶胞】衍射数据可支持晶胞类型和参数，再结合化学组成计算粒子数与密度；不能由一张衍射图直接推出所有化学性质。"],"visualSteps":["先认测定对象","提取结构证据","与组成交叉","结论不超证据"]},{"label":"晶胞几何与空间利用","rule":"在题给晶胞模型中，可由均摊计数、最近邻、粒子接触关系和晶胞参数求配位数、化学式、密度或简单空间利用率；所有长度和体积单位必须统一。","examples":["【示范：立方晶胞密度】先按顶点1/8、面心1/2等求一个晶胞中的粒子数Z，再由接触关系求边长与半径联系，最后用ρ=ZM/(NₐV晶胞)并把长度换成cm。"],"visualSteps":["均摊计数","建立几何关系","求晶胞质量体积","统一单位校验"]}]}],"workedExamples":[{"substance":"Fe与Fe²⁺的电子排布","path":"先按能量最低、泡利和洪特规则写Fe基态排布；形成Fe²⁺时先失较外层4s电子，再核对未成对电子数。周期趋势比较时说明电子层、有效核电荷和亚层稳定性的局部例外。","labels":["能层能级轨道","价电子","原子到离子","周期趋势"]},{"substance":"由CO₂画Lewis结构","path":"统计总价电子，O—C—O先以单键连接，补外围八电子后中心C仍缺电子，形成两个C=O双键；再用形式电荷和总电子数核对。","labels":["统计价电子","搭骨架","补八电子/多键","核对形式"]},{"substance":"NH₃的空间结构与极性","path":"N周围3个成键电子域和1个孤电子对，共4域，电子对构型四面体、sp³杂化；去掉孤对看分子为三角锥，键偶极不完全抵消，分子有极性。","labels":["数电子域","定VSEPR/杂化","去孤对定构型","矢量判极性"]},{"substance":"NaCl、金刚石、干冰和Cu","path":"NaCl由离子构成，金刚石由原子共价网络构成，干冰由CO₂分子构成，Cu用金属键模型；从构成粒子和作用力解释熔点、硬度及导电性。配合物则另识别中心、配体和配位数。","labels":["识别构成粒子","判断作用力","晶体类型","结构解释性质"]},{"substance":"NaCl晶胞密度","path":"按顶点1/8、面心1/2等均摊得到一个晶胞中的化学式单位数Z；数最近邻得配位数；用ρ=(ZM/Nₐ)/Vcell，先把边长换成cm。","labels":["均摊计数","最近邻配位","晶胞质量","体积与单位"]},{"substance":"NH₃构型","path":"N有5个价电子，与3个H形成3个成键电子对，另有1个孤电子对，共4个电子域，N为sp³杂化；电子对构型四面体，分子构型三角锥，分子有极性。","labels":["数价电子","4电子域","去孤对看构型","判极性"]},{"substance":"晶胞密度","path":"先用均摊法得一个晶胞含Z个化学式单位，晶胞质量=ZM/Nₐ；由晶胞参数求体积并统一到cm³，代ρ=m/V。","labels":["均摊Z","摩尔质量","单位换算","密度"]},{"substance":"钠焰色背后的能级图","path":"受热使电子由较低能级跃迁到较高能级，回落时发出特征黄色光。把“能级差—光的能量—特征颜色”连起来，同时保留只能检出元素的证据边界。","labels":["受热激发","电子回落","特征发射","证据边界"]},{"substance":"Mg、Al、P、S第一电离能比较","path":"先写同周期总体增大，再用Mg的3s²全充满、P的3p³半充满解释Mg>Al、P>S两个局部例外。","labels":["总体趋势","价电子排布","局部稳定","得出比较"]},{"substance":"H₂O、Cu配离子和晶胞的三层结构证据","path":"分子层用氢键解释H₂O沸点，配合物层用中心—配体解释颜色变化，晶体层用衍射和晶胞计数解释密度。不同模型回答不同问题。","labels":["分子间作用","配位环境","晶体排列","模型边界"]}],"checkpoints":["我能从价电子画基础Lewis结构。","我能区分电子对构型和分子构型。","我能按构成粒子判断晶体类型。","我能用均摊法和密度公式处理晶胞。","我能区分电子云概率模型与电子真实运动轨迹。","我能解释第一电离能总体趋势和Mg/Al、P/S局部例外。","我能区分分子间氢键、分子内氢键和分子内共价键。","我能说明配合、光谱和X射线衍射分别提供什么证据。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h3_structure$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_STRUCTURE' and skill_id = 'H3_STRUCTURE';

update public.chem_knowledge_cards
set structured_content = $card_h3_organic${"skillId":"H3_ORGANIC","version":2,"intro":"有机化学从碳骨架和官能团重新开始：碳骨架决定同分异构，官能团决定主要性质，反应条件决定发生哪种转化。合成路线就是把这些转化按目标倒推和正推。","overview":["看结构先圈碳骨架、官能团、官能团数目与位置，再判断类别和性质。","常见反应类型：取代、加成、消去、氧化、还原、酯化、水解、加聚、缩聚。","同分异构体：分子式相同、结构不同；按碳链—位置—官能团顺序系统枚举。","合成推断同时追踪碳原子数、官能团变化、反应条件和题给新信息。","只使用福建高中教材要求的官能团、反应类型、转化路线和信息题方法，不展开大学层次的反应机理、立体化学命名和专门合成反应。"],"visualSummary":{"kind":"network","title":"有机化学完整证据网络","center":"结构与转化","groups":[{"label":"结构证据","items":["质谱看相对分子质量","红外看官能团","¹H NMR看等效氢"]},{"label":"碳骨架","items":["苯与芳香烃","顺反/手性识别","异构枚举"]},{"label":"官能团","items":["酚/醛/酯","性质与反应类型","官能团转化"]},{"label":"大分子","items":["糖/油脂/蛋白质","核酸","加聚/缩聚"]},{"label":"综合输出","items":["合成路线","实验与检验"]}]},"sections":[{"title":"有机物表示、分类和命名基础","summary":"先读懂结构，再谈反应。","items":[{"label":"碳骨架","rule":"判断链状/环状、脂肪/芳香、饱和/不饱和，数清主链和支链。","examples":["【示范：读CH₃CH(OH)CH₂CHO】先找最长含主要官能团碳链，圈羟基和醛基，编号使醛基位次最低；由结构式核分子式和不饱和度，再按命名规则组织名称。"],"visualSteps":["碳骨架","识别碳骨架","圈官能团","编号命名","分子式复核"]},{"label":"官能团","rule":"碳碳双/三键、卤素原子、羟基、醚键、醛基、羰基、羧基、酯基、酰胺基等决定特征性质。","examples":["【示范：读CH₃CH(OH)CH₂CHO】先找最长含主要官能团碳链，圈羟基和醛基，编号使醛基位次最低；由结构式核分子式和不饱和度，再按命名规则组织名称。"],"visualSteps":["官能团","识别碳骨架","圈官能团","编号命名","分子式复核"]},{"label":"命名思路","rule":"选含主要官能团的最长主链，编号使主要官能团和取代基位次合理，按规则写名称。","examples":["【示范：读CH₃CH(OH)CH₂CHO】先找最长含主要官能团碳链，圈羟基和醛基，编号使醛基位次最低；由结构式核分子式和不饱和度，再按命名规则组织名称。"],"visualSteps":["命名思路","识别碳骨架","圈官能团","编号命名","分子式复核"]},{"label":"分子式与不饱和度","rule":"由元素组成和结构特征核对环/双键信息；具体计算按课内不饱和度方法或题给信息。","examples":["【示范：读CH₃CH(OH)CH₂CHO】先找最长含主要官能团碳链，圈羟基和醛基，编号使醛基位次最低；由结构式核分子式和不饱和度，再按命名规则组织名称。"],"visualSteps":["分子式与不饱和度","识别碳骨架","圈官能团","编号命名","分子式复核"]}]},{"title":"常见官能团性质网络","summary":"把试剂、条件、断键成键和现象配成套。","items":[{"label":"烯烃/炔烃","rule":"可加成、加聚、被氧化；溴水褪色要结合反应对象排除其他还原性基团。","examples":["【示范：乙烯—乙醇—乙醛—乙酸—酯】乙烯加成得乙醇；乙醇氧化得乙醛，再氧化得乙酸；乙酸与乙醇酯化得乙酸乙酯。每一步把试剂条件和官能团变化配成对。"],"visualSteps":["烯烃/炔烃","烯烃加成","醇/醛氧化","羧酸酯化","条件与现象"]},{"label":"卤代烃","rule":"水解生成醇，消去生成不饱和键；条件不同产物不同。","examples":["【示范：乙烯—乙醇—乙醛—乙酸—酯】乙烯加成得乙醇；乙醇氧化得乙醛，再氧化得乙酸；乙酸与乙醇酯化得乙酸乙酯。每一步把试剂条件和官能团变化配成对。"],"visualSteps":["卤代烃","烯烃加成","醇/醛氧化","羧酸酯化","条件与现象"]},{"label":"醇与酚","rule":"醇可取代、氧化、消去、酯化；酚羟基受苯环影响呈弱酸性并有特征取代/显色反应。","examples":["【示范：乙烯—乙醇—乙醛—乙酸—酯】乙烯加成得乙醇；乙醇氧化得乙醛，再氧化得乙酸；乙酸与乙醇酯化得乙酸乙酯。每一步把试剂条件和官能团变化配成对。"],"visualSteps":["醇与酚","烯烃加成","醇/醛氧化","羧酸酯化","条件与现象"]},{"label":"醛、酮、羧酸、酯","rule":"醛易氧化并能还原银氨溶液/新制Cu(OH)₂；羧酸显酸性并酯化；酯可水解。","examples":["【示范：乙烯—乙醇—乙醛—乙酸—酯】乙烯加成得乙醇；乙醇氧化得乙醛，再氧化得乙酸；乙酸与乙醇酯化得乙酸乙酯。每一步把试剂条件和官能团变化配成对。"],"visualSteps":["醛、酮、羧酸、酯","烯烃加成","醇/醛氧化","羧酸酯化","条件与现象"]},{"label":"胺/酰胺与生物大分子","rule":"按教材掌握碱性、成盐、水解及蛋白质、糖类、油脂的基础性质，不展开超出课标的反应机理。","examples":["【示范：乙烯—乙醇—乙醛—乙酸—酯】乙烯加成得乙醇；乙醇氧化得乙醛，再氧化得乙酸；乙酸与乙醇酯化得乙酸乙酯。每一步把试剂条件和官能团变化配成对。"],"visualSteps":["胺/酰胺与生物大分子","烯烃加成","醇/醛氧化","羧酸酯化","条件与现象"]}]},{"title":"反应类型与条件","summary":"看到条件要反向联想到官能团变化。","items":[{"label":"取代","rule":"一个原子或基团被另一个原子或基团替换；常见实例有烷烃卤代、卤代烃水解和苯环取代。酯化、聚合等按教材给出的独立反应类型判断。","examples":["【示范：溴乙烷的水解和消去】溴乙烷在NaOH水溶液、加热条件下水解得乙醇；在NaOH醇溶液、加热条件下消去得乙烯。同一底物因条件不同发生不同反应。"],"visualSteps":["取代","读条件","判断取代/消去","画断键成键","核对产物"]},{"label":"加成与消去","rule":"加成使不饱和度降低，消去形成不饱和键；水/醇溶液、温度等条件是关键信号。","examples":["【示范：溴乙烷的水解和消去】溴乙烷在NaOH水溶液、加热条件下水解得乙醇；在NaOH醇溶液、加热条件下消去得乙烯。同一底物因条件不同发生不同反应。"],"visualSteps":["加成与消去","读条件","判断取代/消去","画断键成键","核对产物"]},{"label":"氧化与还原","rule":"跟踪C与O/H的关系：加O或去H常为氧化，加H或去O常为还原；最终以化合价/结构变化判断。","examples":["【示范：溴乙烷的水解和消去】溴乙烷在NaOH水溶液、加热条件下水解得乙醇；在NaOH醇溶液、加热条件下消去得乙烯。同一底物因条件不同发生不同反应。"],"visualSteps":["氧化与还原","读条件","判断取代/消去","画断键成键","核对产物"]},{"label":"聚合","rule":"加聚通常打开不饱和键不产生小分子；缩聚由多官能团单体反应并常放出小分子。","examples":["【示范：溴乙烷的水解和消去】溴乙烷在NaOH水溶液、加热条件下水解得乙醇；在NaOH醇溶液、加热条件下消去得乙烯。同一底物因条件不同发生不同反应。"],"visualSteps":["聚合","读条件","判断取代/消去","画断键成键","核对产物"]}]},{"title":"同分异构体系统枚举","summary":"写完要用分子式和条件双重核对。","items":[{"label":"第一步：确定类别","rule":"根据官能团、与试剂反应、核磁信号等题给条件确定可能类别。","examples":["【示范：C₄H₈O₂且能放CO₂的异构体】与NaHCO₃放CO₂先锁定羧基；再枚举满足总碳数的不同碳链和羧基位置，利用对称性去重；逐个回算分子式和题给反应量。"],"visualSteps":["第一步：确定类别","确定官能团类别","枚举碳链","移动位置并去重","条件筛选"]},{"label":"第二步：碳链异构","rule":"先画不同碳骨架，注意对称性，避免旋转/翻转造成重复。","examples":["【示范：C₄H₈O₂且能放CO₂的异构体】与NaHCO₃放CO₂先锁定羧基；再枚举满足总碳数的不同碳链和羧基位置，利用对称性去重；逐个回算分子式和题给反应量。"],"visualSteps":["第二步：碳链异构","确定官能团类别","枚举碳链","移动位置并去重","条件筛选"]},{"label":"第三步：位置异构","rule":"在每个骨架上移动官能团或多键，排除等价位置。","examples":["【示范：C₄H₈O₂且能放CO₂的异构体】与NaHCO₃放CO₂先锁定羧基；再枚举满足总碳数的不同碳链和羧基位置，利用对称性去重；逐个回算分子式和题给反应量。"],"visualSteps":["第三步：位置异构","确定官能团类别","枚举碳链","移动位置并去重","条件筛选"]},{"label":"第四步：条件筛选","rule":"用取代产物数、反应消耗量、苯环取代关系等逐条筛选并回算分子式。","examples":["【示范：C₄H₈O₂且能放CO₂的异构体】与NaHCO₃放CO₂先锁定羧基；再枚举满足总碳数的不同碳链和羧基位置，利用对称性去重；逐个回算分子式和题给反应量。"],"visualSteps":["第四步：条件筛选","确定官能团类别","枚举碳链","移动位置并去重","条件筛选"]}]},{"title":"合成路线与实验","summary":"正推看能做什么，逆推看目标从哪来。","items":[{"label":"逆推目标官能团","rule":"目标若是酯，前一步可考虑酸+醇；若是醇，可由卤代烃水解或羰基还原等课内路线得到。","examples":["【示范：由乙烯合成乙二酸乙二酯】先逆推目标酯来自乙二酸和乙二醇；再正推乙烯经加成/氧化等课内路线得到相应双官能团物质。每一步同时核对碳数、官能团、反应条件和实验分离。"],"visualSteps":["逆推目标官能团","逆推目标官能团","正推可行路线","跟踪碳数","考虑条件与纯化"]},{"label":"保护与选择性信息","rule":"若多官能团互相干扰，题目通常给保护/转化新信息；严格按信息迁移，不自行引入大学试剂。","examples":["【示范：由乙烯合成乙二酸乙二酯】先逆推目标酯来自乙二酸和乙二醇；再正推乙烯经加成/氧化等课内路线得到相应双官能团物质。每一步同时核对碳数、官能团、反应条件和实验分离。"],"visualSteps":["保护与选择性信息","逆推目标官能团","正推可行路线","跟踪碳数","考虑条件与纯化"]},{"label":"跟踪碳数","rule":"每一步检查碳骨架是否增长、缩短、成环或断裂，避免只盯官能团。","examples":["【示范：由乙烯合成乙二酸乙二酯】先逆推目标酯来自乙二酸和乙二醇；再正推乙烯经加成/氧化等课内路线得到相应双官能团物质。每一步同时核对碳数、官能团、反应条件和实验分离。"],"visualSteps":["跟踪碳数","逆推目标官能团","正推可行路线","跟踪碳数","考虑条件与纯化"]},{"label":"有机实验","rule":"关注试剂用量、加热方式、冷凝回流、萃取洗涤、蒸馏结晶和产率纯化。","examples":["【示范：由乙烯合成乙二酸乙二酯】先逆推目标酯来自乙二酸和乙二醇；再正推乙烯经加成/氧化等课内路线得到相应双官能团物质。每一步同时核对碳数、官能团、反应条件和实验分离。"],"visualSteps":["有机实验","逆推目标官能团","正推可行路线","跟踪碳数","考虑条件与纯化"]}]},{"title":"质谱、红外和氢谱：三种证据回答三个问题","summary":"先用分子量和分子式缩小范围，再用官能团和等效氢信息拼出结构。","items":[{"label":"质谱提供相对分子质量线索","rule":"高中题常由质谱中的分子离子峰等题给信息判断相对分子质量，再结合元素分析确定分子式；峰值不能脱离题目说明机械解释。","examples":["【示范：C、H、O有机物的质谱】题给分子离子峰对应相对分子质量46，再结合元素比例可锁定C₂H₆O；此时仍有乙醇和二甲醚等不同结构，不能停在分子式。"],"visualSteps":["读取题给分子量","结合元素组成","确定分子式","保留结构多解"]},{"label":"红外光谱识别官能团","rule":"不同化学键或官能团在红外光谱中有特征吸收。高中只按题给峰位信息识别官能团，不凭单个吸收峰唯一确定整分子结构。","examples":["【示范：区分乙醇和二甲醚】两者分子式都为C₂H₆O；若红外显示O—H特征吸收，可支持乙醇，若没有O—H而有C—O信息，则支持醚类。"],"visualSteps":["先看分子式","查特征吸收","识别官能团","不由单峰锁全结构"]},{"label":"核磁共振氢谱识别等效氢","rule":"氢谱信号组数通常对应不同化学环境的氢的种类，积分面积比对应各组氢数之比；对称性会使多个H等效。具体裂分规则只按题给信息使用。","examples":["【示范：C₂H₆O两种结构】二甲醚CH₃OCH₃的两组CH₃等效，常只有1组氢信号；乙醇CH₃CH₂OH通常有3类氢。与红外证据结合即可区分。"],"visualSteps":["找对称性","数等效氢种类","读积分比","与红外交叉"]}]},{"title":"等效氢、顺反和手性：只做到结构识别","summary":"先画清连接关系和对称性，再判断是否满足异构条件；不要求超纲命名。","items":[{"label":"等效氢与一氯代物数目","rule":"能由分子对称操作互换、且处在相同化学环境中的H可视为等效；一氯取代物种数通常等于不等效氢的种类数，还要排除重复结构。","examples":["【示范：正丁烷的一氯代物】两端CH₃上的H彼此等效，两个中间CH₂上的H在基础计数中归为另一类，因此得到两种不同连接位置的一氯代物。"],"visualSteps":["画完整碳骨架","寻找对称面或对称轴","标不等效H","对应一氯代物去重"]},{"label":"顺反异构的条件","rule":"碳碳双键限制旋转，且双键两个碳各自都连接两个不同基团时，才可能存在顺反异构；任一双键碳连接两个相同基团就不满足。","examples":["【示范：2-丁烯与1-丁烯】2-丁烯双键两端都分别连接H和CH₃，存在顺、反两种；1-丁烯端碳连接两个H，不存在顺反异构。"],"visualSteps":["找到C=C","检查左端两个基团","检查右端两个基团","判断有无顺反"]},{"label":"手性碳原子的识别边界","rule":"四面体碳原子连接四个不同原子或基团时可构成手性中心。福建高中只需按结构识别和计数，不要求使用更高层次的构型命名。","examples":["【示范：乳酸CH₃CH(OH)COOH】中间碳分别连接H、OH、CH₃、COOH四个不同基团，是手性碳；羧基碳为平面结构，不按此标准计入。"],"visualSteps":["找四面体碳","列四个相连基团","检查是否全部不同","只识别不作超纲命名"]}]},{"title":"芳香烃：苯环稳定性、取代和侧链","summary":"苯不能机械按三个孤立双键处理，苯环反应和侧链反应要分开。","items":[{"label":"苯的结构证据和特殊稳定性","rule":"苯分子中六个碳碳键等同，具有特殊稳定性；结构简式中的交替单双键只是表征方式，不能把苯完全类比为普通烯烃。","examples":["【示范：苯与溴水】苯在通常条件下不能像乙烯那样因加成使溴水迅速褪色；若出现分层和有机层带色，可能只是Br₂溶解与萃取。"],"visualSteps":["识别苯环","知道六键等同","不机械套烯烃","区分反应与萃取"]},{"label":"苯环取代反应","rule":"苯可在催化剂和适当条件下发生卤代、硝化等取代反应，苯环保留而H被取代；试剂和条件必须与反应类型成套书写。","examples":["【示范：苯的溴代】苯与液溴在FeBr₃等催化条件下生成溴苯和HBr；不能写成“苯使溴水褪色发生加成”。"],"visualSteps":["读苯环底物","识别催化条件","H被基团取代","苯环保持"]},{"label":"苯同系物的侧链氧化","rule":"苯环会影响与其直接相连的侧链。苯同系物被强氧化剂氧化时，产物要看苄位是否有H及题给规则；不能把所有烷基苯无条件写成苯甲酸。","examples":["【示范：甲苯与酸性KMnO₄】甲基碳有苄位H，可被氧化为羧基，使酸性KMnO₄褪色；苯本身在相同常规条件下不发生这一侧链反应。"],"visualSteps":["找到苯环侧链","检查苄位H","按题给氧化规则","核对碳骨架"]}]},{"title":"酚、醛和酯：试剂—现象—结构闭环","summary":"每个特征反应都要带试剂条件、可观察现象和结论边界。","items":[{"label":"苯酚的弱酸性、取代和显色","rule":"苯酚弱酸性强于醇但通常弱于碳酸，能与NaOH反应而通常不与NaHCO₃放CO₂；可与浓溴水发生取代并与Fe³⁺产生特征显色。","examples":["【示范：苯酚与浓溴水】生成2,4,6-三溴苯酚白色沉淀；现象可支持酚羟基及活化苯环，但检验仍要结合其他可能干扰。"],"visualSteps":["先认酚羟基","选择浓溴水或Fe³⁺","记录沉淀或显色","限定检验结论"]},{"label":"醛基的银镜和新制Cu(OH)₂检验","rule":"醛基易被氧化，能在规定条件下还原银氨溶液或新制Cu(OH)₂；含醛基的物质不一定属于醛类，葡萄糖等也可呈阳性。","examples":["【示范：乙醛与新制Cu(OH)₂】在碱性并加热条件下出现砖红色Cu₂O沉淀，乙醛被氧化；若缺少新制、碱性或加热条件，现象可能不可靠。"],"visualSteps":["识别醛基","配套检验试剂","写明加热条件","现象支持含醛基"]},{"label":"酯化与酸、碱水解","rule":"羧酸与醇的酯化通常可逆；酯在酸性条件下水解可逆，在碱性条件下生成羧酸盐，常使水解更趋完全。产物由介质决定。","examples":["【示范：乙酸乙酯水解】酸性水解生成乙酸和乙醇并建立平衡；NaOH条件下生成乙酸钠和乙醇，羧酸被转成盐，推动反应进行。"],"visualSteps":["先认酯基","读酸碱介质","确定酸或盐产物","判断反应限度"]}]},{"title":"生命有机物与高分子：结构层次决定反应","summary":"只保留福建高中要求的结构特点、典型性质、检验和聚合物反推。","items":[{"label":"糖类与葡萄糖","rule":"糖类按能否继续水解可分单糖、二糖和多糖。葡萄糖兼有多羟基和醛基性质；蔗糖、淀粉等水解产物和还原性不能机械等同。","examples":["【示范：淀粉水解后检验葡萄糖】先在酸性条件下水解，冷却后用碱中和酸，再加新制Cu(OH)₂并加热；若直接在强酸性水解液中检验，会破坏所需碱性条件。"],"visualSteps":["判断糖类层次","完成水解","中和酸","检验还原性产物"]},{"label":"油脂、氨基酸和蛋白质","rule":"油脂是高级脂肪酸与甘油形成的酯，可氢化和水解，碱性水解称皂化；氨基酸含氨基和羧基而有两性，可缩合形成肽键；蛋白质要区分盐析、变性和水解。","examples":["【示范：油脂皂化与蛋白质盐析】1 mol甘油三酯完全皂化通常消耗3 mol OH⁻并生成甘油和高级脂肪酸盐；蛋白质盐析常可逆，变性通常破坏其天然结构且不易恢复。"],"visualSteps":["数酯基","写皂化产物","识别肽键来源","区分盐析与变性"]},{"label":"核酸的结构信息边界","rule":"DNA和RNA由核苷酸单元构成；碱基配对中的氢键有助于维持结构。高中只需读懂教材或题给结构信息，不要求记忆大学层次复制机理和全部结构细节。","examples":["【示范：读DNA片段示意图】先区分共价连接的主链与碱基间氢键，再按题给配对信息统计氢键或单元数；不能把氢键写成主链中的共价键。"],"visualSteps":["识别核苷酸单元","区分主链与碱基","识别氢键","按题给信息计算"]},{"label":"加聚、缩聚与单体反推","rule":"加聚打开不饱和键且通常不放小分子；缩聚需要合适的多官能团单体并常放出小分子。由聚合物反推单体时要恢复双键或断开缩聚连接点。","examples":["【示范：聚乙烯和聚酯对比】聚乙烯链节—CH₂—CH₂—恢复为CH₂=CH₂；聚酯在酯键处断开并补回相应端基，得到二元酸和二元醇等单体，同时核对小分子。"],"visualSteps":["识别链节连接","判断加聚或缩聚","恢复单体官能团","核对小分子与原子"]}]}],"workedExamples":[{"substance":"读CH₃CH(OH)CH₂CHO","path":"先找最长含主要官能团碳链，圈羟基和醛基，编号使醛基位次最低；由结构式核分子式和不饱和度，再按命名规则组织名称。","labels":["识别碳骨架","圈官能团","编号命名","分子式复核"]},{"substance":"乙烯—乙醇—乙醛—乙酸—酯","path":"乙烯加成得乙醇；乙醇氧化得乙醛，再氧化得乙酸；乙酸与乙醇酯化得乙酸乙酯。每一步把试剂条件和官能团变化配成对。","labels":["烯烃加成","醇/醛氧化","羧酸酯化","条件与现象"]},{"substance":"溴乙烷的水解和消去","path":"溴乙烷在NaOH水溶液、加热条件下水解得乙醇；在NaOH醇溶液、加热条件下消去得乙烯。同一底物因条件不同发生不同反应。","labels":["读条件","判断取代/消去","画断键成键","核对产物"]},{"substance":"C₄H₈O₂且能放CO₂的异构体","path":"与NaHCO₃放CO₂先锁定羧基；再枚举满足总碳数的不同碳链和羧基位置，利用对称性去重；逐个回算分子式和题给反应量。","labels":["确定官能团类别","枚举碳链","移动位置并去重","条件筛选"]},{"substance":"由乙烯合成乙二酸乙二酯","path":"先逆推目标酯来自乙二酸和乙二醇；再正推乙烯经加成/氧化等课内路线得到相应双官能团物质。每一步同时核对碳数、官能团、反应条件和实验分离。","labels":["逆推目标官能团","正推可行路线","跟踪碳数","考虑条件与纯化"]},{"substance":"乙醇到乙酸乙酯","path":"乙醇先氧化可得乙醛，再氧化得乙酸；乙酸与乙醇在浓硫酸、加热条件下酯化生成乙酸乙酯和水。每一步标官能团：羟基→醛基→羧基→酯基。","labels":["官能团追踪","氧化","酯化","条件"]},{"substance":"限定同分异构体","path":"先由分子式和“能与NaHCO₃放CO₂”锁定羧基，再枚举满足碳数的碳骨架和羧基位置，利用等效位置去重，最后逐个核对分子式和题给其他现象。","labels":["先定官能团","枚举碳链","位置去重","条件复核"]},{"substance":"C₂H₆O的三谱证据链","path":"质谱和元素分析先确定分子式；红外判断是否有O—H；氢谱比较等效氢种类。三类证据合用可区分乙醇和二甲醚，单一证据不够。","labels":["分子量与分子式","红外官能团","氢谱等效氢","交叉锁定"]},{"substance":"2-丁烯与乳酸的立体结构识别","path":"2-丁烯双键两端各有两个不同基团，所以有顺反结构；乳酸中间碳连接四个不同基团，是手性碳。只做结构识别，不作超出高中范围的构型命名。","labels":["检查双键两端","判断顺反","列四个基团","识别手性中心"]},{"substance":"苯—苯酚—甲苯的反应分工","path":"苯以催化取代为主，不能机械使溴水加成褪色；苯酚使苯环活化，可与浓溴水生成白色沉淀；甲苯的苄位H使侧链可被强氧化剂氧化。","labels":["苯环稳定","苯酚取代","侧链氧化","条件分流"]},{"substance":"从油脂到蛋白质再到聚合物","path":"油脂按三个酯基处理皂化计量；蛋白质区分盐析、变性和水解；合成高分子先判加聚或缩聚，再反推单体并核对小分子。","labels":["官能团计数","性质边界","判聚合类型","反推单体"]}],"checkpoints":["我能先圈官能团再判断性质。","我能由反应条件反推官能团变化。","我会按碳链—位置—类别系统写同分异构体。","我能在合成路线中同步追踪碳数和官能团。","我能把质谱、红外和氢谱分别对应到分子量、官能团和等效氢。","我能判断顺反异构和手性中心，但不使用超出福建高中范围的构型命名。","我能区分苯环取代、酚的特征反应和苯同系物侧链氧化。","我能说明糖类、油脂、蛋白质、核酸与高分子的结构—性质主线。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card_h3_organic$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_ORGANIC' and skill_id = 'H3_ORGANIC';

insert into public.chem_questions(
  id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind,
  usable_for_class_quiz,usable_for_review,usable_for_exam_sprint
) values (
  'QCOMP_H1_PERIODIC_01','MCOMP_H1_PERIODIC_01','H1_PERIODIC',1,'高一',
  '某原子的核外电子分层排布为2、8、7。该元素在周期表中的位置是','["第3周期ⅦA族","第3周期ⅥA族","第4周期ⅠA族","第2周期ⅦA族"]'::jsonb,0,'电子层数为3，所以在第3周期；最外层有7个电子，所以是ⅦA族主族元素。位置判断先看电子层数，再看最外层电子数。','把“3个电子层”和“最外层7个电子”分别翻译成周期数与主族序数。',
