) values (
  'QCOMP_H3_THERMO_RATE_01','MCOMP_H3_THERMO_RATE_01','H3_THERMO_RATE',5,'高三',
  '已知C(s)+O₂(g)=CO₂(g)　ΔH₁，CO(g)+1/2O₂(g)=CO₂(g)　ΔH₂，则C(s)+1/2O₂(g)=CO(g)的ΔH为','["ΔH₁-ΔH₂","ΔH₁+ΔH₂","ΔH₂-ΔH₁","-ΔH₁-ΔH₂"]'::jsonb,0,'目标反应等于第一个反应加上第二个反应的逆反应，因此ΔH=ΔH₁+(-ΔH₂)=ΔH₁-ΔH₂。反应式倒转时ΔH变号。','先把目标式中的CO放到生成物一侧，再决定哪条已知反应需要倒转。',
  'approved','IN','teacher_original',false,true,true
)
