) values (
  'QCOMP_H1_MOLE_01','MCOMP_H1_MOLE_01','H1_MOLE',6,'高一',
  '某浓盐酸中HCl的质量分数为36.5%，溶液密度为1.18 g·mL⁻¹。该盐酸中HCl的物质的量浓度约为（HCl的摩尔质量为36.5 g·mol⁻¹）','["3.65 mol·L⁻¹","11.8 mol·L⁻¹","36.5 mol·L⁻¹","1.18 mol·L⁻¹"]'::jsonb,1,'取1 L溶液，其质量为1.18×1000=1180 g；HCl质量为1180×36.5%=430.7 g，物质的量为430.7/36.5=11.8 mol，所以c=11.8 mol·L⁻¹。','固定取1 L溶液，按“体积→溶液质量→溶质质量→物质的量→浓度”依次换算。',
  'approved','IN','teacher_original',false,true,true
)
