) values (
  'QCOMP_H2_RATE_01','MCOMP_H2_RATE_01','H2_RATE',5,'高二',
  '某产气反应记录为：0 s时0 mL，20 s时0 mL，40 s时12 mL，60 s时20 mL。下列判断正确的是','["三个时间段的平均产气速率相同","0～20 s可能为诱导期；按产气体积估算，20～40 s平均产气速率大于40～60 s","0～20 s没有气体，说明化学反应一定没有开始","40～60 s平均产气速率为1.0 mL·s⁻¹"]'::jsonb,1,'0～20 s未收集到气体可能是诱导、装置充气或检测阈值造成，不能断言反应未开始；20～40 s为12/20=0.60 mL·s⁻¹，40～60 s为8/20=0.40 mL·s⁻¹。','先逐段计算ΔV/Δt，再把“观测为0”和“微观反应未发生”区分开。',
  'approved','IN','teacher_original',false,true,true
)
