) values (
  'QCOMP_H2_PH_HYDRO_02','MCOMP_H2_PH_HYDRO_02','H2_PH_HYDRO',6,'高二',
  '用已知浓度NaOH溶液滴定未知浓度CH₃COOH溶液，若误选甲基橙作指示剂，滴至其变色即停止，其他操作正确，则测得CH₃COOH浓度通常','["偏高","不变","无法出现颜色变化","偏低"]'::jsonb,3,'弱酸被强碱滴定的化学计量点溶液显碱性，甲基橙变色范围偏酸，会在到达化学计量点前变色，消耗NaOH体积偏小，因此计算出的醋酸浓度偏低。','先判断化学计量点酸碱性，再比较指示剂变色范围与滴定突跃区的位置。',
  'approved','IN','teacher_original',false,true,true
)
