insert into public.chem_questions(
  id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind,
  usable_for_class_quiz,usable_for_review,usable_for_exam_sprint
) values (
  'QCOMP_H3_EQUILIBRIUM_01','MCOMP_H3_EQUILIBRIUM_01','H3_EQUILIBRIUM',7,'高三',
  '恒温下，反应2NO₂(g)⇌N₂O₄(g)已达平衡。t₁时c(NO₂)与c(N₂O₄)均瞬间增大为原来的2倍；随后c(NO₂)逐渐减小、c(N₂O₄)继续增大，直至新平衡。t₁时进行的操作最可能是','["将容器体积突然压缩为原来的一半","加入催化剂","移走部分N₂O₄","升高温度"]'::jsonb,0,'两种气体浓度同时瞬间变为2倍，说明体积突然减半；随后平衡向气体物质的量较少的N₂O₄一侧移动，正好对应NO₂下降、N₂O₄继续上升。','先用“是否瞬间突变、哪些量同时突变”判断操作，再用后续缓慢变化判断平衡移动。',
  'approved','IN','teacher_original',false,true,true
)
on conflict(id) do update set
  mother_id=excluded.mother_id,skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,
