insert into public.chem_questions(
  id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind,
  usable_for_class_quiz,usable_for_review,usable_for_exam_sprint
) values (
  'QCOMP_H2_ELECTRO_05','MCOMP_H2_ELECTRO_05','H2_ELECTRO',6,'高二',
  '用惰性电极电解CuSO₄溶液一段时间，阴极析出Cu、阳极放出O₂。若要在不引入新杂质的前提下使溶液组成恢复到电解前，适合加入','["适量金属Cu","适量CuO","适量CuCl₂","适量NaOH"]'::jsonb,1,'电解总效应可写成2CuSO₄+2H₂O→2Cu+O₂+2H₂SO₄，溶液酸性增强。加入CuO可与H₂SO₄反应生成CuSO₄和H₂O，补回电解时离开体系的Cu、O组成而不引入新离子。','先写两极反应并合并总反应，再问“从溶液中净移走了哪种物质的组成”。',
  'approved','IN','teacher_original',false,true,true
)
on conflict(id) do update set
