) values (
  'QCOMP_H3_INORGANIC_05','MCOMP_H3_INORGANIC_05','H3_INORGANIC',5,'高三',
  '向新制FeSO₄溶液中加入NaOH溶液，并使生成的沉淀暴露在空气中，典型颜色变化是','["白色沉淀迅速变为灰绿色，最终变为红褐色","蓝色沉淀最终变为黑色","始终为白色且不变化","先黄色后变为紫色"]'::jsonb,0,'Fe²⁺先生成白色Fe(OH)₂，但实际观察中常很快呈灰绿色；在空气中被O₂氧化，最终生成红褐色Fe(OH)₃。反应为4Fe(OH)₂+O₂+2H₂O=4Fe(OH)₃。','按时间顺序写三格：刚生成Fe(OH)₂、短时表观颜色、被空气氧化后的Fe(OH)₃。',
  'approved','IN','teacher_original',false,true,true
)
