insert into public.chem_questions(
  id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind,
  usable_for_class_quiz,usable_for_review,usable_for_exam_sprint
) values (
  'QCOMP_H3_EXPERIMENT_07','MCOMP_H3_EXPERIMENT_07','H3_EXPERIMENT',6,'高三',
  '使用分液漏斗完成萃取、静置分层后，正确的分液操作是','["下层从上口倒出，上层从下口放出","先打开上口塞或使塞上凹槽对准小孔，下层液体从下口放出，上层液体从上口倒出","始终塞紧上口，下层和上层都从下口连续放出","不经振荡和放气，直接从上口倒出两层液体"]'::jsonb,1,'放液前要使漏斗内外气压相通；下层从下口放出可在界面到达旋塞时准确停止，上层再从上口倒出，避免被下口残留的下层液体污染。振荡过程中还应适时放气。','按“通气→下层下放→界面停→上层上倒”的顺序复述操作。',
  'approved','IN','teacher_original',false,true,true
)
