insert into public.chem_questions(
  id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind,
  usable_for_class_quiz,usable_for_review,usable_for_exam_sprint
) values (
  'QCOMP_H3_STRUCTURE_08','MCOMP_H3_STRUCTURE_08','H3_STRUCTURE',6,'高三',
  '关于物质结构测定方法与所得信息的对应关系，下列正确的是','["质谱可提供相对分子质量信息，红外光谱可提示官能团，X射线衍射可研究晶体结构","红外光谱直接给出晶胞中每个原子的三维坐标，质谱只测颜色","X射线衍射只能测溶液pH，不能研究晶体","核磁共振氢谱只能判断元素种类，不能反映不同化学环境的氢"]'::jsonb,0,'质谱的分子离子峰等可提供相对分子质量信息；红外吸收与化学键振动有关，可提示官能团；X射线衍射是解析晶体结构的重要方法。不同方法回答不同层级的问题。','建立“质量—质谱、官能团—红外、晶体空间结构—X射线”的一一对应表。',
  'approved','IN','teacher_original',false,true,true
)
