insert into public.chem_questions(
  id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind,
  usable_for_class_quiz,usable_for_review,usable_for_exam_sprint
) values (
  'QCOMP_H3_ORGANIC_05','MCOMP_H3_ORGANIC_05','H3_ORGANIC',6,'高三',
  '推断未知有机物结构时，下列“三谱信息—作用”对应正确的是','["红外光谱可直接给出所有同分异构体的唯一结构，无需其他信息","质谱估计相对分子质量，红外光谱识别官能团，¹H核磁共振谱判断不同化学环境氢的种类及数目比","质谱直接确定所有化学键，红外只测分子质量，¹H核磁只测元素种类","三种谱图只能判断物质颜色"]'::jsonb,1,'三种证据各有分工：质谱重点给出相对分子质量及碎片信息，红外提示特征官能团，¹H核磁反映等效氢种类和峰面积比。通常要把多种证据与化学性质共同拼接，不能靠单一谱图包办。','把未知结构拆成三个问题：多重、有什么官能团、有几类氢且比例怎样。',
  'approved','IN','teacher_original',false,true,true
)
