) values (
  'QCOMP_H3_ORGANIC_12','MCOMP_H3_ORGANIC_12','H3_ORGANIC',4,'高三',
  '关于常见生物大分子的说法正确的是','["油脂属于蛋白质，水解只生成葡萄糖","核酸的基本组成单元是高级脂肪酸","纤维素和淀粉的分子式、结构和性质完全相同","淀粉和纤维素都属于多糖，蛋白质水解可得到氨基酸"]'::jsonb,3,'淀粉和纤维素都由葡萄糖单元聚合而成，属于多糖，但连接方式和结构不同，性质也不同；蛋白质由氨基酸构成，水解最终可得到氨基酸。','按“类别—基本单元—水解产物”整理糖类、油脂、蛋白质和核酸，不能只看元素组成。',
  'approved','IN','teacher_original',false,true,true
)
