insert into public.chem_questions(
  id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind,
  usable_for_class_quiz,usable_for_review,usable_for_exam_sprint
) values (
  'QCOMP_H1_NACL_05','MCOMP_H1_NACL_05','H1_NACL',2,'高一',
  '某样品的焰色试验中直接观察到强烈黄色。若还要判断样品中是否含钾元素，下一步最合适的是','["改用湿润蓝色石蕊试纸","仅凭黄色直接判定一定不含钾","透过蓝色钴玻璃观察是否出现紫色焰色","加入AgNO₃观察白色沉淀"]'::jsonb,2,'钠的黄色焰色很强，可能遮住钾的紫色。透过蓝色钴玻璃可减弱黄色干扰，便于观察钾的紫色焰色；焰色只能支持检出相应元素，不能唯一确定化合物。','先写“Na黄色可能干扰K紫色”，再选择能够减弱黄色干扰的观察方法。',
  'approved','IN','teacher_original',false,true,true
)
on conflict(id) do update set
  mother_id=excluded.mother_id,skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,
  stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,
  scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',
  usable_for_class_quiz=false,usable_for_review=true,usable_for_exam_sprint=true,updated_at=now();

insert into public.chem_questions(
  id,mother_id,skill_id,level,grade_band,stem,options,correct_option,explanation,scaffold,review_status,scope_status,source_kind,
  usable_for_class_quiz,usable_for_review,usable_for_exam_sprint
) values (
  'QCOMP_H1_NACL_06','MCOMP_H1_NACL_06','H1_NACL',3,'高一',
  'Cl₂与热的浓NaOH溶液反应时，含氯产物Cl⁻与ClO₃⁻的物质的量之比为','["1∶1","1∶5","3∶1","5∶1"]'::jsonb,3,'ClO₃⁻中的Cl由0升到+5，1个Cl失5e⁻；Cl⁻中的Cl由0降到-1，5个Cl共得5e⁻，因此Cl⁻∶ClO₃⁻=5∶1。完整离子方程式为3Cl₂+6OH⁻=5Cl⁻+ClO₃⁻+3H₂O。','分别写0→+5和0→-1，先用电子守恒定两种含氯产物的比例。',
  'approved','IN','teacher_original',false,true,true
)
on conflict(id) do update set
  mother_id=excluded.mother_id,skill_id=excluded.skill_id,level=excluded.level,grade_band=excluded.grade_band,
  stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,
  scaffold=excluded.scaffold,review_status='approved',scope_status='IN',source_kind='teacher_original',
  usable_for_class_quiz=false,usable_for_review=true,usable_for_exam_sprint=true,updated_at=now();

do $verify$
declare
  complete_cards integer;
  classification_complete boolean;
  complete_questions integer;
  invalid_questions integer;
begin
  select exists (
    select 1
    from public.chem_knowledge_cards
    where id = 'KC_H1_CLASSIFY' and skill_id = 'H1_CLASSIFY' and review_status = 'approved'
      and exists (
        select 1 from jsonb_array_elements(coalesce(structured_content->'sections', '[]'::jsonb)) entry
        where entry->>'title' = '四类基本反应与横向分类'
          and jsonb_array_length(coalesce(entry->'items', '[]'::jsonb)) >= 4
      )
  ) into classification_complete;

  select count(*) into complete_cards
  from public.chem_knowledge_cards
  where skill_id = any(array['H1_PERIODIC','H1_NACL','H1_REDOX','H1_ELECTROLYTE','H1_MOLE','H2_RATE','H2_EQUIL','H2_PH_HYDRO','H2_ELECTRO','H3_STOICH','H3_INORGANIC','H3_THERMO_RATE','H3_EQUILIBRIUM','H3_AQ','H3_ELECTRO','H3_EXPERIMENT','H3_STRUCTURE','H3_ORGANIC'])
    and id = 'KC_' || skill_id
    and review_status = 'approved'
    and jsonb_array_length(coalesce(structured_content->'sections','[]'::jsonb)) >= 5
    and not exists (
      select 1
      from jsonb_array_elements(structured_content->'sections') section_value
      cross join lateral jsonb_array_elements(section_value->'items') item_value
      where jsonb_array_length(coalesce(item_value->'examples','[]'::jsonb)) = 0
         or jsonb_array_length(coalesce(item_value->'visualSteps','[]'::jsonb)) < 2
    );

  select count(*), count(*) filter (
    where jsonb_array_length(options) <> 4
       or correct_option < 0 or correct_option > 3
       or review_status <> 'approved' or scope_status <> 'IN'
       or usable_for_class_quiz or not usable_for_review or not usable_for_exam_sprint
  ) into complete_questions, invalid_questions
  from public.chem_questions
  where id = any(array['QCOMP_H1_PERIODIC_01','QCOMP_H1_PERIODIC_02','QCOMP_H1_PERIODIC_03','QCOMP_H1_PERIODIC_04','QCOMP_H1_PERIODIC_05','QCOMP_H1_PERIODIC_06','QCOMP_H1_PERIODIC_07','QCOMP_H1_PERIODIC_08','QCOMP_H1_PERIODIC_09','QCOMP_H1_PERIODIC_10','QCOMP_H1_PERIODIC_11','QCOMP_H1_PERIODIC_12','QCOMP_H1_PERIODIC_13','QCOMP_H1_PERIODIC_14','QCOMP_H1_PERIODIC_15','QCOMP_H1_PERIODIC_16','QCOMP_H1_NACL_01','QCOMP_H1_NACL_02','QCOMP_H1_NACL_03','QCOMP_H1_NACL_04','QCOMP_H2_EQUIL_01','QCOMP_H2_EQUIL_02','QCOMP_H2_EQUIL_03','QCOMP_H2_EQUIL_04','QCOMP_H2_ELECTRO_01','QCOMP_H2_ELECTRO_02','QCOMP_H2_ELECTRO_03','QCOMP_H2_ELECTRO_04','QCOMP_H3_INORGANIC_01','QCOMP_H3_INORGANIC_02','QCOMP_H3_INORGANIC_03','QCOMP_H3_INORGANIC_04','QCOMP_H3_THERMO_RATE_01','QCOMP_H3_THERMO_RATE_02','QCOMP_H3_THERMO_RATE_03','QCOMP_H3_THERMO_RATE_04','QCOMP_H3_ELECTRO_01','QCOMP_H3_ELECTRO_02','QCOMP_H3_ELECTRO_03','QCOMP_H3_ELECTRO_04','QCOMP_H3_EXPERIMENT_01','QCOMP_H3_EXPERIMENT_02','QCOMP_H3_EXPERIMENT_03','QCOMP_H3_EXPERIMENT_04','QCOMP_H3_STRUCTURE_01','QCOMP_H3_STRUCTURE_02','QCOMP_H3_STRUCTURE_03','QCOMP_H3_STRUCTURE_04','QCOMP_H3_ORGANIC_01','QCOMP_H3_ORGANIC_02','QCOMP_H3_ORGANIC_03','QCOMP_H3_ORGANIC_04','QCOMP_H1_REDOX_01','QCOMP_H1_REDOX_02','QCOMP_H1_ELECTROLYTE_01','QCOMP_H1_MOLE_01','QCOMP_H3_STOICH_01','QCOMP_H2_RATE_01','QCOMP_H2_PH_HYDRO_01','QCOMP_H2_PH_HYDRO_02','QCOMP_H3_AQ_01','QCOMP_H3_EQUILIBRIUM_01','QCOMP_H3_EQUILIBRIUM_02','QCOMP_H2_EQUIL_05','QCOMP_H2_EQUIL_06','QCOMP_H2_ELECTRO_05','QCOMP_H3_ELECTRO_05','QCOMP_H3_INORGANIC_05','QCOMP_H3_INORGANIC_06','QCOMP_H3_INORGANIC_07','QCOMP_H3_EXPERIMENT_05','QCOMP_H3_EXPERIMENT_06','QCOMP_H3_EXPERIMENT_07','QCOMP_H3_STRUCTURE_05','QCOMP_H3_STRUCTURE_06','QCOMP_H3_STRUCTURE_07','QCOMP_H3_STRUCTURE_08','QCOMP_H3_ORGANIC_05','QCOMP_H3_ORGANIC_06','QCOMP_H3_ORGANIC_07','QCOMP_H3_ORGANIC_08','QCOMP_H3_ORGANIC_09','QCOMP_H3_ORGANIC_10','QCOMP_H3_ORGANIC_11','QCOMP_H3_ORGANIC_12','QCOMP_H1_NACL_05','QCOMP_H1_NACL_06']);

  if complete_cards <> 18 then
    raise exception 'Expected 18 complete cards, found %', complete_cards;
  end if;
  if not classification_complete then
    raise exception 'H1_CLASSIFY P1 verification failed';
  end if;
  if complete_questions <> 87 or invalid_questions <> 0 then
    raise exception 'Question verification failed: found %, invalid %', complete_questions, invalid_questions;
  end if;
end
$verify$;
